import re, math
from decimal import Decimal

# Value kinds
EMPTY='empty'; ABSENT='absent'; NULL='null'; ERROR='error'; STRING='string'; INT='int'; FLOAT='float'; BOOL='bool'; ARRAY='array'; MAP='map'

INT64_MIN=-(2**63); INT64_MAX=2**63-1
def wrap_int64(n):
    n = int(n) & ((1<<64)-1)
    if n >= 2**63: n -= 2**64
    return n

class MMap:
    """Ordered map with Value keys. Internal dict keyid -> (keyV, valV)"""
    def __init__(self):
        self.d={}
    def __len__(self): return len(self.d)
    def __bool__(self): return len(self.d)>0
    def key_id(self, kv):
        return freeze_key(kv)
    def set(self, kv, v):
        kid=freeze_key(kv)
        if kid in self.d:
            oldk,_=self.d[kid]
            self.d[kid]=(oldk, v)
        else:
            self.d[kid]=(kv, v)
    def get(self, kv, default=None):
        e=self.d.get(freeze_key(kv))
        return e[1] if e else (default if default is not None else VAbsent())
    def has(self, kv): return freeze_key(kv) in self.d
    def delete(self, kv):
        self.d.pop(freeze_key(kv), None)
    def items(self): return list(self.d.values())
    def keys(self): return [k for k,v in self.d.values()]
    def values_list(self): return [v for k,v in self.d.values()]
    def copy(self):
        m=MMap(); 
        for k,v in self.items(): m.set(k, v.copy())
        return m
    # string-key helpers
    def set_str(self, s, v): self.set(VString(s) if s!="" else VEmpty(), v)
    def get_str(self, s, default=None):
        return self.get(VString(s) if s!="" else VEmpty(), default)

def freeze_key(v):
    # for map keys: Miller uses stringified? int 1 and string "1" distinct? We'll use (kind, value) but int/float 1 vs 1.0 ?
    # For record access keys are strings.
    if v.kind==INT: return ('int', v.val)
    if v.kind==FLOAT: return ('float', v.val)
    if v.kind==BOOL: return ('bool', v.val)
    if v.kind in (STRING,EMPTY): return ('str', v.to_plain_string() if hasattr(v,'to_plain_string') else '')
    if v.kind==NULL: return ('null',)
    # fallback stringify
    return ('str', v.to_string())

def freeze(v):
    """hashable representation for grouping/equality of values (including collections)"""
    if v.kind==INT: return ('num', float(v.val)) if False else ('int', v.val)
    if v.kind==FLOAT:
        # nan handling
        if math.isnan(v.val): return ('float','nan')
        return ('float', v.val)
    if v.kind==BOOL: return ('bool', v.val)
    if v.kind in (STRING,EMPTY): return (v.kind, v.val if v.kind==STRING else '')
    if v.kind==ARRAY: return ('array', tuple(freeze(x) for x in v.val))
    if v.kind==MAP: return ('map', tuple((freeze_key(k), freeze(val)) for k,val in v.val.items()))
    return (v.kind,)

class Value:
    __slots__=('kind','val','orig','errmsg')
    def __init__(self, kind, val=None, orig=None, errmsg=None):
        self.kind=kind; self.val=val; self.orig=orig; self.errmsg=errmsg
    def copy(self):
        if self.kind==ARRAY:
            return Value(ARRAY, [x.copy() for x in self.val])
        if self.kind==MAP:
            return Value(MAP, self.val.copy())
        return Value(self.kind, self.val, self.orig, self.errmsg)
    def __repr__(self):
        return f"V({self.kind},{self.val!r},orig={self.orig!r})"
    def is_void(self):
        return self.kind in (EMPTY, ABSENT)  # null considered? separate
    def is_numeric(self):
        return self.kind in (INT,FLOAT)
    def to_plain_string(self):
        if self.kind==STRING: return self.val
        if self.kind==EMPTY: return ''
        return self.to_string()
    def to_string(self, ofmt=None):
        k=self.kind
        if k==EMPTY: return ''
        if k==ABSENT: return ''
        if k==NULL: return 'null'
        if k==ERROR: return '(error)'
        if k==BOOL: return 'true' if self.val else 'false'
        if k==INT:
            if self.orig is not None: return self.orig
            return str(self.val)
        if k==FLOAT:
            if ofmt: return format_with_ofmt(self.val, ofmt)
            if self.orig is not None: return self.orig
            return format_float(self.val)
        if k==STRING: return self.val
        if k in (ARRAY,MAP):
            return json_stringify(self, vstack=True, ofmt=ofmt)
        return str(self.val)
    def to_number(self):
        """return (is_int, numeric value) or None"""
        if self.kind==INT: return (True, self.val)
        if self.kind==FLOAT: return (False, self.val)
        return None
    def as_float(self):
        if self.kind==INT: return float(self.val)
        if self.kind==FLOAT: return self.val
        raise ValueError('not numeric')
    def as_int(self):
        if self.kind==INT: return self.val
        if self.kind==FLOAT: return int(self.val)  # trunc toward zero? Go conversion
        raise ValueError('not numeric')

def VEmpty(): return Value(EMPTY,'')
def VAbsent(): return Value(ABSENT)
def VNull(): return Value(NULL)
def VError(msg=''): return Value(ERROR, errmsg=msg)
def VBool(b): return Value(BOOL, bool(b))
def VInt(n, orig=None): return Value(INT, wrap_int64(n), orig=orig)
def VFloat(f, orig=None): return Value(FLOAT, float(f), orig=orig)
def VString(s):
    if s=='': return Value(EMPTY,'')
    return Value(STRING, s)
def VArray(lst): return Value(ARRAY, list(lst))
def VMap(m=None):
    if m is None: m=MMap()
    return Value(MAP, m)

def format_float(f):
    if math.isnan(f): return 'NaN'
    if math.isinf(f): return '+Inf' if f>0 else '-Inf'
    # shortest repr
    if f==0.0:
        # preserve sign? Go FormatFloat -0 -> '-0'
        return '-0' if math.copysign(1,f)<0 else '0'
    r=repr(float(f))  # python shortest
    if 'e' in r or 'E' in r:
        # expand to fixed
        d=Decimal(r)
        s=format(d,'f')
        return s
    else:
        if r.endswith('.0'):
            return r[:-2]
        return r

def format_with_ofmt(f, ofmt):
    # ofmt is a single printf-style directive e.g. %.18f %9.6e %.6g
    # Miller uses Go fmt.Sprintf(ofmt, f)
    if f is None: return ''
    # handle Inf/NaN Go style: Sprintf %.2f with Inf -> +Inf ? Go: %f of +Inf gives +Inf
    try:
        # python % formatting is close
        # Go %g exponent format: e+00 vs python e+00 similar? Python %g uses e+00? check: '%g'%1e20 = '1e+20'
        # Go %.6g same-ish.
        s = ofmt % f
        # Python produces 'inf'/'-inf'/'nan' ; Go produces +Inf/-Inf/NaN with width padding etc approximate
        if math.isnan(f):
            # try keep width?
            s = ofmt % 0.0  # placeholder to get width? simpler replace
            s = s.replace('0','',0) # not good
            # reconstruct: strip
            return _go_special(ofmt, 'NaN', f)
        if math.isinf(f):
            return _go_special(ofmt, '+Inf' if f>0 else '-Inf', f)
        # Go %e exponent min 2 digits; python already 2 digits.
        # Go %g removes trailing zeros similar.
        return s
    except Exception:
        return format_float(f)

def _go_special(ofmt, txt, f):
    m=re.search(r'%([0-9]*)(?:\.[0-9]*)?[a-zA-Z]', ofmt)
    width=0
    if m and m.group(1):
        try: width=int(m.group(1))
        except: pass
    if width>len(txt):
        return ' '*(width-len(txt))+txt
    return txt

# ---------- inference ----------
_int_digits_re=re.compile(r'^[+-]?[0-9]+$')
_float_re=re.compile(r'^[+-]?(?:[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)(?:[eE][+-]?[0-9]+)?$')

def infer_value(s, opts=None):
    """opts dict with infer_none, infer_int_as_float, infer_octal"""
    if opts is None: opts={}
    if s=='' or s is None:
        return VEmpty()
    if opts.get('infer_none'):
        return VString(s)
    # int attempt
    v=_try_int(s, opts)
    if v is not None:
        if opts.get('infer_int_as_float'):
            return VFloat(float(v.val), orig=s)
        return v
    # if digits only (overflow or leading zero non-octal) -> string (not float)
    if _int_digits_re.match(s):
        # check leading zero cases already handled returning None, and overflow
        return VString(s)
    # float attempt requires dot or exponent
    if ('.' in s or 'e' in s or 'E' in s) and _float_re.match(s):
        try:
            f=float(s)
        except:
            return VString(s)
        if math.isinf(f):
            return VString(s)
        return VFloat(f, orig=s)
    return VString(s)

def _try_int(s, opts):
    t=s
    sign=1
    if t[:1] in ('+','-'):
        if t[0]=='-': sign=-1
        body=t[1:]
    else:
        body=t
    if body=='' : return None
    low=body.lower()
    try:
        if low.startswith('0x'):
            digits=body[2:]
            if digits and all(c in '0123456789abcdefABCDEF' for c in digits):
                n=sign*int(digits,16)
                if INT64_MIN<=n<=INT64_MAX: return VInt(n, orig=s)
            return None
        if low.startswith('0b'):
            digits=body[2:]
            if digits and all(c in '01' for c in digits):
                n=sign*int(digits,2)
                if INT64_MIN<=n<=INT64_MAX: return VInt(n, orig=s)
            return None
        if low.startswith('0o'):
            digits=body[2:]
            if digits and all(c in '01234567' for c in digits):
                n=sign*int(digits,8)
                if INT64_MIN<=n<=INT64_MAX: return VInt(n, orig=s)
            return None
    except:
        return None
    if body.isdigit():
        if len(body)>1 and body[0]=='0':
            if opts.get('infer_octal'):
                if all(c in '01234567' for c in body):
                    n=sign*int(body,8)
                else:
                    n=sign*int(body,10)
                if INT64_MIN<=n<=INT64_MAX: return VInt(n, orig=s)
                return None
            else:
                return None
        n=sign*int(body,10)
        if INT64_MIN<=n<=INT64_MAX: return VInt(n, orig=s)
        return None
    return None

def parse_int_literal(tok):
    """DSL int literal: Go-like base0 with wrap"""
    s=tok
    sign=1
    # literal tokens from lexer won't include sign (unary handled)
    low=s.lower()
    try:
        if low.startswith('0x'):
            n=int(s[2:],16)
        elif low.startswith('0b'):
            n=int(s[2:],2)
        elif low.startswith('0o'):
            n=int(s[2:],8)
        elif len(s)>1 and s[0]=='0' and s.isdigit():
            # octal if all 0-7 else decimal? DSL 077 ->63, 01->1, 08? test later assume octal attempt else decimal
            if all(c in '01234567' for c in s):
                n=int(s,8)
            else:
                n=int(s,10)
        else:
            n=int(s,10)
    except:
        n=0
    return VInt(n, orig=tok)

# ---------- JSON stringify ----------
import json as _json
def json_escape_str(s):
    # Go-like: use python json with ensure_ascii=False but don't escape /? python fine
    return _json.dumps(s, ensure_ascii=False)

def json_stringify(v, vstack=True, ofmt=None, indent_level=0, quote_all=False):
    k=v.kind
    if quote_all:
        # all scalars as strings recursively
        if k not in (ARRAY,MAP):
            if k==NULL:
                return json_escape_str('null')
            return json_escape_str(v.to_string(ofmt))
    if k==NULL: return 'null'
    if k==EMPTY: return '""'
    if k==ABSENT: return 'null'  # ??
    if k==ERROR: return '(error)'
    if k==BOOL: return 'true' if v.val else 'false'
    if k==INT:
        return v.to_string(ofmt)
    if k==FLOAT:
        # JSON output for inf/nan: Go Miller prints +Inf/NaN as-is (invalid json)
        return v.to_string(ofmt)
    if k==STRING: return json_escape_str(v.val)
    if k==ARRAY:
        if len(v.val)==0: return '[]'
        if not vstack:
            return '['+', '.join(json_stringify(x, vstack=False, ofmt=ofmt, indent_level=indent_level, quote_all=quote_all) for x in v.val)+']'
        # stacked if any element is non-scalar (map/array non-empty?)
        has_complex=any(x.kind in (ARRAY,MAP) for x in v.val)
        if not has_complex:
            return '['+', '.join(json_stringify(x, vstack=True, ofmt=ofmt, indent_level=indent_level, quote_all=quote_all) for x in v.val)+']'
        indent='  '*indent_level
        inner_indent='  '*(indent_level+1)
        parts=[]
        for x in v.val:
            parts.append(inner_indent+json_stringify(x, vstack=True, ofmt=ofmt, indent_level=indent_level+1, quote_all=quote_all))
        return '[\n'+',\n'.join(parts)+'\n'+indent+']'
    if k==MAP:
        items=v.val.items()
        if len(items)==0: return '{}'
        if not vstack:
            parts=[json_escape_str(key_v.to_string())+': '+json_stringify(val, vstack=False, ofmt=ofmt, indent_level=indent_level, quote_all=quote_all) for key_v,val in items]
            return '{'+', '.join(parts)+'}'
        indent='  '*indent_level
        inner_indent='  '*(indent_level+1)
        parts=[]
        for key_v,val in items:
            parts.append(inner_indent+json_escape_str(key_v.to_string())+': '+json_stringify(val, vstack=True, ofmt=ofmt, indent_level=indent_level+1, quote_all=quote_all))
        return '{\n'+',\n'.join(parts)+'\n'+indent+'}'
    return json_escape_str(v.to_string(ofmt))

# ---------- comparison ----------
def values_equal(a,b):
    # Miller == semantics: returns bool or absent/error? Caller handling in DSL ops.
    # Here python bool for internal use (grouping etc uses freeze)
    if a.kind in (INT,FLOAT) and b.kind in (INT,FLOAT):
        return a.as_float()==b.as_float() if (a.kind==FLOAT or b.kind==FLOAT) else a.val==b.val
    if a.kind!=b.kind:
        # empty vs string "" - empty is string "" caninical; empty vs absent? false
        if set([a.kind,b.kind])=={EMPTY,STRING}:
            return a.to_plain_string()==b.to_plain_string()
        return False
    if a.kind==ARRAY:
        return len(a.val)==len(b.val) and all(values_equal(x,y) for x,y in zip(a.val,b.val))
    if a.kind==MAP:
        ai=a.val.items(); bi=b.val.items()
        if len(ai)!=len(bi): return False
        # maps equal regardless order? test later; assume set equality
        bd={}
        for k,v in bi: bd[freeze_key(k)]=v
        for k,v in ai:
            bv=bd.get(freeze_key(k))
            if bv is None or not values_equal(v,bv): return False
        return True
    if a.kind in (EMPTY,ABSENT,NULL): return a.kind==b.kind
    return a.val==b.val

def compare_values(a,b):
    """for sort etc: return -1,0,1 or None if incomparable. Lexical/string vs numeric handling at caller"""
    if a.kind in (INT,FLOAT) and b.kind in (INT,FLOAT):
        av=a.as_float() if (a.kind==FLOAT or b.kind==FLOAT) else a.val
        bv=b.as_float() if (a.kind==FLOAT or b.kind==FLOAT) else b.val
        # NaN?
        if isinstance(av,float) and math.isnan(av): return -1
        if isinstance(bv,float) and math.isnan(bv): return 1
        return (av>bv)-(av<bv)
    # string comparison on stringified
    as_ = a.to_string(); bs_ = b.to_string()
    return (as_>bs_)-(as_<bs_)

def type_name(v):
    return v.kind

