            bv=bd.get(freeze_key(k))
            if bv is None or not values_equal(v,bv): return False
        return True
    if a.kind in (EMPTY,ABSENT,NULL): return a.kind==b.kind
    return a.val==b.val

def compare_values(a,b):
    """for sort etc: return -1,0,1 or None if incomparable. Lexical/string vs numeric handling at caller"""
    if a.kind in (INT,FLOAT) and b.kind in (INT,FLOAT):
        av=a.as_float() if (a.kind==FLOAT or b.kind==FLOAT) else a.val
        bv=b.as_float() if (a.kind==FLOAT or b.kind==FLOAT) else b.val
        # NaN?
        if isinstance(av,float) and math.isnan(av): return -1
        if isinstance(bv,float) and math.isnan(bv): return 1
        return (av>bv)-(av<bv)
    # string comparison on stringified
    as_ = a.to_string(); bs_ = b.to_string()
    return (as_>bs_)-(as_<bs_)

def type_name(v):
    return v.kind

