    """Ordered map with canonical string keys (Miller maps stringify int keys)."""
    def __init__(self, d=None):
        from collections import OrderedDict
        self.d = d if d is not None else OrderedDict()
    def __len__(self): return len(self.d)
    def __bool__(self): return len(self.d)>0
    def set(self, kv, v):
        self.d[canonical_key(kv)] = v
    def get(self, kv, default=None):
        try: k=canonical_key(kv)
        except Exception: return default if default is not None else VAbsent()
        if k in self.d: return self.d[k]
        return default if default is not None else VAbsent()
    def has(self, kv):
        try: return canonical_key(kv) in self.d
        except Exception: return False
    def delete(self, kv):
        try: self.d.pop(canonical_key(kv), None)
        except Exception: pass
    def items(self): return [(VString(k) if k!="" else VEmpty(), v) for k,v in self.d.items()]
    def keys(self): return [VString(k) if k!="" else VEmpty() for k in self.d.keys()]
    def keys_str(self): return list(self.d.keys())
    def values_list(self): return list(self.d.values())
    def copy(self):
        from collections import OrderedDict
        return MMap(OrderedDict((k, v.copy()) for k,v in self.d.items()))
    def set_str(self, s, v): self.d[s]=v
    def get_str(self, s, default=None):
        if s in self.d: return self.d[s]
        return default if default is not None else VAbsent()

def canonical_key(kv):
    if kv.kind==INT: return str(kv.val)
    if kv.kind==STRING: return kv.val
    if kv.kind==EMPTY: return ''
    if kv.kind==FLOAT: return kv.to_string()
    if kv.kind==BOOL: return 'true' if kv.val else 'false'
    if kv.kind==NULL: return 'null'
    raise ValueError('invalid key type '+kv.kind)

def freeze_key(v):
    try: return ('str', canonical_key(v))
    except Exception: return ('str', v.to_string())

'''
