import re, math, os, sys, time
from mlrval import *
from errors import MlrError, MlrRawError

KEYWORDS={'all','begin','bool','break','call','continue','do','dump','edump','elif','else','emit1','emit','emitf','emitp','end','eprint','eprintn','false','filter','float','for','func','funct','if','in','int','map','num','print','printn','return','stderr','stdout','str','subr','tee','true','unset','var','while','arr'}
TYPES={'var','int','float','num','str','bool','map','arr','funct'}
CONTEXT_VARS={'ENV','FILENAME','FILENUM','FNR','IFS','IPS','IRS','M_E','M_PI','NF','NR','OFS','OPS','ORS','FLATSEP'}

_funct_counter=[0]
def _next_funct_name():
    _funct_counter[0]+=1
    return f"function-literal-{_funct_counter[0]:06d}"

class Token:
    __slots__=('type','text','line','col','value')
    def __init__(self,type,text,line,col,value=None):
        self.type=type; self.text=text; self.line=line; self.col=col; self.value=value
    def __repr__(self): return f"Tok({self.type},{self.text!r}@{self.line}:{self.col})"

class ParseError(Exception):
    def __init__(self, token, msg=None):
        self.token=token
        self.msg=msg or f'Parse error on token "{token.text}" at line {token.line} column {token.col}.'
    def format(self):
        return f"mlr: cannot parse DSL expression.\nmlr: {self.msg}\nPlease check for missing semicolon.\n"

_name_start=re.compile(r'[^\W\d_]', re.UNICODE)
_name_char=re.compile(r'\w', re.UNICODE)

def decode_string_raw(raw):
    """raw is content between quotes (with backslash escapes as in source).
    Returns decoded string where Go escapes decoded, regex escapes kept, \\1..\\9 kept."""
    out=[]
    i=0
    while i < len(raw):
        c=raw[i]
        if c!='\\':
            out.append(c); i+=1; continue
        if i+1>=len(raw):
            out.append('\\'); break
        nxt=raw[i+1]
        if nxt=='a': out.append('\a'); i+=2
        elif nxt=='b': out.append('\b'); i+=2
        elif nxt=='f': out.append('\f'); i+=2
        elif nxt=='n': out.append('\n'); i+=2
        elif nxt=='r': out.append('\r'); i+=2
        elif nxt=='t': out.append('\t'); i+=2
        elif nxt=='v': out.append('\v'); i+=2
        elif nxt=='\\': out.append('\\'); i+=2
        elif nxt=='"': out.append('"'); i+=2
        elif nxt=='x' and i+3<len(raw)+0 and i+3<=len(raw)-1+1 and len(raw)>=i+4 and all(ch in '0123456789abcdefABCDEF' for ch in raw[i+2:i+4]):
            out.append(chr(int(raw[i+2:i+4],16))); i+=4
        elif nxt=='u' and len(raw)>=i+6 and all(ch in '0123456789abcdefABCDEF' for ch in raw[i+2:i+6]):
            out.append(chr(int(raw[i+2:i+6],16))); i+=6
        elif nxt=='U' and len(raw)>=i+10 and all(ch in '0123456789abcdefABCDEF' for ch in raw[i+2:i+10]):
            cp=int(raw[i+2:i+10],16)
            out.append(chr(cp) if cp<=0x10FFFF else ''); i+=10
        elif nxt in '01234567' and i+3 < len(raw)+1 and len(raw)>=i+4 and all(ch in '01234567' for ch in raw[i+1:i+4]) and nxt!='0' or (nxt in '01234567' and len(raw)>=i+4 and raw[i+1:i+4].isdigit() and all(ch in '01234567' for ch in raw[i+1:i+4])):
            # 3-digit octal
            try:
                out.append(chr(int(raw[i+1:i+4],8))); i+=4
            except:
                out.append('\\'+nxt); i+=2
        else:
            out.append('\\'+nxt); i+=2
    return ''.join(out)

_ALLOWED_ESCAPE_CHARS=set('abdfnrstvwxuU0123456789\\"$.*+?()[]{}|^eEpPbBsSwWdDzZGA') 
# note: be permissive except explicitly bad ones observed: q - / ' 
_BAD_ESCAPES=set("q-/'")

def lex(src):
    tokens=[]
    i=0; line=1; col=1
    n=len(src)
    def adv(k=1):
        nonlocal i,line,col
        for _ in range(k):
            if i<n and src[i]=='\n': line+=1; col=1
            else: col+=1
            i+=1
    while i<n:
        c=src[i]
        if c in ' \t\r': adv(); continue
        if c=='\n': adv(); continue
        if c=='#':
            while i<n and src[i]!='\n': adv()
            continue
        start_line, start_col=line,col
        # strings
        if c=='"':
            j=i+1; rawchars=[]
            ok=False
            while j<n:
                ch=src[j]
                if ch=='\\':
                    if j+1<n and src[j+1] in _BAD_ESCAPES:
                        # create a bogus token to trigger parse error roughly like reference
                        # consume up to bad escape inclusive for token text
                        badtext=src[i:j+2]
                        tokens.append(Token('BADSTRING', badtext, start_line, start_col))
                        # advance to j+2
                        while i<j+2: adv()
                        ok=True # marked so we don't treat as string below; use flag
                        rawchars=None
                        break
                    if j+1<n:
                        rawchars.append(src[j:j+2]); j+=2; continue
                    else:
                        break
                elif ch=='"':
                    ok=True; break
                elif ch=='\n':
                    break
                else:
                    rawchars.append(ch); j+=1
            if rawchars is None:
                continue
            if not ok:
                tokens.append(Token('BADSTRING', src[i:j], start_line, start_col))
                while i<j: adv()
                continue
            raw=''.join(rawchars)
            # closing quote at j
            is_ci=False
            end=j+1
            if end<n and src[end]=='i' and (end+1>=n or not (src[end+1].isalnum() or src[end+1]=='_')):
                is_ci=True; end+=1
            text=src[i:end]
            while i<end: adv()
            if is_ci:
                tokens.append(Token('STRINGCI', text, start_line, start_col, value=text))
            else:
                tokens.append(Token('STRING', text, start_line, start_col, value=decode_string_raw(raw)))
            continue
        # $ field forms
        if c=='$':
            if src.startswith('$[[[', i):
                tokens.append(Token('$[[[','$[[[',start_line,start_col)); adv(4); continue
            if src.startswith('$[[', i):
                tokens.append(Token('$[[','$[[',start_line,start_col)); adv(3); continue
            if src.startswith('$[', i):
                tokens.append(Token('$[','$[',start_line,start_col)); adv(2); continue
            if src.startswith('$*', i):
                tokens.append(Token('$*','$*',start_line,start_col)); adv(2); continue
            if src.startswith('${', i):
                end=src.find('}', i+2)
                if end==-1:
                    tokens.append(Token('BAD',src[i:],start_line,start_col)); adv(n-i); continue
                name=src[i+2:end]
                text=src[i:end+1]
                while i<=end: adv()
                tokens.append(Token('FIELD', text, start_line, start_col, value=name)); continue
            # $name : letters/digits/underscore, may start with digit
            j=i+1
            if j<n and (_name_char.match(src[j]) ):
                while j<n and _name_char.match(src[j]): j+=1
                name=src[i+1:j]; text=src[i:j]
                while i<j: adv()
                tokens.append(Token('FIELD', text, start_line, start_col, value=name)); continue
            tokens.append(Token('$','$',start_line,start_col)); adv(); continue
        # @ oosvar forms
        if c=='@':
            if src.startswith('@[[[', i):
                tokens.append(Token('@[[[','@[[[',start_line,start_col)); adv(4); continue
            if src.startswith('@[[', i):
                tokens.append(Token('@[[','@[[',start_line,start_col)); adv(3); continue
            if src.startswith('@[', i):
                tokens.append(Token('@[','@[',start_line,start_col)); adv(2); continue
            if src.startswith('@*', i):
                tokens.append(Token('@*','@*',start_line,start_col)); adv(2); continue
            if src.startswith('@{', i):
                end=src.find('}', i+2)
                if end==-1:
                    tokens.append(Token('BAD',src[i:],start_line,start_col)); adv(n-i); continue
                name=src[i+2:end]; text=src[i:end+1]
                while i<=end: adv()
                tokens.append(Token('OOSVAR', text, start_line, start_col, value=name)); continue
            j=i+1
            if j<n and (_name_start.match(src[j]) or src[j]=='_'):
                while j<n and _name_char.match(src[j]): j+=1
                name=src[i+1:j]; text=src[i:j]
                while i<j: adv()
                tokens.append(Token('OOSVAR', text, start_line, start_col, value=name)); continue
            # invalid like @1 : make token @1 as BAD-ish field to trigger parse error
            j=i+1
            while j<n and _name_char.match(src[j]): j+=1
            text=src[i:j] if j>i+1 else '@'
            tokens.append(Token('BAD', text, start_line, start_col))
            while i<j: adv()
            if j==i: adv()
            continue
        # numbers
        if c.isdigit() or (c=='.' and i+1<n and src[i+1].isdigit()):
            # hex/binary/octal int?
            if c=='0' and i+1<n and src[i+1] in 'xXbBoO':
                j=i+2
                kind=src[i+1].lower()
                allowed='0123456789abcdefABCDEF' if kind=='x' else ('01' if kind=='b' else '01234567')
                while j<n and src[j] in allowed: j+=1
                text=src[i:j]
                while i<j: adv()
                tokens.append(Token('INT',text,start_line,start_col,value=text)); continue
            j=i; is_float=False
            while j<n and src[j].isdigit(): j+=1
            if j<n and src[j]=='.':
                # need lookahead: dot is part of number if ... 1. or 1.5 ; but 1 . 5 has spaces. '1.' followed by non-digit is float token per reference.
                is_float=True; j+=1
                while j<n and src[j].isdigit(): j+=1
            if j<n and src[j] in 'eE':
                k=j+1
                if k<n and src[k] in '+-': k+=1
                if k<n and src[k].isdigit():
                    is_float=True; j=k
                    while j<n and src[j].isdigit(): j+=1
            if c=='.':
                is_float=True
                # j started at i, need rescan
                j=i+1
                while j<n and src[j].isdigit(): j+=1
                if j<n and src[j] in 'eE':
                    k=j+1
                    if k<n and src[k] in '+-': k+=1
                    if k<n and src[k].isdigit():
                        j=k
                        while j<n and src[j].isdigit(): j+=1
            text=src[i:j]
            while i<j: adv()
            tokens.append(Token('FLOAT' if is_float else 'INT',text,start_line,start_col,value=text)); continue
        # names / keywords
        if _name_start.match(c) or c=='_':
            j=i
            while j<n and _name_char.match(src[j]): j+=1
            text=src[i:j]
            while i<j: adv()
            tokens.append(Token('NAME',text,start_line,start_col,value=text)); continue
        # operators / punctuation - longest match
        # bracket runs
        if c=='[':
            if src.startswith('[[[', i):
                tokens.append(Token('[[[','[[[',start_line,start_col)); adv(3); continue
            if src.startswith('[[', i):
                tokens.append(Token('[[','[[',start_line,start_col)); adv(2); continue
            tokens.append(Token('[','[',start_line,start_col)); adv(); continue
        ops=['>>>=' ,'???=','>>>','>>=','<<=','**=','//=','??=','???','<=>','==','!=~','=~','!=','>=','<=','>>','<<','**','//','??','||=','&&=','^^=','||','&&','^^','+=','-=','*=','/=','%=','|=','&=','^=','.=','.+','.-','.*','./','.//']
        matched=None
        for op in ops:
            if src.startswith(op,i): matched=op; break
        if matched:
            tokens.append(Token(matched,matched,start_line,start_col)); adv(len(matched)); continue
        tokens.append(Token(c,c,start_line,start_col)); adv(); continue
    tokens.append(Token('EOF','',line,col))
    return tokens

