def decode_string_raw(raw):
    """raw is content between quotes (with backslash escapes as in source).
    Returns decoded string where Go escapes decoded, regex escapes kept, \\1..\\9 kept."""
    out=[]
    i=0
    while i < len(raw):
        c=raw[i]
        if c!='\\':
            out.append(c); i+=1; continue
        if i+1>=len(raw):
            out.append('\\'); break
        nxt=raw[i+1]
        if nxt=='a': out.append('\a'); i+=2
        elif nxt=='b': out.append('\b'); i+=2
        elif nxt=='f': out.append('\f'); i+=2
        elif nxt=='n': out.append('\n'); i+=2
        elif nxt=='r': out.append('\r'); i+=2
        elif nxt=='t': out.append('\t'); i+=2
        elif nxt=='v': out.append('\v'); i+=2
        elif nxt=='\\': out.append('\\'); i+=2
        elif nxt=='"': out.append('"'); i+=2
        elif nxt=='x' and i+3<len(raw)+0 and i+3<=len(raw)-1+1 and len(raw)>=i+4 and all(ch in '0123456789abcdefABCDEF' for ch in raw[i+2:i+4]):
            out.append(chr(int(raw[i+2:i+4],16))); i+=4
        elif nxt=='u' and len(raw)>=i+6 and all(ch in '0123456789abcdefABCDEF' for ch in raw[i+2:i+6]):
            out.append(chr(int(raw[i+2:i+6],16))); i+=6
        elif nxt=='U' and len(raw)>=i+10 and all(ch in '0123456789abcdefABCDEF' for ch in raw[i+2:i+10]):
            cp=int(raw[i+2:i+10],16)
            out.append(chr(cp) if cp<=0x10FFFF else ''); i+=10
        elif nxt in '01234567' and i+3 < len(raw)+1 and len(raw)>=i+4 and all(ch in '01234567' for ch in raw[i+1:i+4]) and nxt!='0' or (nxt in '01234567' and len(raw)>=i+4 and raw[i+1:i+4].isdigit() and all(ch in '01234567' for ch in raw[i+1:i+4])):
            # 3-digit octal
            try:
                out.append(chr(int(raw[i+1:i+4],8))); i+=4
            except:
                out.append('\\'+nxt); i+=2
        else:
