                self.advance(); self.expect('('); c=self.parse_expr(); self.expect(')'); b=self.parse_block()
                branches.append((c,b))
            elif self.is_name('else'):
                self.advance(); else_body=self.parse_block(); break
            else:
                break
        return Node('if', branches=branches, else_body=else_body)

    def _scan_for_kind(self):
        # at '(' token after for; scan balanced to find ';' or 'in' at depth 1
        depth=0; i=self.pos
        has_semi=False; has_in=False
        while i < len(self.tokens):
            t=self.tokens[i]
            if t.type in ('(','[','[[','[[[','{','$[','$[[','$[[[','@['):
                depth+=1
            elif t.type in (')',']','}'):
                depth-=1
                if depth==0: break
            elif depth==1 and t.type==';':
                has_semi=True
            elif depth==1 and t.type=='NAME' and t.text=='in':
                has_in=True
            i+=1
        return has_semi, has_in

    def parse_for(self):
        self.expect_name('for')
        has_semi, has_in=self._scan_for_kind()
        self.expect('(')
        if has_in and not has_semi:
            # for-in
            vars_list=[]
            multi=[]
            if self.cur().type=='(':
                self.advance()
                while True:
                    n=self._parse_loop_varname(); multi.append(n)
                    if not self.match(','): break
                self.expect(')'); self.expect(',')
                vname=self._parse_loop_varname()
                self.expect_name('in'); coll=self.parse_expr(); self.expect(')')
                body=self.parse_block()
                return Node('forinmulti', knames=multi, vname=vname, coll=coll, body=body)
            else:
                first=self._parse_loop_varname()
                second=None
                if self.match(','):
                    second=self._parse_loop_varname()
                self.expect_name('in'); coll=self.parse_expr(); self.expect(')')
                body=self.parse_block()
                return Node('forin', names=[first] if second is None else [first,second], coll=coll, body=body)
        else:
            # C-style
            init=self.parse_simple_list(stop=';')
            self.expect(';')
            cond=None
            if self.cur().type!=';':
                cond=self.parse_expr()
            self.expect(';')
            incr=self.parse_simple_list(stop=')')
            self.expect(')')
            body=self.parse_block()
            return Node('forc', init=init, cond=cond, incr=incr, body=body)

    def _parse_loop_varname(self):
        # optional type prefix
        if self.cur().type=='NAME' and self.cur().text in TYPES and self.peek(1).type=='NAME':
            self.advance()
        t=self.cur()
        if t.type!='NAME': raise ParseError(t)
        self.advance(); return t.text

    def parse_simple_list(self, stop):
        stmts=[]
        if self.cur().type==stop:
            return stmts
        while True:
            # decl?
            if self.cur().type=='NAME' and self.cur().text in TYPES and self.peek(1).type=='NAME' and self.peek(2).type in ASSIGN_OPS:
                stmts.append(self.parse_decl())
            else:
                expr=self.parse_expr()
                if self.cur().type in ASSIGN_OPS:
                    op=self.advance().type; rhs=self.parse_expr()
                    stmts.append(Node('assign', target=expr, op=op, rhs=rhs))
                else:
                    stmts.append(Node('exprstmt', expr=expr))
            if self.match(','):
                continue
            break
        return stmts

    def parse_funcdef(self, is_subr):
        kw=self.advance() # func/subr
        name_tok=self.cur()
        if name_tok.type!='NAME': raise ParseError(name_tok)
        self.advance()
        name=name_tok.text
        params=self.parse_params()
        rettype=None
        if self.match(':'):
            rt=self.cur()
            if rt.type!='NAME': raise ParseError(rt)
            rettype=rt.text; self.advance()
        body=self.parse_block()
        return Node('subrdef' if is_subr else 'funcdef', name=name, params=params, rettype=rettype, body=body)

    def parse_params(self):
        self.expect('(')
        params=[]
        if self.cur().type!=')':
            while True:
                vartype='var'
                if self.cur().type=='NAME' and self.cur().text in TYPES and self.peek(1).type=='NAME':
                    vartype=self.advance().text
                nt=self.cur()
                if nt.type!='NAME': raise ParseError(nt)
                self.advance(); params.append((vartype, nt.text))
                if not self.match(','): break
        self.expect(')')
        return params

    def parse_arg_list(self):
        args=[]
        if self.cur().type==')':
            return args
        while True:
            args.append(self.parse_expr())
            if not self.match(','): break
        return args

    def parse_redirect_dest(self):
        t=self.cur()
        if t.type=='NAME' and t.text in ('stderr','stdout'):
            self.advance(); return Node('redirname', name=t.text)
        return self.parse_expr()

    def parse_print(self):
        kw=self.advance().text
        redir=None; args=[]
        if self.cur().type in ('>','>>','|'):
            op=self.advance().type; dest=self.parse_redirect_dest(); redir=(op,dest)
            self.expect(',')
            args=self.parse_expr_list()
        else:
            if self.cur().type not in (';','}','EOF'):
                args=self.parse_expr_list()
        return Node(kw, redir=redir, args=args)

    def parse_expr_list(self):
        args=[self.parse_expr()]
        while self.match(','):
            args.append(self.parse_expr())
        return args

    def parse_emit(self, kw):
        self.advance()
        redir=None
        if self.cur().type in ('>','>>','|'):
            op=self.advance().type; dest=self.parse_redirect_dest(); redir=(op,dest)
            self.expect(',')
        args=[]
        if self.cur().type not in (';','}','EOF'):
            args=self.parse_expr_list()
        return Node(kw, redir=redir, args=args)

    # ---------- expressions ----------
    def parse_expr(self, min_prec=1):
        # ternary at prec 1
        left=self.parse_binary(min_prec)
        if min_prec<=1 and self.cur().type=='?':
            self.advance()
            then=self.parse_expr(1)
            self.expect(':')
            els=self.parse_expr(1)
            left=Node('ternary', cond=left, then=then, els=els)
        return left

    def parse_binary(self, min_prec):
        left=self.parse_prefix()
        while True:
            t=self.cur()
            if t.type=='?' and min_prec<=1:
                break
            prec=BIN_PREC.get(t.type)
            if prec is None or prec<min_prec:
                break
            op=t.type; self.advance()
            if op in RIGHT_ASSOC:
                right=self.parse_binary(prec)
            else:
                # For ternary in right operand of lowest ops? e.g. a || b ? c:d is ternary at root, handled since parse_binary from parse_expr will break on ?
                right=self.parse_binary(prec+1)
            left=Node('binary', op=op, left=left, right=right, tok=t)
        return left

    def parse_prefix(self):
        t=self.cur()
        if t.type in ('+','-','!','~','.+','.-'):
            self.advance()
            operand=self.parse_binary(14)
            return Node('unary', op=t.type, operand=operand, tok=t)
        return self.parse_postfix()

    def parse_postfix(self):
        node=self.parse_primary()
        while True:
            t=self.cur()
            if t.type=='[':
                self.advance()
                # slice or index
                first=None; is_slice=False; second=None
                if self.cur().type==':':
                    is_slice=True; self.advance()
                    if self.cur().type!=']':
                        second=self.parse_expr()
                elif self.cur().type==']':
                    # empty index? error later
                    pass
                else:
                    first=self.parse_expr()
                    if self.cur().type==':':
                        is_slice=True; self.advance()
                        if self.cur().type!=']':
                            second=self.parse_expr()
                self.expect(']')
                if is_slice:
                    node=Node('slice', base=node, lo=first, hi=second)
                else:
                    node=Node('index', base=node, index=first)
                continue
            if t.type=='[[':
                self.advance(); idx=self.parse_expr(); self.expect(']'); self.expect(']')
                node=Node('keyatpos', base=node, index=idx); continue
            if t.type=='[[[':
                self.advance(); idx=self.parse_expr(); self.expect(']'); self.expect(']'); self.expect(']')
                node=Node('valatpos', base=node, index=idx); continue
            break
        return node

    def parse_primary(self):
        t=self.cur()
        if t.type=='BAD' or t.type=='BADSTRING':
            raise ParseError(t)
        if t.type=='(':
            self.advance(); e=self.parse_expr(); self.expect(')'); return e
        if t.type=='[':
            self.advance(); elems=[]
            if self.cur().type!=']':
                while True:
                    elems.append(self.parse_expr())
                    if not self.match(','): break
                    if self.cur().type==']': break
            self.expect(']'); return Node('arraylit', elems=elems)
        if t.type=='{':
            self.advance(); entries=[]
            if self.cur().type!='}':
                while True:
                    k=self.parse_expr(2)
                    self.expect(':')
                    v=self.parse_expr()
                    entries.append((k,v))
                    if not self.match(','): break
                    if self.cur().type=='}': break
            self.expect('}'); return Node('maplit', entries=entries)
        if t.type=='STRING':
            self.advance(); return Node('stringlit', value=t.value, tok=t)
        if t.type=='STRINGCI':
            self.advance(); return Node('stringlit', value=t.value, tok=t, ci=True)
        if t.type=='INT':
            self.advance(); return Node('intlit', value=parse_int_literal(t.text), tok=t)
        if t.type=='FLOAT':
            self.advance()
            try: f=float(t.text)
            except: f=0.0
            return Node('floatlit', value=VFloat(f, orig=t.text), tok=t)
        if t.type=='FIELD':
            self.advance(); return Node('field', name=t.value, tok=t)
        if t.type=='$*':
            self.advance(); return Node('fullrec', tok=t)
        if t.type=='$[':
            self.advance(); idx=self.parse_expr(); self.expect(']')
            return Node('index', base=Node('fullrec',tok=t), index=idx)
        if t.type=='$[[':
            self.advance(); idx=self.parse_expr(); self.expect(']'); self.expect(']')
            return Node('reckeyatpos', index=idx, tok=t)
        if t.type=='$[[[':
            self.advance(); idx=self.parse_expr(); self.expect(']'); self.expect(']'); self.expect(']')
            return Node('recvalatpos', index=idx, tok=t)
        if t.type=='OOSVAR':
            self.advance(); return Node('oosvar', name=t.value, tok=t)
        if t.type=='@*':
            self.advance(); return Node('fulloos', tok=t)
        if t.type=='@[':
            self.advance(); idx=self.parse_expr(); self.expect(']')
            return Node('oosbyexpr', index=idx, tok=t)
        if t.type=='@[[':
            self.advance(); idx=self.parse_expr(); self.expect(']'); self.expect(']')
            return Node('keyatpos', base=Node('fulloos',tok=t), index=idx)
        if t.type=='@[[[':
            self.advance(); idx=self.parse_expr(); self.expect(']'); self.expect(']'); self.expect(']')
            return Node('valatpos', base=Node('fulloos',tok=t), index=idx)
        if t.type=='NAME':
            name=t.text
            if name=='true':
                self.advance(); return Node('boollit', value=True)
            if name=='false':
                self.advance(); return Node('boollit', value=False)
            if name=='null':
                self.advance(); return Node('nulllit')
            if name=='Inf':
                self.advance(); return Node('floatlit', value=VFloat(math.inf, orig='Inf'), tok=t)
            if name=='NaN':
                self.advance(); return Node('floatlit', value=VFloat(math.nan, orig='NaN'), tok=t)
            if name=='all':
                self.advance(); return Node('fulloos', tok=t)
            if name=='func' and self.peek(1).type=='(':
                # anonymous function literal
                self.advance()
                params=self.parse_params()
                rettype=None
                if self.match(':'):
                    rt=self.cur(); rettype=rt.text; self.advance()
                body=self.parse_block()
                fname=_next_funct_name()
                return Node('funclit', name=fname, params=params, rettype=rettype, body=body)
            if name in CONTEXT_VARS:
                self.advance(); return Node('ctxvar', name=name, tok=t)
            if self.peek(1).type=='(':
                # function call
                self.advance(); self.expect('('); args=self.parse_arg_list(); self.expect(')')
                return Node('call', name=name, args=args, tok=t)
            self.advance(); return Node('name', name=name, tok=t)
        raise ParseError(t)

