# ---------------- Interpreter ----------------
class BreakExc(Exception): pass
class ContinueExc(Exception): pass
class ReturnExc(Exception):
    def __init__(self, value): self.value=value
class PanicExc(Exception): pass

def node_pos(node):
    if node is None: return (1,1)
    tok=getattr(node,'tok',None)
    if tok is not None: return (tok.line, tok.col)
    for attr in ('left','operand','base','cond','target','expr','then'):
        v=getattr(node,attr,None)
        if isinstance(v,Node): return node_pos(v)
    return (1,1)

def display_value_for_error(v):
    if v.kind==STRING: return '"'+v.val+'"'
    if v.kind==EMPTY: return '""'
    return v.to_string()

def make_bin_error(op,a,b):
    return VError(f"{op}: unacceptable types {a.kind}, {b.kind} with values {display_value_for_error(a)}, {display_value_for_error(b)}")
def make_un_error(op,a):
    return VError(f"{op}: unacceptable type {a.kind} with value {display_value_for_error(a)}")

_regex_cache={}
def compile_regex(pattern):
    """pattern is a string; Miller CI literals are stored as '"..."i' """
    flags=0; pat=pattern
    if len(pat)>=3 and pat[0]=='"' and pat.endswith('"i'):
        pat=pat[1:-2]; flags|=re.IGNORECASE
    key=(pat,flags)
    if key in _regex_cache:
        cached=_regex_cache[key]
        if isinstance(cached, Exception): raise cached
        return cached
    try:
        # Go RE2 supports (?P<name>...) and also (?<name>...)? Python doesn't support (?<name>. Leave.
        rx=re.compile(pat, flags)
    except re.error as e:
        err=MlrError(f"error parsing regexp: {e.msg}: `{pat}`")
        _regex_cache[key]=err
        raise err
    _regex_cache[key]=rx
    return rx

def apply_captures_to_string(s, captures):
    if captures is None: return s
    def repl(m):
        idx=int(m.group(1))
        if 1<=idx<=len(captures):
            g=captures[idx-1]
            return g if g is not None else ''
        return ''
    return re.sub(r'\\([1-9])', repl, s)

def typecheck_ok(vartype, v):
    if vartype in (None,'var'): return True
    if v.kind==ABSENT: return True
    if vartype=='int': return v.kind==INT
    if vartype=='float': return v.kind==FLOAT
    if vartype=='num': return v.kind in (INT,FLOAT)
    if vartype=='str': return v.kind in (STRING,EMPTY)
    if vartype=='bool': return v.kind==BOOL
    if vartype=='map': return v.kind==MAP
    if vartype=='arr': return v.kind==ARRAY
    if vartype=='funct': return v.kind==FUNCT
    return True

def check_assign_type(vartype, name, v, what=None):
    if not typecheck_ok(vartype, v):
        # empty string for str etc handled above
        desc=what or f"{vartype} {name}"
        # value description: type + representation; for string no quotes, for map json single-line?
        if v.kind==MAP: rep=json_stringify(v, vstack=False)
        elif v.kind==ARRAY: rep=json_stringify(v, vstack=False)
        elif v.kind==FUNCT: rep=v.to_string()
        else: rep=v.to_string()
        raise MlrError(f"couldn't assign variable {desc} from value {v.kind} {rep}")

class UserFunction:
    def __init__(self, name, params, rettype, body, is_subr=False):
        self.name=name; self.params=params; self.rettype=rettype; self.body=body; self.is_subr=is_subr
    def __repr__(self): return self.name

class Scope(dict):
    pass

class Runtime:
    def __init__(self, program, gctx, writer_opts=None):
        self.program=program
        self.gctx=gctx
        self.opts=gctx.opts if gctx else None
        self.writer_opts=writer_opts  # Options clone for redirected emit (output side)
        self.oos=MMap()
        self.rec=None  # OrderedDict
        self.ctx=None
        self.scopes=[]
        self.captures=None
        self.filter_value=VNull()
        self.put_include=True
        self.emit_callback=None  # fn(rec_dict, ctx, redir_tuple_or_None, runtime)
        self.in_function=0
    # scopes
    def push_scope(self):
        s=Scope(); self.scopes.append(s); return s
    def pop_scope(self):
        self.scopes.pop()
    def lookup_local(self, name):
        for s in reversed(self.scopes):
            if name in s: return s[name][0]
        return None
    def lookup_local_entry(self, name):
        for s in reversed(self.scopes):
            if name in s: return s, s[name]
        return None, None
    def define_local(self, name, vartype, value):
        cur=self.scopes[-1]
        if name in cur:
            raise MlrError(f"mlr: variable {name} has already been defined in the same scope")
        if value.kind!=ABSENT:
            check_assign_type(vartype, name, value)
            cur[name]=[value.copy(), vartype]
        else:
            cur[name]=[VAbsent(), vartype]
    def assign_local(self, name, value):
        if value.kind==ABSENT:
            return
        scope, entry=self.lookup_local_entry(name)
        if entry is not None:
            check_assign_type(entry[1], name, value)
            scope[name]=[value.copy(), entry[1]]
        else:
            self.scopes[-1][name]=[value.copy(), 'var']
    def set_local_existing_or_current(self, name, value):
        # for loop vars etc without type check beyond existing
        self.assign_local(name, value)
    def record_map_value(self):
        from collections import OrderedDict
        if self.rec is None:
            return VMap(MMap(OrderedDict()))
        return Value(MAP, MMap(self.rec))
    def oos_map_value(self):
        return Value(MAP, self.oos)

class DSLProgram:
    def __init__(self, source, gctx, writer_opts=None, is_filter=False):
        self.source=source
        self.gctx=gctx
        self.writer_opts=writer_opts
        self.is_filter=is_filter
        parser=Parser(source)
        try:
            stmts=parser.parse()
        except ParseError as e:
            raise MlrRawError(e.format())
        self.all_stmts=stmts
        self.begin_blocks=[]; self.end_blocks=[]; self.main_stmts=[]
        self.funcs={}; self.subrs={}
        for s in stmts:
            if s.kind=='begin': self.begin_blocks.append(s.body)
            elif s.kind=='end': self.end_blocks.append(s.body)
            elif s.kind=='funcdef':
                self.funcs[s.name]=UserFunction(s.name, s.params, s.rettype, s.body, False)
            elif s.kind=='subrdef':
                self.subrs[s.name]=UserFunction(s.name, s.params, s.rettype, s.body, True)
            else:
                self.main_stmts.append(s)
        self.runtime=Runtime(self, gctx, writer_opts)
        self.validate()
    def validate(self):
        # check overriding builtins
        import builtins as bif
        for name in list(self.funcs.keys())+list(self.subrs.keys()):
            if bif.is_builtin_name(name):
                raise MlrError(f'function named "{name}" must not override a built-in function of the same name')
        # filter keyword check handled by caller for filter verb (source scan at AST)
        # walk
        def walk_node(n, ctx):
            # ctx: dict with in_func (None|'func'|'subr'), in_loop bool, in_beginend bool, top bool
            if isinstance(n, list):
                for x in n: walk_node(x, ctx)
                return
            if not isinstance(n, Node): return
            if ctx.get('in_beginend') and n.kind in ('field','fullrec','reckeyatpos','recvalatpos'):
                raise MlrError('begin/end blocks cannot refer to records via $x, $*, etc')
            if n.kind in ('funcdef','subrdef') and not ctx.get('top'):
                raise MlrError('func blocks can only be at top level')
            if n.kind=='return':
                if ctx.get('in_func') is None:
                    raise MlrError('return statements are only valid within func/subr blocks')
                if ctx.get('in_func')=='func' and getattr(n,'expr',None) is None:
                    raise MlrError('return statements in func blocks must return a value')
                if ctx.get('in_func')=='subr' and getattr(n,'expr',None) is not None:
                    raise MlrError('return statements in subr blocks must not return a value')
            if n.kind=='break' and not ctx.get('in_loop'):
                raise MlrError('break statements are only valid within for/do/while loops')
            if n.kind=='continue' and not ctx.get('in_loop'):
                raise MlrError('continue statements are only valid within for/do/while loops')
            if n.kind=='call':
                import builtins as bif2
                if bif2.is_builtin_name(n.name):
                    bif2.check_arity(n.name, len(n.args))
                elif n.name in self.funcs:
                    exp=len(self.funcs[n.name].params)
                    if len(n.args)!=exp:
                        raise MlrError(arity_msg(n.name, len(n.args), exp))
            if n.kind=='callstmt' and n.name in self.subrs:
                exp=len(self.subrs[n.name].params)
                if len(n.args)!=exp:
                    raise MlrError(arity_msg(n.name, len(n.args), exp))
            if n.kind=='assign':
                validate_target(n.target)
            # recurse with updated ctx for special nodes
            if n.kind=='begin' or n.kind=='end':
                walk_node(n.body, {**ctx,'in_beginend':True,'top':False}); return
            if n.kind=='funcdef':
                walk_node(n.body, {**ctx,'in_func':'func','in_loop':False,'top':False,'in_beginend':False}); return
            if n.kind=='subrdef':
                walk_node(n.body, {**ctx,'in_func':'subr','in_loop':False,'top':False,'in_beginend':False}); return
            if n.kind=='funclit':
                walk_node(n.body, {**ctx,'in_func':'func','in_loop':False,'top':False}); return
            if n.kind in ('forin','forinmulti','forc','while','dowhile'):
                # walk children; body with in_loop True, other parts as is
                for k,v in n.__dict__.items():
                    if k=='body': walk_node(v,{**ctx,'in_loop':True,'top':False})
                    elif k=='kind': pass
                    else: walk_node(v,{**ctx,'top':False})
                return
            for k,v in n.__dict__.items():
                if k in ('kind','tok'): continue
                walk_node(v, {**ctx,'top':False})
        def validate_target(t):
            if not isinstance(t, Node): return
            if t.kind=='slice':
                raise MlrError('at CST BuildAssignableNode: unhandled AST node array-slice access')
            if t.kind=='keyatpos':
                raise MlrError("'[[...]]' is allowed on assignment left-hand sides only when immediately preceded by '$'")
            if t.kind=='valatpos':
                raise MlrError("'[[[...]]]' is allowed on assignment left-hand sides only when immediately preceded by '$'")
            if t.kind=='ctxvar' and t.name!='ENV':
                raise MlrError('context variable is not valid on the left-hand side of an assignment')
            for k,v in t.__dict__.items():
                if isinstance(v, Node): validate_target(v)
                elif isinstance(v, list):
