def get_index(base, idx, rt=None):
    if base.kind==ABSENT:
        return VAbsent()
    if base.kind==ERROR:
        return base
    if idx.kind==ARRAY:
        cur=base
        for el in idx.val:
            cur=get_index(cur, el, rt)
            if cur.kind in (ABSENT,ERROR): return cur
        return cur
    if base.kind==MAP:
        if idx.kind==INT:
            return base.val.get_str(str(idx.val))
        if idx.kind==STRING:
            return base.val.get_str(idx.val)
        return VError(f"Cannot map-index {idx.kind} {display_value_for_error(idx)}")
    if base.kind==ARRAY:
        if idx.kind!=INT:
            return VError(f"Cannot array-index {idx.kind} {display_value_for_error(idx)}")
        i=idx.val; n=len(base.val)
        if i<0: i=n+i+1
        if i<1 or i>n: return VAbsent()
        return base.val[i-1]
    if base.kind==STRING:
        if idx.kind!=INT:
            return VError(f"Cannot string-index {idx.kind} {display_value_for_error(idx)}")
        s=base.val; n=len(s); i=idx.val
        if i<0: i=n+i+1
        if i<1 or i>n: return VError("string index out of range")
        return VString(s[i-1])
    if base.kind==EMPTY:
        return VError("Cannot index empty")
