# ----- expression evaluation -----
def eval_context_var(name, rt):
    ctx=rt.ctx; opts=rt.opts
    if name=='NR': return VInt(ctx.nr if ctx else 1)
    if name=='FNR': return VInt(ctx.fnr if ctx else 1)
    if name=='FILENAME': return VString(ctx.filename if ctx else '(stdin)')
    if name=='FILENUM': return VInt(ctx.filenum if ctx else 1)
    if name=='NF': return VInt(len(rt.rec) if rt.rec is not None else 0)
    if name=='M_PI': return VFloat(math.pi)
    if name=='M_E': return VFloat(math.e)
    if name=='IFS': return VString(opts.ifs if opts else ',')
    if name=='OFS': return VString(opts.ofs if opts else ',')
    if name=='IPS': return VString(opts.ips if opts else '=')
    if name=='OPS': return VString(opts.ops if opts else '=')
    if name=='IRS': return VString(opts.irs if opts else '\n')
    if name=='ORS': return VString(opts.ors if opts else '\n')
    if name=='FLATSEP': return VString(opts.flatsep if opts else '.')
    if name=='ENV': return VAbsent() # only index form meaningful
    return VAbsent()

def eval_expr(node, rt):
    k=node.kind
    if k=='intlit' or k=='floatlit':
        return node.value.copy()
    if k=='stringlit':
        s=node.value
        # captures substitution is applied to stored string; for CI literals stored raw including quotes
        s=apply_captures_to_string(s, rt.captures)
        return VString(s)
    if k=='boollit': return VBool(node.value)
    if k=='nulllit': return VNull()
    if k=='field':
        if rt.rec is None: return VAbsent()
        return rt.rec.get(node.name, VAbsent())
    if k=='fullrec':
        # return a copy-ish map sharing? For read uses, returning live map is expected for iteration snapshot made by callers.
        # But assignments of $* to a var copy at set time.
        return rt.record_map_value()
    if k=='fulloos':
        return rt.oos_map_value()
    if k=='oosvar':
        return rt.oos.get_str(node.name)
    if k=='oosbyexpr':
        nm=eval_expr(node.index, rt).to_string(); return rt.oos.get_str(nm)
    if k=='name':
        v=rt.lookup_local(node.name)
        if v is not None: return v
        if node.name in rt.program.funcs:
            return Value(FUNCT, rt.program.funcs[node.name])
        return VAbsent()
    if k=='ctxvar':
        return eval_context_var(node.name, rt)
    if k=='arraylit':
        return VArray([eval_expr(e,rt) for e in node.elems])
    if k=='maplit':
        m=VMap()
        for kn, vn in node.entries:
            kv=eval_expr(kn, rt); vv=eval_expr(vn, rt)
            if kv.kind not in (INT,STRING,EMPTY):
                continue
            if vv.kind==ABSENT:
                # map entry with absent value? Miller: check later; skip? assign absent is no-op in maps built via SetIndex?
                # Test expectation: {"a": $nope} likely {} . Keep skipping.
                continue
            m.val.set(kv, vv.copy())
        return m
    if k=='index':
        if node.base.kind=='ctxvar' and node.base.name=='ENV':
            idx=eval_expr(node.index, rt)
            return VString(os.environ.get(idx.to_string(), ''))
        base=eval_expr(node.base, rt)
        idx=eval_expr(node.index, rt)
        return get_index(base, idx, rt)
    if k=='slice':
        base=eval_expr(node.base, rt)
        lo=eval_expr(node.lo, rt) if node.lo is not None else None
        hi=eval_expr(node.hi, rt) if node.hi is not None else None
        return get_slice(base, lo, hi)
    if k=='keyatpos':
        return key_at_pos(eval_expr(node.base, rt), eval_expr(node.index, rt))
    if k=='valatpos':
        return val_at_pos(eval_expr(node.base, rt), eval_expr(node.index, rt))
    if k=='reckeyatpos':
        return key_at_pos(rt.record_map_value(), eval_expr(node.index, rt))
    if k=='recvalatpos':
        return val_at_pos(rt.record_map_value(), eval_expr(node.index, rt))
    if k=='unary':
        return eval_unary(node.op, eval_expr(node.operand, rt))
    if k=='binary':
        return eval_binary(node, rt)
    if k=='ternary':
        c=eval_expr(node.cond, rt)
        if c.kind==ERROR: return c
        if c.kind!=BOOL: return VError('ternary condition is not boolean')
        return eval_expr(node.then if c.val else node.els, rt)
    if k=='call':
        return eval_call(node, rt)
    if k=='funclit':
        uf=UserFunction(node.name, node.params, node.rettype, node.body, False)
        return Value(FUNCT, uf)
    raise MlrError(f'internal: unhandled expression {k}')

def eval_unary(op, a):
    if op in ('+','.+'):
        if a.kind in (INT,FLOAT): return a
        if a.kind==ABSENT: return a
        if a.kind==EMPTY: return VInt(0)
        if a.kind==NULL: return a
        if a.kind==ERROR: return a
        if a.kind in (ARRAY,MAP,FUNCT): return VAbsent()
        return make_un_error(op,a)
    if op in ('-','.-'):
        if a.kind==INT: return VInt(wrap_int64(-a.val))
        if a.kind==FLOAT: return VFloat(-a.val)
        if a.kind==ABSENT: return a
        if a.kind==EMPTY: return VInt(0)
        if a.kind==NULL: return a
        if a.kind==ERROR: return a
        if a.kind in (ARRAY,MAP,FUNCT): return VAbsent()
        return make_un_error(op,a)
    if op=='!':
        if a.kind==BOOL: return VBool(not a.val)
        if a.kind==ERROR: return a
        return make_un_error(op,a)
    if op=='~':
        if a.kind==INT: return VInt(wrap_int64(~a.val))
        if a.kind==ABSENT: return a
        if a.kind==EMPTY: return a
        if a.kind==NULL: return a
        if a.kind==ERROR: return a
        if a.kind in (ARRAY,MAP,FUNCT): return VAbsent()
        return make_un_error(op,a)
    return make_un_error(op,a)

def _is_voidish(v): return v.kind in (EMPTY,ABSENT,NULL)
def _both_voidish_result(a,b,op):
    # if either absent -> absent; empty+null -> error; both empty -> empty; both null -> depends
    if a.kind==ABSENT or b.kind==ABSENT: return VAbsent()
    if {a.kind,b.kind}=={EMPTY,NULL}: return make_bin_error(op,a,b)
    if a.kind==EMPTY and b.kind==EMPTY: return VEmpty()
    if a.kind==NULL and b.kind==NULL:
        if op in ('+','-','*','.+','.-','.*','.'): return VNull()
        return make_bin_error(op,a,b)
    return None

def _zero_like(v):
    return VFloat(0.0) if v.kind==FLOAT else VInt(0)

def _float_div(x,y):
    if y==0.0:
        if x==0.0 or math.isnan(x): return math.nan
        return math.inf if (x>0) == (math.copysign(1,y)>0) else -math.inf
    return x/y

def eval_arith(op,a,b):
    if op=='.//':
        raise MlrError('function name not found: .//')
    if a.kind==ERROR: return a
    if b.kind==ERROR: return b
    if a.kind in (ARRAY,MAP,FUNCT) or b.kind in (ARRAY,MAP,FUNCT):
        return VAbsent()
    if a.kind in (STRING,BOOL) or b.kind in (STRING,BOOL):
        return make_bin_error(op,a,b)
    # void handling
    if _is_voidish(a) and _is_voidish(b):
        return _both_voidish_result(a,b,op)
    if _is_voidish(a) or _is_voidish(b):
        # group classification
        if op in ('+','*','.+','.*'):
            return b if _is_voidish(a) else a
        if op in ('-','.-'):
            if a.kind==EMPTY:
                # 0 - b
                return VInt(-b.val) if b.kind==INT else VFloat(-b.as_float())
            if b.kind==EMPTY:
                return a if a.kind in (INT,FLOAT) else b
            return b if _is_voidish(a) else a
        if op=='/':
            if a.kind==EMPTY or b.kind==EMPTY: return VEmpty()
            # absent/null left -> 0 like right; right -> left
            if _is_voidish(a): return _zero_like(b)
            else: return a
        if op in ('%','//','**'):
            if a.kind==EMPTY or b.kind==EMPTY: return VEmpty()
            if a.kind==NULL or b.kind==NULL: return make_bin_error(op,a,b)
            # absent
            if a.kind==ABSENT: return _zero_like(b)
            return a
        # other arith / bitwise / shifts / ./
        if a.kind==EMPTY or b.kind==EMPTY: return VEmpty()
        if a.kind==NULL or b.kind==NULL: return make_bin_error(op,a,b)
        return b if a.kind==ABSENT else a
    # numeric
    ai = a.kind==INT; bi=b.kind==INT
    if op in ('&','|','^','<<','>>','>>>'):
        if not (ai and bi): return make_bin_error(op,a,b)
        x=a.val; y=b.val
        if op=='&': return VInt(x&y)
        if op=='|': return VInt(x|y)
        if op=='^': return VInt(x^y)
        if op=='<<':
            if y<0 or y>=64: return VInt(0)
            return VInt(wrap_int64(x<<y))
        if op=='>>':
            if y<0: return VInt(0)
            return VInt(x>>y)  # python arithmetic, within int64 for y<... big gives 0/-1 fine
        if op=='>>>':
            if y<0 or y>=64: return VInt(0)
            return VInt(wrap_int64((x & ((1<<64)-1)) >> y))
    if op in ('+','-','*','.+','.-','.*'):
        dotop=op.startswith('.')
        baseop={'+':'+','-':'-','*':'*','.+':'+','.-':'-','.*':'*'}[op]
        if ai and bi:
            if baseop=='+': r=a.val+b.val
            elif baseop=='-': r=a.val-b.val
            else: r=a.val*b.val
            if dotop: return VInt(wrap_int64(r))
            if INT64_MIN<=r<=INT64_MAX: return VInt(r)
            return VFloat(float(a.val)+float(b.val) if baseop=='+' else (float(a.val)-float(b.val) if baseop=='-' else float(a.val)*float(b.val)))
        x=a.as_float(); y=b.as_float()
        return VFloat(x+y if baseop=='+' else (x-y if baseop=='-' else x*y))
    if op=='/':
        if ai and bi:
            if b.val==0:
                return VFloat(_float_div(float(a.val), float(b.val)))
            if a.val % b.val==0:
                # careful minint/-1 overflow
                q=a.val//b.val if (a.val<0)==(b.val<0) or a.val%b.val==0 else -((-a.val)//b.val)  # exact division anyway
                q=int(a.val/b.val) if False else a.val//b.val if a.val%b.val==0 else 0 # python floor == trunc when exact
                if INT64_MIN<=q<=INT64_MAX: return VInt(q)
                return VFloat(float(a.val)/float(b.val))
            return VFloat(a.val/b.val)
        return VFloat(_float_div(a.as_float(), b.as_float()))
    if op=='%':
        if ai and bi:
            if b.val==0: return VFloat(_float_div(float(a.val), float(b.val)))
            return VInt(a.val % b.val)
        x=a.as_float(); y=b.as_float()
        if y==0.0: return VFloat(_float_div(x,y))
        return VFloat(x % y)
    if op=='//':
        if ai and bi:
            if b.val==0: return VFloat(_float_div(float(a.val), float(b.val)))
            return VInt(a.val//b.val)
        x=a.as_float(); y=b.as_float()
        if y==0.0: return VFloat(_float_div(x,y))
        return VFloat(math.floor(x/y))
    if op=='./':
        if ai and bi:
            if b.val==0:
                raise PanicExc('panic: runtime error: integer divide by zero')
            q=abs(a.val)//abs(b.val)
            if (a.val<0)!=(b.val<0): q=-q
            return VInt(wrap_int64(q))
        return VFloat(_float_div(a.as_float(), b.as_float()))
    if op=='**':
        if ai and bi:
            if b.val>=0:
                # check overflow without huge ints for large exponents
                if a.val==0: return VInt(1 if b.val==0 else 0)
                if abs(a.val)==1:
                    return VInt(1 if a.val==1 or b.val%2==0 else -1)
                if b.val>1000:
                    # will overflow to float inf-ish
                    try: return VFloat(math.pow(float(a.val), float(b.val)))
                    except OverflowError: return VFloat(math.inf if a.val>0 or b.val%2==0 else -math.inf)
                r=a.val**b.val
                if INT64_MIN<=r<=INT64_MAX: return VInt(r)
                try: return VFloat(math.pow(float(a.val), float(b.val)))
                except OverflowError: return VFloat(math.inf)
            else:
                try: return VFloat(math.pow(float(a.val), float(b.val)))
                except Exception: return VFloat(_float_div(1.0,0.0) if a.val==0 else math.nan)
        try:
            return VFloat(math.pow(a.as_float(), b.as_float()))
        except OverflowError:
            return VFloat(math.inf)
        except Exception:
            # negative base fractional exp -> nan; 0**negative -> inf
            if a.as_float()==0.0 and b.as_float()<0: return VFloat(math.inf)
            return VFloat(math.nan)
    return make_bin_error(op,a,b)

def eval_compare(op,a,b):
    if a.kind==ABSENT or b.kind==ABSENT: return VAbsent()
    if a.kind==ERROR: return a
    if b.kind==ERROR: return b
    if a.kind in (ARRAY,MAP) or b.kind in (ARRAY,MAP):
        if op=='==': return VBool(values_equal(a,b))
        if op=='!=': return VBool(not values_equal(a,b))
        return make_bin_error(op,a,b)
    # compare
    if a.kind in (INT,FLOAT) and b.kind in (INT,FLOAT):
        if a.kind==INT and b.kind==INT:
            cmp=(a.val>b.val)-(a.val<b.val)
        else:
            x=a.as_float(); y=b.as_float()
            if math.isnan(x) or math.isnan(y):
                if op=='==': return VBool(False)
                if op=='!=': return VBool(True)
                if op=='<=>': return VInt(0)  # uncertain
                return VBool(False)
            cmp=(x>y)-(x<y)
    else:
        # if one is bool and other isn't bool, equality is false; relational uses string compare below (matches probes)
        if (a.kind==BOOL) != (b.kind==BOOL):
            if op=='==': return VBool(False)
            if op=='!=': return VBool(True)
        sa=a.to_string(); sb=b.to_string()
        cmp=(sa>sb)-(sa<sb)
    if op=='==': return VBool(cmp==0)
    if op=='!=': return VBool(cmp!=0)
    if op=='<': return VBool(cmp<0)
    if op=='<=': return VBool(cmp<=0)
    if op=='>': return VBool(cmp>0)
    if op=='>=': return VBool(cmp>=0)
    if op=='<=>': return VInt(cmp)
    return make_bin_error(op,a,b)

def eval_regex_match(op,a,b,rt):
    if a.kind==ABSENT or b.kind==ABSENT: return VAbsent()
    if a.kind==NULL or b.kind==NULL: return VNull()
    if a.kind==ERROR: return a
    if b.kind==ERROR: return b
    if b.kind not in (STRING,EMPTY):
        return make_bin_error(op,a,b)
    pat=b.to_plain_string()
    rx=compile_regex(pat)  # raises MlrError on invalid
    text=a.to_string()
    m=rx.search(text)
    if m:
        rt.captures=list(m.groups())
        matched=True
    else:
        rt.captures=[]
        matched=False
    return VBool(matched if op=='=~' else not matched)

def eval_binary(node, rt):
    op=node.op
    # short-circuit / special
    if op=='&&': return eval_logic_and(node, rt)
    if op=='||': return eval_logic_or(node, rt)
    if op=='^^':
        a=eval_expr(node.left, rt); b=eval_expr(node.right, rt)
        return eval_logic_xor(op,a,b)
    if op=='??':
        a=eval_expr(node.left, rt)
        if a.kind==ABSENT: return eval_expr(node.right, rt)
        return a
    if op=='???':
        a=eval_expr(node.left, rt)
        if a.kind in (ABSENT,EMPTY): return eval_expr(node.right, rt)
        return a
    if op=='.':
        a=eval_expr(node.left, rt)
        if a.kind==MAP:
            if node.right.kind=='name':
                key=node.right.name
            else:
                rv=eval_expr(node.right, rt)
                key=rv.to_string()
            return a.val.get_str(key)
        b=eval_expr(node.right, rt)
        return eval_concat(a,b)
    a=eval_expr(node.left, rt); b=eval_expr(node.right, rt)
    if op in ('+','-','*','/','%','//','**','./','.+','.-','.*','&','|','^','<<','>>','>>>','.//'):
        return eval_arith(op,a,b)
    if op in ('==','!=','<','<=','>','>=','<=>'):
        return eval_compare(op,a,b)
    if op in ('=~','!=~'):
        return eval_regex_match(op,a,b,rt)
    return make_bin_error(op,a,b)

def eval_concat(a,b):
    if a.kind==ERROR: return a
    if b.kind==ERROR: return b
    if a.kind==MAP:
        return VAbsent() # handled earlier normally
    if b.kind in (ARRAY,MAP) or a.kind==ARRAY:
        if _is_voidish(a) or _is_voidish(b):
            # null/absent . map -> absent; empty . array?
            if a.kind in (ABSENT,NULL) or b.kind in (ABSENT,NULL):
                return VAbsent()
        return make_bin_error('.',a,b)
    def cs(v):
        if v.kind in (EMPTY,ABSENT,NULL): return ''
        return v.to_string()
    return VString(cs(a)+cs(b))

def eval_logic_and(node, rt):
    a=eval_expr(node.left, rt)
    if a.kind==BOOL and not a.val:
        return VBool(False)
    if a.kind==ERROR:
        return a
    b=eval_expr(node.right, rt)
    if b.kind==BOOL and not b.val:
        return VBool(False)
    if b.kind==ABSENT:
        # absent &&/|| patterns: true&&absent absent, 3&&absent absent, empty&&absent absent
        return VAbsent()
    if a.kind==ABSENT:
        if b.kind==BOOL: return b
        if b.kind==EMPTY: return VAbsent()
        if b.kind==ERROR: return b
        return make_bin_error('&&',a,b)
    if a.kind==BOOL and a.val:
        if b.kind==BOOL: return b
        return make_bin_error('&&',a,b)
    if a.kind==EMPTY:
        if b.kind==BOOL: return b
        return make_bin_error('&&',a,b)
    if a.kind==NULL:
        if b.kind==BOOL: return b
        return make_bin_error('&&',a,b)
    # a other non-bool
    return make_bin_error('&&',a,b)

def eval_logic_or(node, rt):
    a=eval_expr(node.left, rt)
    if a.kind==BOOL and a.val:
        return VBool(True)
    if a.kind==ERROR:
        return a
    b=eval_expr(node.right, rt)
    if b.kind==BOOL and b.val:
        return VBool(True)
    if b.kind==ABSENT:
        return VAbsent()
    if a.kind==ABSENT:
        if b.kind==BOOL: return b
        if b.kind==EMPTY: return VAbsent()
        if b.kind==ERROR: return b
        return make_bin_error('||',a,b)
    if a.kind==BOOL and not a.val:
        if b.kind==BOOL: return b
        return make_bin_error('||',a,b)
    if a.kind in (EMPTY,NULL):
        if b.kind==BOOL: return b
        return make_bin_error('||',a,b)
    return make_bin_error('||',a,b)

def eval_logic_xor(op,a,b):
    if a.kind==ERROR: return a
    if b.kind==ERROR: return b
    if a.kind==ABSENT or b.kind==ABSENT:
        other=b if a.kind==ABSENT else a
        if other.kind==BOOL: return other
        if other.kind==ABSENT: return VAbsent()
        return make_bin_error(op,a,b)
    if a.kind==BOOL and b.kind==BOOL:
        return VBool(a.val ^ b.val)
    if a.kind in (EMPTY,NULL) and b.kind==BOOL: return b
    if b.kind in (EMPTY,NULL) and a.kind==BOOL: return a
    return make_bin_error(op,a,b)

def eval_call(node, rt):
    name=node.name
    # local funct variable takes precedence if funct
    # Evaluate args first? For unknown func, Miller error before arg side effects? Unknown. Evaluate args for known paths.
    local=rt.lookup_local(name)
    if local is not None and local.kind==FUNCT:
        args=[eval_expr(x,rt) for x in node.args]
        return call_user_function(local.val, args, rt, name_for_msg=name)
    if name in rt.program.funcs:
        uf=rt.program.funcs[name]
        if len(node.args)!=len(uf.params):
            raise MlrError(arity_msg(name, len(node.args), len(uf.params)))
        args=[eval_expr(x,rt) for x in node.args]
        return call_user_function(uf, args, rt, name_for_msg=name)
    import bifs
    if bifs.is_builtin_name(name):
        # Some bifs need unevaluated? No, all args evaluated. Higher-order funcs receive FUNCT values.
        args=[eval_expr(x,rt) for x in node.args]
        return bifs.call_builtin(name, args, rt)
    raise MlrError(f'function name not found: {name}')

def call_user_function(uf, args, rt, name_for_msg=None):
    if len(args)!=len(uf.params):
        raise MlrError(arity_msg(name_for_msg or uf.name, len(args), len(uf.params)))
    saved_scopes=rt.scopes
    saved_infunc=rt.in_function
    rt.in_function+=1
    rt.scopes=[]
    pscope=rt.push_scope()
    try:
        for (vartype,pname), val in zip(uf.params, args):
            if val.kind!=ABSENT:
                check_assign_type(vartype, pname, val)
                pscope[pname]=[val.copy(), vartype]
            else:
                pscope[pname]=[VAbsent(), vartype]
        try:
            exec_block(rt, uf.body)
            result=VAbsent()
        except ReturnExc as e:
            result=e.value if e.value is not None else VAbsent()
    finally:
        rt.scopes=saved_scopes
        rt.in_function=saved_infunc
    if not uf.is_subr and uf.rettype not in (None,'var'):
        if result.kind!=ABSENT:
            check_assign_type(uf.rettype, 'function return value', result, what=f"{uf.rettype} function return value")
    return result

