# ----- expression evaluation -----
def eval_context_var(name, rt):
    ctx=rt.ctx; opts=rt.opts
    if name=='NR': return VInt(ctx.nr if ctx else 1)
    if name=='FNR': return VInt(ctx.fnr if ctx else 1)
    if name=='FILENAME': return VString(ctx.filename if ctx else '(stdin)')
    if name=='FILENUM': return VInt(ctx.filenum if ctx else 1)
    if name=='NF': return VInt(len(rt.rec) if rt.rec is not None else 0)
    if name=='M_PI': return VFloat(math.pi)
    if name=='M_E': return VFloat(math.e)
    if name=='IFS': return VString(opts.ifs if opts else ',')
    if name=='OFS': return VString(opts.ofs if opts else ',')
    if name=='IPS': return VString(opts.ips if opts else '=')
    if name=='OPS': return VString(opts.ops if opts else '=')
    if name=='IRS': return VString(opts.irs if opts else '\n')
    if name=='ORS': return VString(opts.ors if opts else '\n')
    if name=='FLATSEP': return VString(opts.flatsep if opts else '.')
    if name=='ENV': return VAbsent() # only index form meaningful
    return VAbsent()

def eval_expr(node, rt):
    k=node.kind
    if k=='intlit' or k=='floatlit':
        return node.value.copy()
    if k=='stringlit':
        s=node.value
        # captures substitution is applied to stored string; for CI literals stored raw including quotes
        s=apply_captures_to_string(s, rt.captures)
        return VString(s)
    if k=='boollit': return VBool(node.value)
    if k=='nulllit': return VNull()
    if k=='field':
        if rt.rec is None: return VAbsent()
        return rt.rec.get(node.name, VAbsent())
    if k=='fullrec':
        # return a copy-ish map sharing? For read uses, returning live map is expected for iteration snapshot made by callers.
        # But assignments of $* to a var copy at set time.
        return rt.record_map_value()
    if k=='fulloos':
        return rt.oos_map_value()
    if k=='oosvar':
        return rt.oos.get_str(node.name)
    if k=='oosbyexpr':
        nm=eval_expr(node.index, rt).to_string(); return rt.oos.get_str(nm)
    if k=='name':
        v=rt.lookup_local(node.name)
        if v is not None: return v
        if node.name in rt.program.funcs:
            return Value(FUNCT, rt.program.funcs[node.name])
        return VAbsent()
    if k=='ctxvar':
        return eval_context_var(node.name, rt)
    if k=='arraylit':
        return VArray([eval_expr(e,rt) for e in node.elems])
    if k=='maplit':
        m=VMap()
        for kn, vn in node.entries:
            kv=eval_expr(kn, rt); vv=eval_expr(vn, rt)
            if kv.kind not in (INT,STRING,EMPTY):
                continue
            if vv.kind==ABSENT:
                # map entry with absent value? Miller: check later; skip? assign absent is no-op in maps built via SetIndex?
                # Test expectation: {"a": $nope} likely {} . Keep skipping.
                continue
            m.val.set(kv, vv.copy())
        return m
    if k=='index':
        if node.base.kind=='ctxvar' and node.base.name=='ENV':
            idx=eval_expr(node.index, rt)
            return VString(os.environ.get(idx.to_string(), ''))
        base=eval_expr(node.base, rt)
        idx=eval_expr(node.index, rt)
        return get_index(base, idx, rt)
    if k=='slice':
        base=eval_expr(node.base, rt)
        lo=eval_expr(node.lo, rt) if node.lo is not None else None
        hi=eval_expr(node.hi, rt) if node.hi is not None else None
        return get_slice(base, lo, hi)
    if k=='keyatpos':
        return key_at_pos(eval_expr(node.base, rt), eval_expr(node.index, rt))
    if k=='valatpos':
        return val_at_pos(eval_expr(node.base, rt), eval_expr(node.index, rt))
    if k=='reckeyatpos':
        return key_at_pos(rt.record_map_value(), eval_expr(node.index, rt))
    if k=='recvalatpos':
        return val_at_pos(rt.record_map_value(), eval_expr(node.index, rt))
    if k=='unary':
        return eval_unary(node.op, eval_expr(node.operand, rt))
    if k=='binary':
        return eval_binary(node, rt)
    if k=='ternary':
        c=eval_expr(node.cond, rt)
        if c.kind==ERROR: return c
        if c.kind!=BOOL: return VError('ternary condition is not boolean')
        return eval_expr(node.then if c.val else node.els, rt)
    if k=='call':
        return eval_call(node, rt)
    if k=='funclit':
        uf=UserFunction(node.name, node.params, node.rettype, node.body, False)
        return Value(FUNCT, uf)
    raise MlrError(f'internal: unhandled expression {k}')

def eval_unary(op, a):
    if op in ('+','.+'):
        if a.kind in (INT,FLOAT): return a
        if a.kind==ABSENT: return a
        if a.kind==EMPTY: return VInt(0)
        if a.kind==NULL: return a
        if a.kind==ERROR: return a
        if a.kind in (ARRAY,MAP,FUNCT): return VAbsent()
        return make_un_error(op,a)
    if op in ('-','.-'):
        if a.kind==INT: return VInt(wrap_int64(-a.val))
        if a.kind==FLOAT: return VFloat(-a.val)
        if a.kind==ABSENT: return a
        if a.kind==EMPTY: return VInt(0)
        if a.kind==NULL: return a
        if a.kind==ERROR: return a
        if a.kind in (ARRAY,MAP,FUNCT): return VAbsent()
        return make_un_error(op,a)
    if op=='!':
        if a.kind==BOOL: return VBool(not a.val)
        if a.kind==ERROR: return a
        return make_un_error(op,a)
    if op=='~':
        if a.kind==INT: return VInt(wrap_int64(~a.val))
        if a.kind==ABSENT: return a
        if a.kind==EMPTY: return a
        if a.kind==NULL: return a
        if a.kind==ERROR: return a
        if a.kind in (ARRAY,MAP,FUNCT): return VAbsent()
        return make_un_error(op,a)
    return make_un_error(op,a)

def _is_voidish(v): return v.kind in (EMPTY,ABSENT,NULL)
def _both_voidish_result(a,b,op):
    # if either absent -> absent; empty+null -> error; both empty -> empty; both null -> depends
    if a.kind==ABSENT or b.kind==ABSENT: return VAbsent()
    if {a.kind,b.kind}=={EMPTY,NULL}: return make_bin_error(op,a,b)
    if a.kind==EMPTY and b.kind==EMPTY: return VEmpty()
    if a.kind==NULL and b.kind==NULL:
        if op in ('+','-','*','.+','.-','.*','.'): return VNull()
        return make_bin_error(op,a,b)
    return None

def _zero_like(v):
    return VFloat(0.0) if v.kind==FLOAT else VInt(0)

def _float_div(x,y):
    if y==0.0:
        if x==0.0 or math.isnan(x): return math.nan
        return math.inf if (x>0) == (math.copysign(1,y)>0) else -math.inf
    return x/y

def eval_arith(op,a,b):
    if op=='.//':
        raise MlrError('function name not found: .//')
    if a.kind==ERROR: return a
    if b.kind==ERROR: return b
    if a.kind in (ARRAY,MAP,FUNCT) or b.kind in (ARRAY,MAP,FUNCT):
        return VAbsent()
    if a.kind in (STRING,BOOL) or b.kind in (STRING,BOOL):
        return make_bin_error(op,a,b)
    # void handling
    if _is_voidish(a) and _is_voidish(b):
        return _both_voidish_result(a,b,op)
    if _is_voidish(a) or _is_voidish(b):
        # group classification
        if op in ('+','*','.+','.*'):
            return b if _is_voidish(a) else a
        if op in ('-','.-'):
            if a.kind==EMPTY:
                # 0 - b
                return VInt(-b.val) if b.kind==INT else VFloat(-b.as_float())
            if b.kind==EMPTY:
                return a if a.kind in (INT,FLOAT) else b
            return b if _is_voidish(a) else a
        if op=='/':
            if a.kind==EMPTY or b.kind==EMPTY: return VEmpty()
            # absent/null left -> 0 like right; right -> left
            if _is_voidish(a): return _zero_like(b)
            else: return a
        if op in ('%','//','**'):
            if a.kind==EMPTY or b.kind==EMPTY: return VEmpty()
            if a.kind==NULL or b.kind==NULL: return make_bin_error(op,a,b)
            # absent
            if a.kind==ABSENT: return _zero_like(b)
            return a
        # other arith / bitwise / shifts / ./
        if a.kind==EMPTY or b.kind==EMPTY: return VEmpty()
        if a.kind==NULL or b.kind==NULL: return make_bin_error(op,a,b)
        return b if a.kind==ABSENT else a
    # numeric
    ai = a.kind==INT; bi=b.kind==INT
    if op in ('&','|','^','<<','>>','>>>'):
        if not (ai and bi): return make_bin_error(op,a,b)
        x=a.val; y=b.val
        if op=='&': return VInt(x&y)
        if op=='|': return VInt(x|y)
        if op=='^': return VInt(x^y)
        if op=='<<':
            if y<0 or y>=64: return VInt(0)
            return VInt(wrap_int64(x<<y))
        if op=='>>':
            if y<0: return VInt(0)
            return VInt(x>>y)  # python arithmetic, within int64 for y<... big gives 0/-1 fine
        if op=='>>>':
            if y<0 or y>=64: return VInt(0)
            return VInt(wrap_int64((x & ((1<<64)-1)) >> y))
    if op in ('+','-','*','.+','.-','.*'):
        dotop=op.startswith('.')
        baseop={'+':'+','-':'-','*':'*','.+':'+','.-':'-','.*':'*'}[op]
        if ai and bi:
            if baseop=='+': r=a.val+b.val
            elif baseop=='-': r=a.val-b.val
            else: r=a.val*b.val
            if dotop: return VInt(wrap_int64(r))
            if INT64_MIN<=r<=INT64_MAX: return VInt(r)
            return VFloat(float(a.val)+float(b.val) if baseop=='+' else (float(a.val)-float(b.val) if baseop=='-' else float(a.val)*float(b.val)))
        x=a.as_float(); y=b.as_float()
        return VFloat(x+y if baseop=='+' else (x-y if baseop=='-' else x*y))
    if op=='/':
        if ai and bi:
            if b.val==0:
                return VFloat(_float_div(float(a.val), float(b.val)))
            if a.val % b.val==0:
                # careful minint/-1 overflow
                q=a.val//b.val if (a.val<0)==(b.val<0) or a.val%b.val==0 else -((-a.val)//b.val)  # exact division anyway
                q=int(a.val/b.val) if False else a.val//b.val if a.val%b.val==0 else 0 # python floor == trunc when exact
                if INT64_MIN<=q<=INT64_MAX: return VInt(q)
                return VFloat(float(a.val)/float(b.val))
            return VFloat(a.val/b.val)
        return VFloat(_float_div(a.as_float(), b.as_float()))
    if op=='%':
        if ai and bi:
            if b.val==0: return VFloat(_float_div(float(a.val), float(b.val)))
            return VInt(a.val % b.val)
        x=a.as_float(); y=b.as_float()
        if y==0.0: return VFloat(_float_div(x,y))
        return VFloat(x % y)
    if op=='//':
        if ai and bi:
            if b.val==0: return VFloat(_float_div(float(a.val), float(b.val)))
            return VInt(a.val//b.val)
        x=a.as_float(); y=b.as_float()
        if y==0.0: return VFloat(_float_div(x,y))
