            return VInt(wrap_int64(q))
        return VFloat(_float_div(a.as_float(), b.as_float()))
    if op=='**':
        if ai and bi:
            if b.val>=0:
                # check overflow without huge ints for large exponents
                if a.val==0: return VInt(1 if b.val==0 else 0)
                if abs(a.val)==1:
                    return VInt(1 if a.val==1 or b.val%2==0 else -1)
                if b.val>1000:
                    # will overflow to float inf-ish
                    try: return VFloat(math.pow(float(a.val), float(b.val)))
                    except OverflowError: return VFloat(math.inf if a.val>0 or b.val%2==0 else -math.inf)
                r=a.val**b.val
                if INT64_MIN<=r<=INT64_MAX: return VInt(r)
                try: return VFloat(math.pow(float(a.val), float(b.val)))
                except OverflowError: return VFloat(math.inf)
            else:
                try: return VFloat(math.pow(float(a.val), float(b.val)))
                except Exception: return VFloat(_float_div(1.0,0.0) if a.val==0 else math.nan)
