        return eval_regex_match(op,a,b,rt)
    return make_bin_error(op,a,b)

def eval_concat(a,b):
    if a.kind==ERROR: return a
    if b.kind==ERROR: return b
    if a.kind==MAP:
        return VAbsent() # handled earlier normally
    if b.kind in (ARRAY,MAP) or a.kind==ARRAY:
        if _is_voidish(a) or _is_voidish(b):
            # null/absent . map -> absent; empty . array?
            if a.kind in (ABSENT,NULL) or b.kind in (ABSENT,NULL):
                return VAbsent()
        return make_bin_error('.',a,b)
    def cs(v):
        if v.kind in (EMPTY,ABSENT,NULL): return ''
        return v.to_string()
    return VString(cs(a)+cs(b))

def eval_logic_and(node, rt):
    a=eval_expr(node.left, rt)
    if a.kind==BOOL and not a.val:
        return VBool(False)
    if a.kind==ERROR:
        return a
    b=eval_expr(node.right, rt)
    if b.kind==BOOL and not b.val:
        return VBool(False)
    if b.kind==ABSENT:
        # absent &&/|| patterns: true&&absent absent, 3&&absent absent, empty&&absent absent
        return VAbsent()
    if a.kind==ABSENT:
        if b.kind==BOOL: return b
        if b.kind==EMPTY: return VAbsent()
        if b.kind==ERROR: return b
        return make_bin_error('&&',a,b)
    if a.kind==BOOL and a.val:
        if b.kind==BOOL: return b
        return make_bin_error('&&',a,b)
    if a.kind==EMPTY:
        if b.kind==BOOL: return b
        return make_bin_error('&&',a,b)
    if a.kind==NULL:
        if b.kind==BOOL: return b
        return make_bin_error('&&',a,b)
    # a other non-bool
    return make_bin_error('&&',a,b)

def eval_logic_or(node, rt):
    a=eval_expr(node.left, rt)
    if a.kind==BOOL and a.val:
        return VBool(True)
    if a.kind==ERROR:
        return a
    b=eval_expr(node.right, rt)
    if b.kind==BOOL and b.val:
        return VBool(True)
    if b.kind==ABSENT:
        return VAbsent()
    if a.kind==ABSENT:
        if b.kind==BOOL: return b
        if b.kind==EMPTY: return VAbsent()
        if b.kind==ERROR: return b
        return make_bin_error('||',a,b)
    if a.kind==BOOL and not a.val:
        if b.kind==BOOL: return b
        return make_bin_error('||',a,b)
    if a.kind in (EMPTY,NULL):
        if b.kind==BOOL: return b
        return make_bin_error('||',a,b)
    return make_bin_error('||',a,b)

def eval_logic_xor(op,a,b):
    if a.kind==ERROR: return a
    if b.kind==ERROR: return b
    if a.kind==ABSENT or b.kind==ABSENT:
        other=b if a.kind==ABSENT else a
        if other.kind==BOOL: return other
        if other.kind==ABSENT: return VAbsent()
        return make_bin_error(op,a,b)
    if a.kind==BOOL and b.kind==BOOL:
        return VBool(a.val ^ b.val)
    if a.kind in (EMPTY,NULL) and b.kind==BOOL: return b
    if b.kind in (EMPTY,NULL) and a.kind==BOOL: return a
    return make_bin_error(op,a,b)

def eval_call(node, rt):
    name=node.name
    # local funct variable takes precedence if funct
    # Evaluate args first? For unknown func, Miller error before arg side effects? Unknown. Evaluate args for known paths.
    local=rt.lookup_local(name)
    if local is not None and local.kind==FUNCT:
        args=[eval_expr(x,rt) for x in node.args]
        return call_user_function(local.val, args, rt, name_for_msg=name)
    if name in rt.program.funcs:
        uf=rt.program.funcs[name]
        if len(node.args)!=len(uf.params):
            raise MlrError(arity_msg(name, len(node.args), len(uf.params)))
        args=[eval_expr(x,rt) for x in node.args]
        return call_user_function(uf, args, rt, name_for_msg=name)
    import bifs
    if bifs.is_builtin_name(name):
        # Some bifs need unevaluated? No, all args evaluated. Higher-order funcs receive FUNCT values.
        args=[eval_expr(x,rt) for x in node.args]
        return bifs.call_builtin(name, args, rt)
    raise MlrError(f'function name not found: {name}')

def call_user_function(uf, args, rt, name_for_msg=None):
    if len(args)!=len(uf.params):
        raise MlrError(arity_msg(name_for_msg or uf.name, len(args), len(uf.params)))
    saved_scopes=rt.scopes
    saved_infunc=rt.in_function
    rt.in_function+=1
    rt.scopes=[]
    pscope=rt.push_scope()
    try:
        for (vartype,pname), val in zip(uf.params, args):
            if val.kind!=ABSENT:
                check_assign_type(vartype, pname, val)
                pscope[pname]=[val.copy(), vartype]
            else:
                pscope[pname]=[VAbsent(), vartype]
        try:
            exec_block(rt, uf.body)
            result=VAbsent()
        except ReturnExc as e:
            result=e.value if e.value is not None else VAbsent()
    finally:
        rt.scopes=saved_scopes
        rt.in_function=saved_infunc
    if not uf.is_subr and uf.rettype not in (None,'var'):
        if result.kind!=ABSENT:
            check_assign_type(uf.rettype, 'function return value', result, what=f"{uf.rettype} function return value")
    return result

