            if cur.kind==BOOL and not cur.val and rhs.kind==BOOL: return rhs
            if cur.kind in (ABSENT,EMPTY,NULL) and rhs.kind==BOOL: return rhs
            if rhs.kind==ABSENT: return VAbsent()
            return make_bin_error(bop,cur,rhs)
    return eval_arith(bop, cur, rhs)

def exec_unset(rt, target):
    k=target.kind
    if k=='field':
        if rt.rec is not None: rt.rec.pop(target.name, None)
        return
    if k=='fullrec':
        if rt.rec is not None: rt.rec.clear()
        return
    if k=='fulloos':
        rt.oos.d.clear(); return
    if k=='oosvar':
        rt.oos.d.pop(target.name, None); return
    if k=='oosbyexpr':
        rt.oos.d.pop(eval_expr(target.index,rt).to_string(), None); return
    if k=='name':
        for s in reversed(rt.scopes):
            if target.name in s: del s[target.name]; return
        return
    if k=='index':
        # unset nested key
        try:
            base_ref=ref_for(target.base, rt)
            base=base_ref.get()
            idx=eval_expr(target.index, rt)
            if base.kind==MAP:
                base.val.d.pop(str(idx.val) if idx.kind==INT else idx.to_plain_string(), None)
            elif base.kind==ARRAY and idx.kind==INT:
                i=idx.val; n=len(base.val)
                if i<0: i=n+i+1
                if 1<=i<=n: del base.val[i-1]
        except Exception:
            pass
        return
    if k=='binary' and target.op=='.':
        # treat as index unset
        fake=Node('index', base=target.left, index=Node('stringlit', value=target.right.name) if target.right.kind=='name' else target.right)
        exec_unset(rt, fake); return
    # $[[...]] etc ignore
    return

def resolve_redirect_dest(rt, redir):
    if redir is None: return None
    op, dest_node=redir
    if dest_node.kind=='redirname':
        return (op, dest_node.name, True)  # is_stream_name
    v=eval_expr(dest_node, rt)
    return (op, v.to_string(), False)

def write_plain(rt, text, redir, default_stream='stdout'):
    if redir is None:
        out=sys.stderr if default_stream=='stderr' else sys.stdout
        out.write(text); out.flush()
        return
    op, dest, is_stream=resolve_redirect_dest(rt, redir)
    if is_stream:
        out=sys.stderr if dest=='stderr' else sys.stdout
        out.write(text); out.flush(); return
    # file / pipe via redirect manager if available
    mgr=rt.gctx.redirects if rt.gctx else None
    if mgr is not None:
        mgr.write_plain(op, dest, text)
    else:
        mode='a' if op=='>>' else 'w'
        if op=='|':
            import subprocess; subprocess.run(dest, shell=True, input=text.encode())
        else:
            with open(dest, mode) as f: f.write(text)

def exec_print(rt, s):
    vals=[eval_expr(a,rt) for a in s.args]
    ofmt=rt.opts.ofmt if rt.opts else None
    text=' '.join(v.to_string(ofmt) for v in vals)
    if s.kind in ('print','eprint'):
        text+='\n'
    default='stderr' if s.kind.startswith('e') else 'stdout'
    write_plain(rt, text, s.redir, default_stream=default)

# ----- emit -----
def _emit_basename(node):
    if node.kind in ('field','oosvar','name'):
        return node.name
    if node.kind=='index':
        return _emit_basename(node.base)
    if node.kind=='binary' and node.op=='.':
        return _emit_basename(node.left)
    return None

def _node_type_desc(node):
    m={'fulloos':'full oosvar','fullrec':'full srec','field':'field name','oosvar':'oosvar name','name':'non-sigil name'}
    return m.get(node.kind, node.kind)

def exec_emit(rt, s):
    if rt.emit_callback is None: return
    from collections import OrderedDict
    if s.kind=='emit1':
        if not s.args: return
        v=eval_expr(s.args[0], rt)
        if v.kind==MAP:
            rec=OrderedDict()
            for kk,vv in v.val.items():
                if vv.kind!=ABSENT: rec[kk.to_plain_string()]=vv.copy()
            rt.emit_callback(rec, rt.ctx, s.redir, rt)
        return
    if s.kind=='emitf':
        rec=OrderedDict()
        for a in s.args:
            bn=_emit_basename(a)
            if bn is None:
                raise MlrError(f"can't get name of node type \"{_node_type_desc(a)}\" for emitf")
            v=eval_expr(a, rt)
            if v.kind!=ABSENT:
                rec[bn]=v.copy()
        rt.emit_callback(rec, rt.ctx, s.redir, rt)
        return
    # emit / emitp
    if not s.args: return
    first=s.args[0]
    index_names=[]
    for a in s.args[1:]:
        iv=eval_expr(a, rt)
        index_names.append(iv.to_string())
    bn=_emit_basename(first)
    v=eval_expr(first, rt)
    records=[]
    if bn is None:
        if v.kind==MAP:
            for kk,vv in v.val.items():
                records.extend(_emit_named(kk.to_plain_string(), vv, index_names, emitp=(s.kind=='emitp'), flatsep=rt.opts.flatsep if rt.opts else '.'))
        elif v.kind!=ABSENT:
            # unnamed scalar: no emit (matches emit of literal? literal scalars parse-restricted)
            pass
    else:
        if v.kind!=ABSENT:
            records.extend(_emit_named(bn, v, index_names, emitp=(s.kind=='emitp'), flatsep=rt.opts.flatsep if rt.opts else '.'))
    for rec in records:
        rt.emit_callback(rec, rt.ctx, s.redir, rt)

def _emit_named(name, value, index_names, emitp=False, flatsep='.'):
    from collections import OrderedDict
    out=[]
    if emitp:
        def rec_walk(val, collected, path):
            # if still consuming index names and val is map, branch
            if val.kind==MAP and len(collected)<len(index_names):
                for kk,vv in val.val.items():
                    rec_walk(vv, collected+[kk.to_plain_string()], path)
                return
            # collect all leaves under val into one record
            recd=OrderedDict()
            for i, cv in enumerate(collected):
                recd[index_names[i]]=VString(cv) if not _looks_int(cv) else infer_value(cv)
                # NOTE index values originally were keys (strings); but keys from maps created by int indices are strings in our model.
                # Miller emits them with original key type (int keys became strings in maps anyway except record fields). Use infer to match numeric keys output (same print).
            leaves=[]
            def collect(v2, p):
                if v2.kind==MAP:
                    if len(v2.val)==0:
                        leaves.append((p, v2))
                    for kk,vv in v2.val.items():
                        collect(vv, p+[kk.to_plain_string()])
                elif v2.kind==ARRAY:
                    if len(v2.val)==0:
                        leaves.append((p, v2))
                    else:
                        # array as leaf value (writer will flatten) - keep as one leaf
                        leaves.append((p, v2))
                else:
                    leaves.append((p, v2))
            collect(val, [])
            for p, leaf in leaves:
                fname=name + (flatsep+flatsep.join(p) if p else '')
                recd[fname]=leaf.copy()
            if leaves:
                out.append(recd)
        rec_walk(value, [], [])
        return out
    # emit (non-p)
    def walk(val, collected):
        if val.kind==MAP:
            if len(collected)<len(index_names):
                for kk,vv in val.val.items():
                    walk(vv, collected+[kk])
                return
            # no slots left
            vals=list(val.val.values_list())
            if all(x.kind!=MAP for x in vals):
                recd=OrderedDict()
                for i, cv in enumerate(collected):
                    recd[index_names[i]]=cv.copy()
                for kk,vv in val.val.items():
                    if vv.kind!=ABSENT: recd[kk.to_plain_string()]=vv.copy()
                out.append(recd); return
            # mixed / maps: traverse map-valued entries dropping keys; scalar entries grouped?
            scalar_rec=None
            for kk,vv in val.val.items():
                if vv.kind==MAP:
                    walk(vv, collected)
                else:
                    if scalar_rec is None:
                        scalar_rec=OrderedDict()
                        for i, cv in enumerate(collected): scalar_rec[index_names[i]]=cv.copy()
                    scalar_rec[kk.to_plain_string()]=vv.copy()
            if scalar_rec is not None:
                out.append(scalar_rec)
            return
        else:
            if len(collected)==0 and len(index_names)>0:
                return
            recd=OrderedDict()
            for i, cv in enumerate(collected):
                if i<len(index_names): recd[index_names[i]]=cv.copy()
            recd[name]=val.copy()
            out.append(recd); return
    walk(value, [])
    return out

def _looks_int(s):
    return bool(re.match(r'^-?[0-9]+$', s))

