# ----- statement execution -----
def exec_block(rt, stmts):
    rt.push_scope()
    try:
        exec_stmts(rt, stmts)
    finally:
        rt.pop_scope()

def exec_stmts(rt, stmts):
    for s in stmts:
        exec_stmt(rt, s)

def require_bool(v, node, allow_absent=False):
    if v.kind==BOOL: return v.val
    if allow_absent and v.kind==ABSENT: return False
    line,col=node_pos(node)
    raise MlrError(f'conditional expression did not evaluate to boolean at DSL expression line {line} column {col}')

def exec_stmt(rt, s):
    k=s.kind
    if k=='exprstmt':
        v=eval_expr(s.expr, rt)
        rt.filter_value=v
        return
    if k=='assign':
        exec_assign(rt, s.target, s.op, s.rhs)
        return
    if k=='decl':
        # compound ops in decl: initial absent op rhs
        if s.op=='=':
            v=eval_expr(s.rhs, rt)
        else:
            v=apply_compound(s.op, VAbsent(), eval_expr(s.rhs, rt), rt, s)
        rt.define_local(s.name, s.vartype, v)
        return
    if k=='if':
        for cond, body in s.branches:
            if require_bool(eval_expr(cond, rt), cond):
                exec_block(rt, body); return
        if s.else_body is not None:
            exec_block(rt, s.else_body)
        return
    if k=='condblock':
        if require_bool(eval_expr(s.cond, rt), s.cond, allow_absent=True):
            exec_block(rt, s.body)
        return
    if k=='while':
        while require_bool(eval_expr(s.cond, rt), s.cond):
            try: exec_block(rt, s.body)
            except ContinueExc: pass
            except BreakExc: break
        return
    if k=='dowhile':
        while True:
            try: exec_block(rt, s.body)
            except ContinueExc: pass
            except BreakExc: break
            if not require_bool(eval_expr(s.cond, rt), s.cond): break
        return
    if k=='forc':
        rt.push_scope()
        try:
            for st in s.init: exec_stmt(rt, st)
            while True:
                if s.cond is not None and not require_bool(eval_expr(s.cond, rt), s.cond):
                    break
                try: exec_block(rt, s.body)
                except ContinueExc: pass
                except BreakExc: break
                for st in s.incr: exec_stmt(rt, st)
        finally:
            rt.pop_scope()
        return
    if k=='forin':
        coll=eval_expr(s.coll, rt)
        entries=collection_entries(coll)
        rt.push_scope()
        try:
            for key_v, val_v in entries:
                if len(s.names)==1:
                    # map: key; array: value
                    v = val_v if coll.kind==ARRAY else key_v
                    rt.scopes[-1][s.names[0]]=[v.copy(),'var']
                else:
                    rt.scopes[-1][s.names[0]]=[key_v.copy(),'var']
                    rt.scopes[-1][s.names[1]]=[val_v.copy(),'var']
                try: exec_block(rt, s.body)
                except ContinueExc: pass
                except BreakExc: break
        finally: rt.pop_scope()
        return
    if k=='forinmulti':
        coll=eval_expr(s.coll, rt)
        flat=[]
        def rec(c, keys):
            if len(keys)==len(s.knames):
                flat.append((list(keys), c)); return
            for kk, vv in collection_entries(c):
                rec(vv, keys+[kk])
        rec(coll, [])
        rt.push_scope()
        try:
            for keys, val_v in flat:
                for nm, kv in zip(s.knames, keys):
                    rt.scopes[-1][nm]=[kv.copy(),'var']
                rt.scopes[-1][s.vname]=[val_v.copy(),'var']
                try: exec_block(rt, s.body)
                except ContinueExc: pass
                except BreakExc: break
        finally: rt.pop_scope()
        return
    if k=='break': raise BreakExc()
    if k=='continue': raise ContinueExc()
    if k=='return':
        raise ReturnExc(eval_expr(s.expr, rt) if s.expr is not None else None)
    if k=='callstmt':
        if s.name in rt.program.subrs:
            uf=rt.program.subrs[s.name]
            args=[eval_expr(x,rt) for x in s.args]
            call_user_function(uf, args, rt, name_for_msg=s.name)
            return
        # maybe a func called via call?
        if s.name in rt.program.funcs:
            args=[eval_expr(x,rt) for x in s.args]
            call_user_function(rt.program.funcs[s.name], args, rt, name_for_msg=s.name)
            return
        raise MlrError(f'function name not found: {s.name}')
    if k in ('print','printn','eprint','eprintn'):
        exec_print(rt, s); return
    if k in ('dump','edump'):
        text=json_stringify(rt.oos_map_value(), vstack=True, ofmt=rt.opts.ofmt if rt.opts else None)
        write_plain(rt, text+'\n', s.redir, default_stream=('stderr' if k=='edump' else 'stdout'))
        return
    if k=='teestmt':
        # tee writes current record to redirect destination
        if rt.rec is not None and rt.emit_callback:
            from collections import OrderedDict
            rt.emit_callback(OrderedDict((kk,vv.copy()) for kk,vv in rt.rec.items()), rt.ctx, s.redir, rt)
        return
    if k in ('emit','emitp','emitf','emit1'):
        exec_emit(rt, s); return
    if k=='unset':
        for t in s.targets: exec_unset(rt, t)
        return
    if k=='filterstmt':
        v=eval_expr(s.expr, rt)
        if v.kind==BOOL:
            rt.put_include=v.val
        return
    if k in ('begin','end','funcdef','subrdef'):
        # nested begin/end inside blocks: treat as no-op (top-level already extracted); funcdefs shouldn't occur
        return
    raise MlrError(f'internal: unhandled statement {k}')

def collection_entries(coll):
    if coll.kind==MAP:
        return [(k.copy(), v.copy()) for k,v in coll.val.items()]
    if coll.kind==ARRAY:
        return [(VInt(i+1), v.copy()) for i,v in enumerate(coll.val)]
    return []

def exec_assign(rt, target, op, rhs_node):
    rhs=eval_expr(rhs_node, rt)
    ref=ref_for(target, rt)
    if op=='=':
        ref.set(rhs); return
    cur=ref.get()
    new=apply_compound(op, cur, rhs, rt, target)
    ref.set(new)

def apply_compound(op, cur, rhs, rt, node_for_pos=None):
    # map compound to binary
    m={' +=':'+'}
    mp={'+=':'+','-=':'-','*=':'*','/=':'/','//=':'//','%=':'%','**=':'**','.=':'.','|=':'|','&=':'&','^=':'^','<<=':'<<','>>=':'>>','>>>=':'>>>','||=':'||','&&=':'&&','^^=':'^^','??=':'??','???=':'???'}
    bop=mp.get(op)
    if bop is None: return rhs
    if bop=='??':
        return rhs if cur.kind==ABSENT else cur
    if bop=='???':
        return rhs if cur.kind in (ABSENT,EMPTY) else cur
    if bop=='.':
        return eval_concat(cur, rhs)
    if bop in ('&&','||','^^'):
        # reuse logic functions with values (note short circuit side effects already evaluated rhs; acceptable except function calls in rhs for ||= etc - Miller AST $x||=f() is ($x || f()) with shortcircuit; our exec_assign evaluated rhs before. TODO: special-case in exec_assign later if tests.)
        if bop=='^^': return eval_logic_xor(bop,cur,rhs)
        # emulate via fake node? direct logic:
        if bop=='&&':
            if cur.kind==BOOL and not cur.val: return VBool(False)
            if rhs.kind==BOOL and not rhs.val: return VBool(False)
            if cur.kind==BOOL and cur.val and rhs.kind==BOOL: return rhs
            if cur.kind in (ABSENT,EMPTY,NULL) and rhs.kind==BOOL: return rhs
            if rhs.kind==ABSENT: return VAbsent()
            return make_bin_error(bop,cur,rhs)
        else:
            if cur.kind==BOOL and cur.val: return VBool(True)
            if rhs.kind==BOOL and rhs.val: return VBool(True)
            if cur.kind==BOOL and not cur.val and rhs.kind==BOOL: return rhs
            if cur.kind in (ABSENT,EMPTY,NULL) and rhs.kind==BOOL: return rhs
            if rhs.kind==ABSENT: return VAbsent()
            return make_bin_error(bop,cur,rhs)
    return eval_arith(bop, cur, rhs)

def exec_unset(rt, target):
    k=target.kind
    if k=='field':
        if rt.rec is not None: rt.rec.pop(target.name, None)
        return
    if k=='fullrec':
