    op, dest, is_stream=resolve_redirect_dest(rt, redir)
    if is_stream:
        out=sys.stderr if dest=='stderr' else sys.stdout
        out.write(text); out.flush(); return
    # file / pipe via redirect manager if available
    mgr=rt.gctx.redirects if rt.gctx else None
    if mgr is not None:
        mgr.write_plain(op, dest, text)
