                elif v2.kind==ARRAY:
                    if len(v2.val)==0:
                        leaves.append((p, v2))
                    else:
                        # array as leaf value (writer will flatten) - keep as one leaf
                        leaves.append((p, v2))
                else:
                    leaves.append((p, v2))
