BUILTINS={}  # name -> (allowed, func) allowed: int exact | set ints | ('variadic',min)
def bif(name, allowed):
    def deco(fn):
        BUILTINS[name]=(allowed, fn); return fn
    return deco

def is_builtin_name(name):
    return name in BUILTINS or name in _OPERATOR_NAMES

_OPERATOR_NAMES={'!','!=','!=~','%','&','&&','*','**','+','-','.','.*','.+','.-','./','/','//','<','<<','<=','<=>','==','=~','>','>=','>>','>>>','?:','??','???','^','^^','|','||','~'}

def _arity_msg(name, got, exp):
    word='argument' if got==1 else 'arguments'
    return f"function {name} invoked with {got} {word}; expected {exp}"

def check_arity(name, got):
    if name not in BUILTINS: return
    allowed,_=BUILTINS[name]
    ok=True; exp=None
    if isinstance(allowed,int):
        ok=(got==allowed); exp=allowed
    elif isinstance(allowed,(set,frozenset,tuple)) and allowed and allowed[0]=='variadic':
        ok=(got>=allowed[1])
    elif isinstance(allowed,(set,frozenset)):
        ok=(got in allowed)
    if not ok:
        if isinstance(allowed,int):
            raise MlrError(_arity_msg(name,got,allowed))
        else:
            raise MlrError(f'at CST BuildMultipleArityFunctionCallsiteNode: function name not found: {name}')

def call_builtin(name, args, rt):
    if name not in BUILTINS:
        raise MlrError(f'function name not found: {name}')
    check_arity(name, len(args))
    return BUILTINS[name][1](args, rt)

