def _latin1_to_utf8_str(s):
    # Argument in Miller is a Go string of bytes presumed latin1-encoded utf8? Input data read as bytes decoded... our strings are unicode from utf8 decoding or surrogateescape for invalid bytes (formats will decode with surrogateescape).
    try:
        b=s.encode('utf-8','surrogateescape')
        return b.decode('latin-1').encode('utf-8').decode('utf-8') if False else b.decode('latin-1')
    except Exception:
        return s
    # Explanation: bytes of the string (as read) interpreted as latin1 codepoints -> unicode string (which encodes to utf8 on output)
def _utf8_to_latin1_str(s):
    try:
        # unicode -> latin1 bytes -> reinterpret as bytes string via surrogateescape so output writes latin1 bytes
        b=s.encode('latin-1', errors='replace')  # Go function likely drops/replaces non-latin1? approximate
        return b.decode('utf-8','surrogateescape')
    except Exception:
        return s

