    if v.kind==STRING: return VString(fn(v.val))
    if v.kind==ARRAY: return VArray([_recurse_string(x,fn) for x in v.val])
    if v.kind==MAP:
        m=VMap()
        for k,val in v.val.items():
            nk=fn(k.to_plain_string()) if k.kind in (STRING,EMPTY) else k.to_plain_string()
