def _sub_impl(name,args,rt,global_flag,regex=True):
    s_v, pat_v, repl_v=args
    if s_v.kind==ABSENT: return VAbsent()
    if s_v.kind==NULL: return VNull()
    if s_v.kind==EMPTY: return VEmpty()
    if s_v.kind==ERROR: return s_v
    if pat_v.kind==ABSENT or repl_v.kind==ABSENT: return VAbsent()
    if pat_v.kind not in (STRING,EMPTY) or repl_v.kind not in (STRING,EMPTY,INT,FLOAT,BOOL):
        # repl may be stringified? test later
        if pat_v.kind not in (STRING,EMPTY): return err(name,pat_v)
    s=s_v.to_string() if s_v.kind not in (ARRAY,MAP) else json_stringify(s_v, vstack=False)
    pat=pat_v.to_plain_string(); repl=repl_v.to_string() if repl_v.kind!=EMPTY else ''
    if not regex:
        if pat=='':
