def _percentile_value(sorted_vals, p, interpolate=False):
    n=len(sorted_vals)
    if n==0: return VEmpty()
    if interpolate:
        if all(v.kind in (INT,FLOAT,EMPTY,NULL) for v in sorted_vals):
            nums=[v.as_float() if v.kind in (INT,FLOAT) else 0.0 for v in sorted_vals]
            rank=(p/100.0)*(n-1)
            lo=math.floor(rank); hi=math.ceil(rank)
            if lo==hi: return _num_result(nums[lo], all(v.kind==INT for v in sorted_vals))
            return VFloat(nums[lo]+(nums[hi]-nums[lo])*(rank-lo))
        # non-numeric interpolation falls back to nearest
    idx=int((p/100.0)*n)
    if idx>=n: idx=n-1
    if idx<0: idx=0
    return sorted_vals[idx]

