def _mode_impl(args, antimode=False):
    a=args[0]; vals=_collection_values(a)
    if vals is None: return err('mode',a)
    if not vals: return VEmpty()
    counts={}
    order=[]
    for v in vals:
        k=v.to_string()
        if k not in counts: counts[k]=(0,v); order.append(k)
        counts[k]=(counts[k][0]+1, counts[k][1])
    best=None
    for k in order:
        if best is None: best=k; continue
        if antimode:
            if counts[k][0]<counts[best][0]: best=k
        else:
            if counts[k][0]>counts[best][0]: best=k
    return counts[best][1]
