def _flatten_numeric_args(args):
    # min/max recurse into arrays/maps
    out=[]
    def rec(v):
        if v.kind==ARRAY:
            for x in v.val: rec(x)
        elif v.kind==MAP:
            for k,x in v.val.items(): rec(x)
        else:
            out.append(v)
    for a in args: rec(a)
    return out

def _minmax(args, want_max):
    vals=[]
    for v in _flatten_numeric_args(args):
        if v.kind in (EMPTY,ABSENT,NULL,ERROR):
            # "null loses": empty/absent/null are ignored unless all are?
            # But max(null,1) returned null in a probe with first arg null... That probe: max(null,1) => null. Hmm docs say null loses maybe meaning null is considered smallest? For max, 1 should win. Let's follow probe: if any null present, result is null? min("",1) gave 1, min($nope,1) 1. So empty/absent ignore, null propagates?
            if v.kind==NULL:
                return VNull()
            if v.kind==ERROR: return v
            continue
        vals.append(v)
    if not vals: return VEmpty()
    # Use DSL compare semantics: numbers numeric, else string compare mixed.
    best=vals[0]
    import dsl
    for v in vals[1:]:
        c=dsl.eval_compare('<=>', v, best)
        if c.kind==INT:
            if (want_max and c.val>0) or ((not want_max) and c.val<0):
                best=v
        elif c.kind==ERROR:
            return c
    return best

