    vals=_collection_values(a)
    if vals is None:
        return None, err(name,a)
    nums=[]; all_int=True
    for v in vals:
        if v.kind in (EMPTY,NULL):
            nums.append(0.0); all_int=False if False else all_int
            # empty treated as 0 int? mean [1,"",3] float due result non-integral anyway
        elif v.kind==ABSENT:
            nums.append(0.0)
        elif v.kind==INT:
            nums.append(float(v.val))
        elif v.kind==FLOAT:
            nums.append(v.val); all_int=False
        else:
            return None, err(name,v)
    return (nums, vals, all_int), None

def _num_result(x, all_int):
    if all_int and x==int(x) and abs(x)<=9.007199254740992e15:
        return VInt(int(x))
    return VFloat(x)

