def _sorted_collection_values(a):
    vals=_collection_values(a)
    if vals is None: return None
    import dsl
    # sort using numeric if all numeric(-ish), else string compare via eval_compare for sorting key using functools.cmp_to_key
    from functools import cmp_to_key
    def cmp(x,y):
        c=dsl.eval_compare('<=>',x,y)
        return c.val if c.kind==INT else 0
    return sorted(vals, key=cmp_to_key(cmp))

