# ---------- time ----------
from datetime import datetime, timezone, timedelta
try:
    from zoneinfo import ZoneInfo
except Exception:
    ZoneInfo=None

def _get_tz(rt, tzarg=None):
    name=None
    if tzarg is not None and tzarg.kind in (STRING,EMPTY) and tzarg.to_plain_string():
        name=tzarg.to_plain_string()
    elif rt is not None and rt.opts is not None and getattr(rt.opts,'tz',None):
        name=rt.opts.tz
    elif os.environ.get('TZ'):
        name=os.environ.get('TZ')
    if name:
        if name.startswith(':'): name=name[1:]
        if name in ('UTC','GMT','Z'): return timezone.utc
        if ZoneInfo is not None:
            try: return ZoneInfo(name)
            except Exception: pass
        # POSIX offset like EST5 etc fallback to local
    # local timezone
    return datetime.now().astimezone().tzinfo

def _frac_str(sec_float, digits):
    if digits<=0: return ''
    # fraction based on fractional part of seconds (floor for negative like Go time)
    frac=sec_float-math.floor(sec_float)
    # produce decimal digits truncated from repr-ish via multiplying
    # Use round to nearest at digit length? Go converts float seconds to nsec int64 truncating total nanos.
    nanos=int(frac*1_000_000_000)
    s=f"{nanos:09d}"
    if digits<=9:
        return '.'+s[:digits]
    return '.'+s+'0'*(digits-9)

def _fmt_epoch_sec(sec, tz, is_gmt, frac_digits=0, date_only=False):
    if isinstance(sec, float) and (math.isnan(sec) or math.isinf(sec)):
        return ''
    whole=math.floor(sec)
    try:
        dt=datetime.fromtimestamp(whole, tz=timezone.utc).astimezone(timezone.utc if is_gmt else tz)
    except Exception:
        return ''
    if date_only:
        return dt.strftime('%Y-%m-%d')
    if is_gmt:
        base=dt.strftime('%Y-%m-%dT%H:%M:%S')
        return base+_frac_str(sec,frac_digits)+'Z'
    else:
        base=dt.strftime('%Y-%m-%d %H:%M:%S')
        return base+_frac_str(sec,frac_digits)

def _fmt_epoch_nsec(ns, tz, is_gmt, frac_digits=0, date_only=False):
    sec=ns//1_000_000_000
    rem=ns%1_000_000_000
    try:
        dt=datetime.fromtimestamp(sec, tz=timezone.utc).astimezone(timezone.utc if is_gmt else tz)
    except Exception:
        return ''
    if date_only: return dt.strftime('%Y-%m-%d')
    frac=''
    if frac_digits>0:
        s=f"{rem:09d}"
        frac='.'+(s[:frac_digits] if frac_digits<=9 else s+'0'*(frac_digits-9))
    if is_gmt:
        return dt.strftime('%Y-%m-%dT%H:%M:%S')+frac+'Z'
    return dt.strftime('%Y-%m-%d %H:%M:%S')+frac

