def _yaml_scalar_value(raw, style, opts):
    # style: 'plain','single','double','literal','folded'
    if style in ('single','double','literal','folded'):
        return VString(raw)
    s=raw.strip()
    if s=='' or s in ('~','null','Null','NULL'):
        return VNull()
    if s in ('true','True','TRUE'): return VBool(True)
    if s in ('false','False','FALSE'): return VBool(False)
    # timestamp?
    ts=_yaml_timestamp(s)
    if ts is not None:
        return VString(ts)
    # int
    t=s.replace('_','')
    try:
        sign=1; body=t
        if body[:1] in ('+','-'):
            sign=-1 if body[0]=='-' else 1; body=body[1:]
        low=body.lower()
        if low.startswith('0x') and re.match(r'^0x[0-9a-fA-F]+$', body): return VInt(sign*int(body[2:],16))
        if low.startswith('0o') and re.match(r'^0o[0-7]+$', body): return VInt(sign*int(body[2:],8))
        if low.startswith('0b') and re.match(r'^0b[01]+$', body): return VInt(sign*int(body[2:],2))
        if re.match(r'^0[0-7]+$', body): return VInt(sign*int(body,8))
        if re.match(r'^[0-9]+$', body): return VInt(sign*int(body,10))
    except Exception:
        pass
    # float
    if s in ('.inf','.Inf','.INF','+.inf','+.Inf','+.INF'): return VFloat(math.inf)
    if s in ('-.inf','-.Inf','-.INF'): return VFloat(-math.inf)
    if s in ('.nan','.Nan','.NaN','.NAN'): return VFloat(math.nan)
    if re.match(r'^[+-]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][+-]?[0-9]+)?$', s) and ('.' in s or 'e' in s or 'E' in s):
        try: return VFloat(float(s))
        except: pass
    return VString(s)

def _yaml_timestamp(s):
    # returns Go time String or None
    m=re.match(r'^(\d{4})-(\d{1,2})-(\d{1,2})(?:[Tt ](\d{1,2}):(\d{2}):(\d{2})(?:\.(\d+))?(?:\s*(Z|[+-]\d{1,2}(?::?\d{2})?))?)?$', s)
    if not m: return None
    y,mo,d=int(m.group(1)),int(m.group(2)),int(m.group(3))
    hh=int(m.group(4) or 0); mm=int(m.group(5) or 0); ss=int(m.group(6) or 0)
    frac=m.group(7) or ''
    zone=m.group(8)
    fracstr=''
    if frac:
        # Go Time.String prints fractional only if nonzero, trailing zeros trimmed
        f=frac.rstrip('0')
        if f: fracstr='.'+f
