        else: off=f"{sign}{int(zh[:-2]):02d}{int(zh[-2:]):02d}"
        return f"{y:04d}-{mo:02d}-{d:02d} {hh:02d}:{mm:02d}:{ss:02d}{fracstr} {off} {off}"
        # zone name for fixed offset in Go is often "" leading to format "%s %s"?? approximate
    return f"{y:04d}-{mo:02d}-{d:02d} {hh:02d}:{mm:02d}:{ss:02d}{fracstr} +0000 UTC"

def _yaml_decode_double(s):
    out=[]; i=0
