        if opts.ifs_regex:
            parts=regex_split_no_groups(opts.ifs_regex, ln.strip())
            return [p for p in parts]
        if opts.ifs_explicit and opts.ifs not in (' ',):
            return _split_fields_lite(ln, opts)
        return ln.split()
    for lineno, ln in enumerate(lines, start=1):
        if _is_comment_line(ln, opts):
            if opts.comment_handling=='pass': items.append(('comment',ln))
            continue
        if ln.strip()=='':
            header=None; continue
        parts=split_line(ln)
        if parts is None:
            continue
        if opts.barred_input and ln.strip().startswith('+'):
            continue
        if header is None:
            header=parts; continue
        if len(parts)!=len(header) and not opts.allow_ragged_csv:
            raise MlrError(f'CSV header/data length mismatch {len(header)} != {len(parts)} at filename {filename} line {lineno}')
        pairs=[]
        for i,val in enumerate(parts):
            k=header[i] if i<len(header) else str(i+1)
            pairs.append((k, infer_value(val, opts.infer_opts())))
        rec_i+=1; items.append(('record', make_record(pairs,opts), ctx_for(rec_i)))
    return items, base_nr+rec_i

def _read_markdown_lines(lines, opts, filename, ctx_for, base_nr):
