def read_input_bytes(filename, opts):
    if opts.prepipe:
        with open(filename,'rb') as f:
            data=f.read()
        r=subprocess.run(opts.prepipe, shell=True, input=data, capture_output=True)
        return r.stdout
    if opts.prepipex:
        import shlex
        r=subprocess.run(opts.prepipex+' '+shlex.quote(filename), shell=True, capture_output=True)
        return r.stdout
    with open(filename,'rb') as f:
        data=f.read()
    low=filename.lower()
    if opts.gzin or low.endswith('.gz'):
        return gzip.decompress(data)
    if opts.bz2in or low.endswith('.bz2'):
        return bz2.decompress(data)
    if opts.zstdin or low.endswith('.zstd') or low.endswith('.zst'):
        # try external decoder
        import shutil
        exe=shutil.which('zstdcat') or shutil.which('unzstd') or shutil.which('zstd')
        if exe:
            args=[exe,'-dc'] if exe.endswith('zstd') else [exe]
            r=subprocess.run(args, input=data, capture_output=True)
            return r.stdout
        raise MlrError('zstd decompression not available')
    if opts.zin or low.endswith('.z'):
        try:
            return zlib.decompress(data)
        except Exception:
            return zlib.decompress(data, -15)
    return data

# ------------- writers -------------
def _encode(s):
    return s.encode('utf-8','surrogateescape')

def _yaml_needs_quote(s):
    if s=='' : return True
    low=s.lower()
    if low in ('true','false','null','~','yes','no','on','off','y','n','.inf','-.inf','.nan','+.inf'): return True
    if re.match(r'^[+-]?[0-9][0-9_]*$', s): return True
    if re.match(r'^[+-]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][+-]?[0-9]+)?$', s) and any(c in s for c in '.eE'): return True
    if re.match(r'^[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}', s): return True
    if re.match(r'^0[xXoObB]', s): return True
    if s.strip()!=s: return True
    if any(ord(c)<0x20 for c in s): return True
    if s[0] in '!&*?|>%@`,#[]{}:-?\'"': return True
    if ': ' in s or s.endswith(':') or ' #' in s: return True
    if '"' in s or '\\' in s: return True
    return False

def _yaml_scalar_str(v, opts):
    if v.kind==NULL or v.kind==EMPTY: return 'null'
    if v.kind==BOOL: return 'true' if v.val else 'false'
    if v.kind==INT: return str(v.val)  # YAML loses orig
    if v.kind==FLOAT:
        # Go yaml float formatting: uses shortest 'g' style but ensures decimal point? 1000 for 1e3 doc? It showed 1000. For 1.5 shows 1.5. Use Go-like from mlrval format_float
        return format_float(v.val) if not (math.isinf(v.val) or math.isnan(v.val)) else ('.inf' if v.val>0 else '-.inf' if v.val<0 else '.nan')
    if v.kind==ERROR: return '(error)'
    s=v.to_string()
    if _yaml_needs_quote(s):
        return json.dumps(s, ensure_ascii=False)
    return s

def _yaml_key_str(k, opts):
    if _yaml_needs_quote(k):
        return json.dumps(k, ensure_ascii=False)
    return k

def _yaml_lines_for_value(v, opts, indent):
    # returns list lines for a (possibly nested) value at this indent; scalar returns [scalar]
    if v.kind==MAP:
        if len(v.val)==0: return ['{}']
        lines=[]
        for k in sorted(v.val.keys_str()):
            val=v.val.get_str(k)
            ks=_yaml_key_str(k,opts)
            if val.kind in (MAP,ARRAY) and ((val.kind==MAP and len(val.val)>0) or (val.kind==ARRAY and len(val.val)>0)):
                lines.append(' '*indent+f"{ks}:")
                sub=_yaml_lines_for_value(val,opts,indent+2)
                lines.extend(sub)
            else:
                lines.append(' '*indent+f"{ks}: {_yaml_scalar_or_empty(val,opts)}")
        return lines
    if v.kind==ARRAY:
        if len(v.val)==0: return ['[]']
        lines=[]
        for el in v.val:
            if el.kind in (MAP,ARRAY) and ((el.kind==MAP and len(el.val)>0) or (el.kind==ARRAY and len(el.val)>0)):
                sub=_yaml_lines_for_value(el,opts,indent+2)
                # first line gets dash
                first=sub[0]
                lines.append(' '*indent+'- '+first.strip())
                lines.extend(sub[1:])
            else:
                lines.append(' '*indent+f"- {_yaml_scalar_or_empty(el,opts)}")
        return lines
    return [_yaml_scalar_str(v,opts)]

def _yaml_scalar_or_empty(v,opts):
    if v.kind==MAP and len(v.val)==0: return '{}'
    if v.kind==ARRAY and len(v.val)==0: return '[]'
    return _yaml_scalar_str(v,opts)

class Writer:
    def __init__(self, opts, out_binary):
        self.opts=opts; self.out=out_binary
        self.fmt=opts.output_format
        self.wrote_any=False
        self._csv_first_keys=None
        self._lite_prev_keys=None; self._lite_started=False; self._lite_pending_blank=False; self._lite_saw_record=False
        self._json_started=False; self._json_first=True
        self._pprint_groups=[]  # list of records buffers? We'll group dynamically for pprint/md
        self._group_keys=None; self._group_recs=[]
        self._yaml_recs=[]
        self._xtab_first=True
    def write(self, rec, ctx):
        # -x check
        if self.opts.error_if_error_field:
            self._check_errors(rec, ctx)
        fmt=self.fmt
        if fmt in ('json','jsonl'):
            self._write_json(rec); return
        if fmt=='yaml':
            if self.opts.yarray:
                self._yaml_recs.append(rec)
            else:
                if self.wrote_any:
                    self._w('---\n')
                self._write_yaml_record(rec, array_style=False)
                self.wrote_any=True
            return
        # prepare flattened if appropriate
        if self.opts.auto_flatten:
            rec2=flatmod.flatten_record(rec, self.opts.flatsep)
        else:
            rec2=rec
        if fmt in ('pprint','markdown','csvlite','tsvlite','asv','usv'):
            self._write_grouped(fmt, rec2); return
        if fmt in ('csv','tsv'):
            self._write_csv_proper(rec2); return
        if fmt=='dkvp':
            parts=[f"{k}{self.opts.ops}{v.to_string(self.opts.ofmt)}" for k,v in rec2.items()]
            self._w(self.opts.ofs.join(parts)+self.opts.ors); self.wrote_any=True; return
        if fmt=='nidx':
            parts=[v.to_string(self.opts.ofmt) for k,v in rec2.items()]
            self._w(self.opts.ofs.join(parts)+self.opts.ors); self.wrote_any=True; return
        if fmt=='xtab':
            self._write_xtab(rec2); return
        if fmt=='dcf':
            for k,v in rec2.items():
                self._w(f"{k}: {v.to_string(self.opts.ofmt)}\n")
            self._w('\n'); self.wrote_any=True; return
        # fallback dkvp
        parts=[f"{k}={v.to_string(self.opts.ofmt)}" for k,v in rec2.items()]
        self._w(','.join(parts)+'\n')
    def finish(self):
        fmt=self.fmt
        if fmt in ('pprint','markdown'):
            self._flush_group(final=True)
        elif fmt in ('csvlite','tsvlite','asv','usv'):
            # grouped-lite streaming didn't buffer except pending blanks handling in _write_grouped; flush pending blank at end if needed for csvlite empty-only/tail
            if self._lite_pending_blank:
                self._w(self.opts.ors)
                self._lite_pending_blank=False
            elif self._lite_saw_record and not self._lite_started:
                self._w(self.opts.ors)
        if fmt in ('json',):
            if self.opts.jlistwrap and self._json_started:
                self._w('\n]\n')
        if fmt=='yaml' and self.opts.yarray:
            if not self._yaml_recs:
                self._w('[]\n')
            else:
                for rec in self._yaml_recs:
                    self._write_yaml_record(rec, array_style=True)
        # jsonl no final
    def _w(self, s):
        self.out.write(_encode(s))
        # flushing policy: Python buffered; main finish flushes stdout.
    def _check_errors(self, rec, ctx):
        def find(v):
            if v.kind==ERROR: return v
            if v.kind==ARRAY:
                for x in v.val:
                    e=find(x)
                    if e: return e
            if v.kind==MAP:
                for k,x in v.val.items():
                    e=find(x)
                    if e: return e
            return None
        for k,v in rec.items():
            e=find(v)
            if e is not None:
                msg=e.errmsg or '(error)'
                # Note this error is reported specially in main (-x) - encode in exception message with marker
                raise _DataError(ctx, k, msg)
    # JSON
    def _write_json(self, rec):
        opts=self.opts
        # build record value
        if opts.auto_unflatten:
            mv=flatmod.unflatten_record(rec, opts.flatsep)
        else:
            mv=VMap()
            for k,v in rec.items(): mv.val.set_str(k,v)
        is_jsonl=(self.fmt=='jsonl')
        listwrap=False if is_jsonl else opts.jlistwrap
        vstack=False if is_jsonl else opts.jvstack
        s=json_stringify(mv, vstack=vstack, ofmt=opts.ofmt, quote_all=opts.jvquoteall)
        if listwrap:
            if not self._json_started:
                self._w('[\n'); self._json_started=True; self._json_first=True
            if not self._json_first:
                self._w(',\n')
            self._w(s); self._json_first=False
        else:
            self._w(s+'\n')
        self.wrote_any=True
    # YAML
    def _write_yaml_record(self, rec, array_style):
        opts=self.opts
        if opts.auto_flatten:
            rec2=flatmod.flatten_record(rec, opts.flatsep)
            mv=VMap()
            for k,v in rec2.items(): mv.val.set_str(k,v)
        else:
            mv=VMap()
            for k,v in rec.items(): mv.val.set_str(k,v)
        if len(mv.val)==0:
            self._w('- {}\n' if array_style else '{}\n'); return
        lines=_yaml_lines_for_value(mv, opts, 0)
        if array_style:
            # first line prefixed "- ", rest indented 2
            out=[]
            for i,ln in enumerate(lines):
                if i==0: out.append('- '+ln)
                else: out.append('  '+ln)
            self._w('\n'.join(out)+'\n')
        else:
            self._w('\n'.join(lines)+'\n')
    # CSV proper
    def _csv_row(self, fields):
        delim=self.opts.ofs if self.opts.ofs else ','
        d=delim[0] if len(delim)>=1 else ','
        out=[]
        for f in fields:
            needs=self.opts.quote_all or (d in f) or '"' in f or '\r' in f or '\n' in f or f=='\\.'
            if needs:
                out.append('"'+f.replace('"','""')+'"')
            else:
                out.append(f)
        return delim.join(out)+self.opts.ors
    def _is_prefix(self, a,b):
        return len(a)<=len(b) and b[:len(a)]==a
    def _write_csv_proper(self, rec):
        keys=list(rec.keys())
        vals=[rec[k].to_string(self.opts.ofmt) for k in keys]
        if self._csv_first_keys is None:
            self._csv_first_keys=keys
            if not self.opts.headerless_csv_output:
                if self.fmt=='tsv':
                    self._w(self._tsv_row(keys))
                else:
                    self._w(self._csv_row(keys))
        else:
            fk=self._csv_first_keys
            if not (self._is_prefix(keys,fk) or self._is_prefix(fk,keys)):
                fmtname='CSV' if self.fmt=='csv' else 'TSV'
                raise _SchemaError(f'{fmtname} schema change: first keys "{self.opts.ofs.join(fk)}"; current keys "{self.opts.ofs.join(keys)}"')
            if len(keys)<len(fk):
                # pad missing trailing fields with empty to header length (values are first n)
                vals=vals+['']*(len(fk)-len(keys))
        if self.fmt=='tsv':
            self._w(self._tsv_row(vals))
        else:
            self._w(self._csv_row(vals))
        self.wrote_any=True
    def _tsv_row(self, fields):
        return self.opts.ofs.join(_tsv_escape(x) for x in fields)+self.opts.ors
    # grouped / lite
    def _write_grouped(self, fmt, rec):
        keys=list(rec.keys())
        if fmt in ('csvlite','tsvlite','asv','usv'):
            self._lite_saw_record=True
            if not keys:
                # act as separator pending
                self._lite_prev_keys=None
                self._lite_pending_blank=True
                return
            if self._lite_pending_blank:
                self._w(self.opts.ors); self._lite_pending_blank=False
                self._lite_prev_keys=None
            if keys!=self._lite_prev_keys:
                if self._lite_started:
                    self._w(self.opts.ors)
                if not self.opts.headerless_csv_output:
                    self._w(self.opts.ofs.join(keys)+self.opts.ors)
                self._lite_prev_keys=keys; self._lite_started=True
            self._w(self.opts.ofs.join(rec[k].to_string(self.opts.ofmt) for k in keys)+self.opts.ors)
            self.wrote_any=True
            return
        # pprint / markdown buffered groups
        if self._group_keys is None:
            self._group_keys=keys; self._group_recs=[rec]
        elif keys==self._group_keys:
            self._group_recs.append(rec)
        else:
            self._flush_group(final=False)
            self._group_keys=keys; self._group_recs=[rec]
    def _flush_group(self, final=False):
        if self._group_keys is None:
            return
        keys=self._group_keys; recs=self._group_recs
        self._group_keys=None; self._group_recs=[]
        fmt=self.fmt
        if fmt=='pprint':
            if not keys:
                # empty group prints nothing, but forces separator for next group via wrote_any logic: mark a flag by keeping wrote_any as-is; next flush will know via a separate attr
                self._pprint_after_empty=True
                return
            if self.wrote_any:
                self._w('\n')
            rows=[[r[k].to_string(self.opts.ofmt) for k in keys] for r in recs]
            widths=[]
            for ci,k in enumerate(keys):
                w=len(k)
                for row in rows: w=max(w,len(row[ci]))
                widths.append(w)
            ofs=self.opts.ofs
            if self.opts.barred_output:
                border='+'+'+'.join('-'*(w+2) for w in widths)+'+\n'
                self._w(border)
                def brow(cells):
                    parts=[]
                    for ci,cell in enumerate(cells):
                        if self.opts.pprint_right: parts.append(' '+cell.rjust(widths[ci])+' ')
                        else: parts.append(' '+cell.ljust(widths[ci])+' ')
                    return '|'+'|'.join(parts)+'|\n'
                self._w(brow(keys)); self._w(border)
                for row in rows: self._w(brow(row))
                self._w(border)
            else:
                def fmt_row(cells):
                    out=''
                    for ci,cell in enumerate(cells):
                        if ci < len(cells)-1:
                            if self.opts.pprint_right:
                                out+= ofs*(widths[ci]-len(cell)) + cell + ofs
                            else:
                                out+= cell + ofs*(widths[ci]-len(cell)+1)
                        else:
                            if self.opts.pprint_right:
                                out+= ofs*(widths[ci]-len(cell)) + cell
                            else:
                                out+= cell
                    return out+self.opts.ors
                self._w(fmt_row(keys))
                for row in rows: self._w(fmt_row(row))
            self.wrote_any=True
            return
        if fmt=='markdown':
            if self.wrote_any:
                self._w('\n')
            if not keys:
                self._w('|\n|\n')
                for r in recs: self._w('|\n')
                self.wrote_any=True; return
            self._w('| '+' | '.join(keys)+' |\n')
            self._w('| '+' | '.join(['---']*len(keys))+' |\n')
            for r in recs:
                self._w('| '+' | '.join(r[k].to_string(self.opts.ofmt) for k in keys)+' |\n')
            self.wrote_any=True
            return
    def _write_xtab(self, rec):
        opts=self.opts
        if not self._xtab_first:
            self._w(opts.ofs)  # extra separator between records
        self._xtab_first=False
        if not rec:
            return
        maxk=max(len(k) for k in rec.keys())
        maxvlen=max(len(v.to_string(opts.ofmt)) for v in rec.values()) if opts.xtab_xvright else 0
        for k,v in rec.items():
            vs=v.to_string(opts.ofmt)
            if len(opts.ops)==1:
                line=k+opts.ops*(maxk-len(k)+1)+ (vs.rjust(maxvlen) if opts.xtab_xvright else vs)
            else:
                line=k+opts.ops+(vs.rjust(maxvlen) if opts.xtab_xvright else vs)
            self._w(line+opts.ofs)
        self.wrote_any=True

class _SchemaError(MlrError):
    pass
class _DataError(Exception):
    def __init__(self, ctx, field, msg):
        self.ctx=ctx; self.field=field; self.msg=msg
    def format(self):
        c=self.ctx
        nr=c.nr if c else 1; fnr=c.fnr if c else 1; fn=c.filename if c else '(stdin)'
        return f"mlr: data error at NR={nr} FNR={fnr} FILENAME={fn}\nmlr: field {self.field}: {self.msg}\nmlr: exiting due to data error\n"

# Redirect manager
class RedirectManager:
    def __init__(self, gctx):
        self.gctx=gctx
        self.writers={}  # key -> (Writer, fileobj_or_None, pipe_or_None, is_stream)
        self.plain={}  # key -> fileobj/pipe/stream marker
        self.order=[]
    def _writer_key(self, op, dest, opts):
        return (op,dest,opts.output_format,opts.ofs,opts.ops,opts.ors,opts.ofmt,opts.flatsep,opts.jlistwrap,opts.jvstack,opts.headerless_csv_output,opts.quote_all,opts.auto_flatten,opts.auto_unflatten,opts.barred_output,opts.pprint_right,opts.xtab_xvright)
    def write_record(self, redir, rec, ctx, opts):
        op,dest,is_stream=redir
        if is_stream:
            out=sys.stderr.buffer if dest=='stderr' else sys.stdout.buffer
            key=self._writer_key(op,('stream',dest),opts)
            entry=self.writers.get(key)
            if entry is None:
                w=Writer(opts, out); entry=(w,None,None,True); self.writers[key]=entry; self.order.append(entry)
            entry[0].write(rec,ctx); out.flush(); return
        key=self._writer_key(op,dest,opts)
        entry=self.writers.get(key)
        if entry is None:
            if op=='|':
                proc=subprocess.Popen(dest, shell=True, stdin=subprocess.PIPE)
                w=Writer(opts, proc.stdin); entry=(w,None,proc,False)
            else:
                mode='ab' if op=='>>' else 'wb'
                f=open(dest,mode)
                w=Writer(opts,f); entry=(w,f,None,False)
            self.writers[key]=entry; self.order.append(entry)
        entry[0].write(rec,ctx)
    def write_plain(self, op, dest, text):
        key=(op,dest)
        if key not in self.plain:
