def read_input_bytes(filename, opts):
    if opts.prepipe:
        with open(filename,'rb') as f:
            data=f.read()
        r=subprocess.run(opts.prepipe, shell=True, input=data, capture_output=True)
        return r.stdout
    if opts.prepipex:
        import shlex
        r=subprocess.run(opts.prepipex+' '+shlex.quote(filename), shell=True, capture_output=True)
        return r.stdout
    with open(filename,'rb') as f:
        data=f.read()
    low=filename.lower()
    if opts.gzin or low.endswith('.gz'):
        return gzip.decompress(data)
    if opts.bz2in or low.endswith('.bz2'):
        return bz2.decompress(data)
    if opts.zstdin or low.endswith('.zstd') or low.endswith('.zst'):
        # try external decoder
        import shutil
        exe=shutil.which('zstdcat') or shutil.which('unzstd') or shutil.which('zstd')
        if exe:
            args=[exe,'-dc'] if exe.endswith('zstd') else [exe]
            r=subprocess.run(args, input=data, capture_output=True)
            return r.stdout
        raise MlrError('zstd decompression not available')
    if opts.zin or low.endswith('.z'):
        try:
            return zlib.decompress(data)
        except Exception:
            return zlib.decompress(data, -15)
    return data

