# ---------- simple stream verbs ----------
@spec('cat', {'-n':'flag','-N':'value','-g':'value','--filename':'flag','--filenum':'flag'})
class CatV(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx)
        self.do_n=_flag(cfg,'-n') or ('-N' in cfg)
        self.nname=_opt(cfg,'-N',default='n')
        self.groups=_fields(cfg,'-g')
        self.counters={}; self.counter=0
    def process(self,rec,ctx):
        if self.do_n:
            if self.groups:
                k=group_key_tuple(rec,self.groups)
                self.counters[k]=self.counters.get(k,0)+1; n=self.counters[k]
            else:
                self.counter+=1; n=self.counter
            new=OrderedDict(); new[self.nname]=VInt(n)
            for kk,vv in rec.items():
                if kk!=self.nname: new[kk]=vv
                else: new[kk]=vv  # position stays front? If name already exists, assigning above then overwrite would lose counter; handle:
            # fix overwrite case: counter at front wins as prepended, original field with same name is overridden (Miller PutAtStart probably replaces)
            new[self.nname]=VInt(n)
            # move to front already first
            rec=new
        prepend=[]
        if _flag(self.cfg,'--filename'):
            prepend.append(('filename', VString(ctx.filename if ctx else '(stdin)')))
        if _flag(self.cfg,'--filenum'):
            prepend.append(('filenum', VInt(ctx.filenum if ctx else 1)))
        if prepend:
            new=OrderedDict()
            for k,v in prepend: new[k]=v
            for k,v in rec.items():
                if k not in new: new[k]=v
            rec=new
        self.emit(rec,ctx)

@spec('nothing',{})
class NothingV(Base):
    def process(self,rec,ctx): pass

@spec('check',{})
class CheckV(Base):
    def process(self,rec,ctx):
        for k in rec.keys():
            if k=='':
                sys.stderr.write(f"mlr: check: empty key at NR={ctx.nr if ctx else '?'}\n")
        # no output

@spec('skip-trivial-records',{})
class SkipTrivV(Base):
    def process(self,rec,ctx):
        if len(rec)==0: return
        if all(v.kind==EMPTY for v in rec.values()): return
        self.emit(rec,ctx)

@spec('cut', {'-f':'value','-o':'flag','-x':'flag','--complement':'flag','-r':'flag'})
class CutV(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx)
        if '-f' not in cfg: raise MlrError('mlr cut: -f field names required')
        self.order=_flag(cfg,'-o'); self.compl=_flag(cfg,'-x','--complement'); self.regex=_flag(cfg,'-r')
        if self.regex:
            self.patterns=[compile_field_regex(p) for p in split_field_list(cfg['-f'],keep_quotes=True)]
            self.fields=None
        else:
            self.fields=split_field_list(cfg['-f']); self.patterns=None
    def _matches(self,k):
        if self.patterns is not None:
            return any(p.search(k) for p in self.patterns)
        return k in self.fields
    def process(self,rec,ctx):
        out=OrderedDict()
        if self.order and not self.regex and not self.compl:
            for f in self.fields:
                if f in rec: out[f]=rec[f]
        else:
            for k,v in rec.items():
                m=self._matches(k)
                if m ^ self.compl:
                    out[k]=v
            if self.order and self.regex:
                # reorder by pattern order matching in record order per pattern (approximate)
                ordered=OrderedDict()
                for p in self.patterns:
                    for k in list(out.keys()):
                        if p.search(k) and k not in ordered: ordered[k]=out[k]
                for k,v in out.items():
                    if k not in ordered: ordered[k]=v
                out=ordered
            if self.order and not self.regex and self.compl:
                pass
        self.emit(out,ctx)

@spec('rename', {'-r':'flag','-g':'flag'}, positionals=1)
class RenameV(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx)
        pos=cfg.get('__pos__',[])
        if not pos: raise MlrError('mlr rename: field names required')
        parts=split_field_list(pos[0], keep_quotes=_flag(cfg,'-r'))
        if len(parts)%2!=0:
            raise MlrError('mlr rename: rename requires an even number of field names')
        self.pairs=[(parts[i],parts[i+1]) for i in range(0,len(parts),2)]
        self.regex=_flag(cfg,'-r'); self.glob=_flag(cfg,'-g')
        self.compiled=[compile_field_regex(p) for p,_ in self.pairs] if self.regex else None
    def process(self,rec,ctx):
        out=OrderedDict()
        for k,v in rec.items():
            nk=k
            if self.regex:
                for (old,new),pat in zip(self.pairs,self.compiled):
                    def repl(m,new=new):
                        return re.sub(r'\\([1-9])', lambda mm: m.group(int(mm.group(1))) if int(mm.group(1))<= (m.lastindex or 0) and m.group(int(mm.group(1))) is not None else '', new)
                    if pat.search(nk):
                        nk=pat.sub(repl,nk,count=0 if self.glob else 1)
            else:
                for old,new in self.pairs:
                    if nk==old: nk=new; break
            out[nk]=v
        self.emit(out,ctx)

@spec('reorder', {'-e':'flag','-f':'value','-r':'flag','-b':'value','-a':'value'})
class ReorderV(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx)
        self.fields=_fields(cfg,'-f')
        self.regex=_flag(cfg,'-r')
        self.patterns=[compile_field_regex(p) for p in split_field_list(cfg.get('-f',''),keep_quotes=True)] if self.regex else None
        self.at_end=_flag(cfg,'-e')
        self.before=_opt(cfg,'-b'); self.after=_opt(cfg,'-a')
    def _selected_keys(self, rec):
        if self.patterns is not None:
            sel=[]
            for p in self.patterns:
                for k in rec.keys():
                    if p.search(k) and k not in sel: sel.append(k)
            return sel
        return [f for f in self.fields if f in rec]
    def process(self,rec,ctx):
        sel=self._selected_keys(rec)
        rest=[k for k in rec.keys() if k not in sel]
        if self.before is not None or self.after is not None:
            anchor=self.before if self.before is not None else self.after
            if anchor not in rec:
                self.emit(rec,ctx); return
            # build without selected, insert sel before/after anchor
            keys=[]
            for k in rest:
                if self.before is not None and k==anchor:
                    keys.extend(sel)
                keys.append(k)
                if self.after is not None and k==anchor:
                    keys.extend(sel)
            # anchor could be in sel? then above fails: if anchor was selected, it is in sel not rest; Miller likely (?) just emit original
            if set(keys)!=set(rec.keys()):
                self.emit(rec,ctx); return
        else:
            keys=(rest+sel) if self.at_end else (sel+rest)
        self.emit(OrderedDict((k,rec[k]) for k in keys),ctx)

@spec('label', {}, positionals=1)
class LabelV(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx)
        pos=cfg.get('__pos__',[])
        self.names=split_field_list(pos[0]) if pos else []
    def process(self,rec,ctx):
        out=OrderedDict()
        for i,(k,v) in enumerate(rec.items()):
            out[self.names[i] if i<len(self.names) else k]=v
        self.emit(out,ctx)

@spec('template', {'-f':'value','-t':'value','--fill-with':'value'})
class TemplateV(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx)
        self.fill=_opt(cfg,'--fill-with',default='')
        if '-t' in cfg:
            # read CSV header line from file (separator based on? csv/tsv etc - use input ifs if explicit? Use comma default)
            with open(cfg['-t'],'r',encoding='utf-8',errors='surrogateescape') as f:
                line=f.readline().strip('\r\n')
            delim='\t' if cfg['-t'].lower().endswith('.tsv') else ','
            import csv, io
            self.fields=list(next(csv.reader(io.StringIO(line), delimiter=delim)))
        else:
            self.fields=_fields(cfg,'-f')
    def process(self,rec,ctx):
        out=OrderedDict()
        fillv=infer_value(self.fill, self.opts.infer_opts()) if isinstance(self.fill,str) else VString('')
        # --fill-with filler string as string or inferred? Tests later: default empty. Miller likely infers type like other fill options? Keep inferred for now but if empty keep Empty.
        if self.fill=='': fillv=VEmpty()
        for f in self.fields:
            out[f]=rec[f] if f in rec else fillv.copy()
        self.emit(out,ctx)

def _sort_keys_rec(v, recursive):
    if v.kind==MAP:
        items=sorted(v.val.items(), key=lambda kv: kv[0].to_plain_string())
        m=VMap()
        for k,val in items:
            m.val.set_str(k.to_plain_string(), _sort_keys_rec(val,recursive) if recursive else val)
        return m
    if v.kind==ARRAY and recursive:
        return VArray([_sort_keys_rec(x,recursive) for x in v.val])
    return v

@spec('regularize',{})
class RegularizeV(Base):
    def process(self,rec,ctx):
        self.emit(OrderedDict((k,rec[k]) for k in sorted(rec.keys())),ctx)
@spec('sort-within-records',{' -r':'flag','-r':'flag'})
class SortWithinV(Base):
    def process(self,rec,ctx):
        rec2=OrderedDict((k,rec[k]) for k in sorted(rec.keys()))
        if _flag(self.cfg,'-r'):
            for k in list(rec2.keys()):
                rec2[k]=_sort_keys_rec(rec2[k],True)
        self.emit(rec2,ctx)

@spec('having-fields',{'--at-least':'value','--which-are':'value','--at-most':'value','--all-matching':'value','--any-matching':'value','--none-matching':'value'})
class HavingV(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx)
        self.mode=None; self.names=[]; self.pat=None
        for kk in ('--at-least','--which-are','--at-most'):
            if kk in cfg: self.mode=kk; self.names=split_field_list(cfg[kk])
        for kk in ('--all-matching','--any-matching','--none-matching'):
            if kk in cfg: self.mode=kk; self.pat=compile_field_regex(cfg[kk])
        if self.mode is None: raise MlrError('mlr having-fields: one of --at-least, --which-are, --at-most, --all-matching, --any-matching, --none-matching is required')
    def process(self,rec,ctx):
        keys=set(rec.keys()); ok=False
        if self.mode=='--at-least': ok=set(self.names)<=keys
        elif self.mode=='--which-are': ok=set(self.names)==keys
        elif self.mode=='--at-most': ok=keys<=set(self.names)
        elif self.mode=='--all-matching': ok=all(self.pat.search(k) for k in rec.keys()) if rec else False
        elif self.mode=='--any-matching': ok=any(self.pat.search(k) for k in rec.keys())
        elif self.mode=='--none-matching': ok=not any(self.pat.search(k) for k in rec.keys())
        if ok: self.emit(rec,ctx)

@spec('clean-whitespace',{'k':'flag','-k':'flag','--keys-only':'flag','-v':'flag','--values-only':'flag'})
class CleanWSV(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx)
        self.keys_only=_flag(cfg,'-k','--keys-only'); self.vals_only=_flag(cfg,'-v','--values-only')
        if self.keys_only and self.vals_only: raise MlrError('mlr clean-whitespace: -k and -v are mutually exclusive')
    def process(self,rec,ctx):
        def clean_str(s): return re.sub(r'\s+',' ',s).strip()
        def clean_val(v):
            if v.kind in (STRING,EMPTY): return VString(clean_str(v.to_plain_string()))
            if v.kind==ARRAY: return VArray([clean_val(x) for x in v.val])
            if v.kind==MAP:
                m=VMap()
                for k,val in v.val.items():
                    nk=clean_str(k.to_plain_string()) if not self.vals_only else k.to_plain_string()
                    m.val.set_str(nk, clean_val(val) if not self.keys_only else val)
                return m
            return v
        out=OrderedDict()
        for k,v in rec.items():
            nk=k if self.vals_only else clean_str(k)
            out[nk]=v if self.keys_only else clean_val(v)
        self.emit(out,ctx)

