@spec('case',{' -k':'flag','-k':'flag','-v':'flag','-f':'value','-u':'flag','-l':'flag','-s':'flag','-t':'flag'})
class CaseV(Base):
    def process(self,rec,ctx):
        mode='upper'
        if _flag(self.cfg,'-l'): mode='lower'
        if _flag(self.cfg,'-s'): mode='sentence'
        if _flag(self.cfg,'-t'): mode='title'
        if _flag(self.cfg,'-u'): mode='upper'
        fields=_fields(self.cfg,'-f') if '-f' in self.cfg else None
        keys_only=_flag(self.cfg,'-k'); vals_only=_flag(self.cfg,'-v')
        def convert(s):
            if mode=='upper': return s.upper()
            if mode=='lower': return s.lower()
            if mode=='sentence': return s[0].upper()+s[1:] if s else s
            if mode=='title': return re.sub(r"[A-Za-z]+('[a-z]*)?", lambda m: m.group(0)[0].upper()+m.group(0)[1:].lower() if False else m.group(0).capitalize(), s) if False else ' '.join((w[0].upper()+w[1:] if w else w) for w in s.split(' '))
            return s
        def conv_val(v):
            if v.kind==STRING: return VString(convert(v.val))
            if v.kind==ARRAY: return VArray([conv_val(x) for x in v.val])
            if v.kind==MAP:
                m=VMap()
                for k,val in v.val.items():
                    nk=k.to_plain_string() if vals_only else convert(k.to_plain_string())
                    m.val.set_str(nk, val if keys_only else conv_val(val))
                return m
            return v
        out=OrderedDict()
        for k,v in rec.items():
            target=(fields is None or k in fields)
            nk=convert(k) if (target and not vals_only) else k
            out[nk]=conv_val(v) if (target and not keys_only) else v
        self.emit(out,ctx)

