    def process(self,rec,ctx):
        sep=_opt(self.cfg,'-s',default=self.opts.flatsep)
        fields=_fields(self.cfg,'-f') if '-f' in self.cfg else None
        if fields is None:
            mv=flatmod.unflatten_record(rec, sep)
            self.emit(fmtmod.record_from_map_value(mv),ctx); return
        out=OrderedDict()
        # group selected fields by first component? Miller -f is list of field NAMES to unflatten (exact names with dots). Unflatten only those names into nested under first part.
        selected=[k for k in rec.keys() if k in fields]
        sub=OrderedDict((k,rec[k]) for k in selected)
        nested=flatmod.unflatten_record(sub, sep) if sub else VMap()
        inserted=False
        for k,v in rec.items():
            if k in fields:
                if not inserted:
                    for nk,nv in nested.val.d.items(): out[nk]=nv
                    inserted=True
                continue
            out[k]=v
        self.emit(out,ctx)

