        self.seen_fields=[]  # for streaming specified fields mode
    def process(self,rec,ctx):
        if self.fields is not None:
            out=OrderedDict()
            # Order: ? fields in -f order perhaps interleaved with other fields in record order. Miller example not for -f. We'll produce record order, inserting missing specified fields at their -f relative positions? Simpler: start with record order; append missing in -f order at end.
