            if f in out and out[f].kind!=EMPTY:
                self.last[f]=out[f].copy()
            elif f in out and not only_absent:
                pass
            elif f in out:
                self.last[f]=out[f].copy()
        # also track fields not in specified list if --all for future fill insertions order? above included last keys
        self.emit(out,ctx)

