def _normalize_c_format(fmt):
    # Convert C long formats like %lld %lf %.6le %08llx to Go/Python-ish.
    # Long specifiers: remove l/ll before verb.
    return re.sub(r'%(?P<main>[-+ 0#]*[0-9]*(?:\.[0-9]*)?)(?:ll|l|h)(?P<verb>[a-zA-Z])', r'%\g<main>\g<verb>', fmt)

def _format_value(v,ifmt,ffmt,sfmt,coerce=False):
    if v.kind==ARRAY:
        return VArray([_format_value(x,ifmt,ffmt,sfmt,coerce) for x in v.val])
    if v.kind==MAP:
        m=VMap()
        for k,val in v.val.items(): m.val.set_str(k.to_plain_string(), _format_value(val,ifmt,ffmt,sfmt,coerce))
        return m
    if v.kind==INT and not coerce:
        f=_normalize_c_format(ifmt)
        try: return VString(bifs._go_sprintf(f, v))
        except: return v
    if v.kind in (INT,FLOAT) and (v.kind==FLOAT or coerce):
        return VString(bifs._go_sprintf(_normalize_c_format(ffmt), VFloat(v.as_float())))
    if v.kind in (STRING,EMPTY,BOOL,NULL):
        f=_normalize_c_format(sfmt)
        s=v.to_string()
        try:
            if '%s' in f or '%v' in f:
                return VString(f.replace('%v','%s') % s if '%s' in f or '%v' in f else f)
            return VString(f % s)
        except:
            return VString(s)
    return v

