def _natural_cmp_key(s):
    parts=re.split(r'(\d+)',s)
    key=[]
    for p in parts:
        if p.isdigit(): key.append((1,int(p),len(p)))  # tie? longer leading zeros
        else: key.append((0,p))
    return key

def compare_for_sort(a,b,kind):
    # kind in f,r,c,cr,n,nr,t,tr
    # returns cmp for a vs b for ASCENDING variant of kind; caller reverses sign for descending outside for n null logic handling separately
    if kind in ('n','nf'):
        # handled special caller
        pass
    sa=a.to_string(); sb=b.to_string()
    if kind in ('c','cr'):
        sa=sa.casefold(); sb=sb.casefold()
        return (sa>sb)-(sa<sb)
    if kind in ('t','tr','rt'):
        ka=_natural_cmp_key(sa); kb=_natural_cmp_key(sb)
        return (ka>kb)-(ka<kb)
    return (sa>sb)-(sa<sb)

