        if k=='field': return '$'+n.name
        if k=='oosvar': return '@'+n.name
        if k=='fullrec': return '$*'
        if k=='fulloos': return '@*'
        if k=='name': return n.name
        if k=='intlit' or k=='floatlit': return n.value.to_string()
        if k=='stringlit': return '"'+n.value+'"'
        if k=='boollit': return 'true' if n.value else 'false'
        if k=='nulllit': return 'null'
        if k=='binary': return f"({n.op} {expr_sexpr(n.left)} {expr_sexpr(n.right)})"
        if k=='unary': return f"({n.op} {expr_sexpr(n.operand)})"
        if k=='ternary': return f"(?: {expr_sexpr(n.cond)} {expr_sexpr(n.then)} {expr_sexpr(n.els)})"
        if k=='call': return f"({n.name} {' '.join(expr_sexpr(x) for x in n.args)})".replace(' )',')')
        if k=='index': return f"([] {expr_sexpr(n.base)} {expr_sexpr(n.index)})"
        if k=='ctxvar': return n.name
        if k=='arraylit': return "([] "+' '.join(expr_sexpr(x) for x in n.elems)+")"
        return k
    def stmt_sexpr(s):
        if s.kind=='assign': return f"(= {expr_sexpr(s.target)} {expr_sexpr(s.rhs)})" if s.op=='=' else f"(= {expr_sexpr(s.target)} ({s.op[:-1]} {expr_sexpr(s.target)} {expr_sexpr(s.rhs)}))"
        if s.kind=='exprstmt': return expr_sexpr(s.expr)
        if s.kind=='begin': return "(begin "+' '.join(stmt_sexpr(x) for x in s.body)+")"
        if s.kind=='end': return "(end "+' '.join(stmt_sexpr(x) for x in s.body)+")"
        return f"({s.kind})"
    return "(statement-block "+' '.join(stmt_sexpr(s) for s in stmts)+")"

