import sys, os, re, io, time, signal, shutil
try:
    signal.signal(signal.SIGPIPE, signal.SIG_DFL)
except Exception:
    pass
from collections import OrderedDict
from opts import Options
from ctx import GlobalCtx, RecCtx
from errors import MlrError, MlrRawError, EarlyExit
import cliparse
import verbs as verbmod
import formats as fmtmod
import dsl as dslmod
import helpmod

VERSION='6.16.0'
TERMINALS={'help','version','aux-list','hex','unhex','lecat','termcvt','repl','regtest'}

class Cursor:
    def __init__(self,tokens): self.tokens=tokens; self.i=0
    def peek(self):
        return self.tokens[self.i] if self.i<len(self.tokens) else None
    def advance(self):
        t=self.peek();
        if t is not None: self.i+=1
        return t
    def remaining(self): return self.tokens[self.i:]

def _missing_arg(tok):
    raise MlrError(f'option "{tok}" missing argument(s).\nPlease run "mlr --help" for detailed usage information.')
def _unknown_global(tok):
    raise MlrError(f'option "{tok}" not recognized.\nPlease run "mlr --help" for usage information.')

_SHORT_GLOBAL_FLAGS={'c','t','j','p','T','N','S','A','O','x','I','n','M','C','h'}
_ACTION_SHORT={'g':'flags','l':'list-verbs','L':'usage-verbs','f':'list-functions','F':'usage-functions','k':'list-keywords','K':'usage-keywords'}

def _do_action(name):
    # returns text to print for action flag topics
    from help_data import DATA
    key=_ACTION_SHORT.get(name)
    if key:
        sys.stdout.write(DATA.get('topic_map',{}).get(key) or DATA.get(key.replace('-','_'),''))
        # topic_map keys include list-verbs etc
        raise EarlyExit(0)

def parse_global(cur, opts, state, stop_on_nonflag=True):
    while True:
        tok=cur.peek()
        if tok is None: break
        if not tok.startswith('-') or tok=='-':
            break
        if tok in ('--help','-h'):
            sys.stdout.write(helpmod.DATA.get('main_help','')); raise EarlyExit(0)
        if tok=='--version':
            sys.stdout.write(f'mlr {VERSION}\n'); raise EarlyExit(0)
        if tok=='--list-color-names':
            sys.stdout.write(helpmod.DATA.get('list_color_names','')); raise EarlyExit(0)
        if tok=='--list-color-codes':
            sys.stdout.write(helpmod.DATA.get('list_color_codes','')); raise EarlyExit(0)
        if len(tok)==2 and tok[1] in _ACTION_SHORT:
            cur.advance(); _do_action(tok[1])
        # bundled short flags
        if re.match(r'^-[A-Za-z]{2,}$', tok) and all(ch in _SHORT_GLOBAL_FLAGS or ch in _ACTION_SHORT for ch in tok[1:]):
            cur.advance()
            for ch in tok[1:]:
                if ch in _ACTION_SHORT: _do_action(ch)
                if ch=='h': sys.stdout.write(helpmod.DATA.get('main_help','')); raise EarlyExit(0)
                cliparse.apply_global_flag(opts,'-'+ch,None,state)
            continue
        base=tok.split('=',1)[0] if tok.startswith('--') else tok
        kind=cliparse.global_flag_kind(base)
        if kind is None:
            _unknown_global(tok)
        cur.advance()
        if kind=='multi':
            vals=[]
            while cur.peek() is not None and cur.peek()!='--':
                vals.append(cur.advance())
            if cur.peek()=='--': cur.advance()
            if base=='--mfrom': state.setdefault('from_files',[]).extend(vals)
            elif base=='--mload': opts.load_files.extend(vals)
            continue
        if kind=='value':
            if '=' in tok and tok.startswith('--'):
                val=tok.split('=',1)[1]
            else:
                if cur.peek() is None: _missing_arg(tok)
                val=cur.advance()
            cliparse.apply_global_flag(opts,base,val,state)
        else:
            # flag; inline = ignored (?) if present, reference may treat as unrecognized but accept approximating
            cliparse.apply_global_flag(opts,base,None,state)

def _verb_missing_arg(verb,tok):
    raise MlrError(f'mlr {verb}: option "{tok}" missing argument(s)')
def _verb_unknown(verb,tok):
    raise MlrError(f'mlr {verb}: option "{tok}" not recognized')

def match_verb_option(spec, tok):
    """return (canonical,kind,inline_value_or_None) or None"""
    if spec is None: return None
    opts=spec.options
    if tok in opts:
        return tok, opts[tok], None
    if tok.startswith('--') and '=' in tok:
        name,val=tok.split('=',1)
        if name in opts:
            return name, opts[name], val
    if tok.startswith('-') and not tok.startswith('--') and '=' not in tok:
        # longest prefix option expecting value
        candidates=[name for name,kind in opts.items() if kind in ('value','multi') and tok.startswith(name) and len(tok)>len(name)]
        if candidates:
            name=max(candidates,key=len)
            return name, opts[name], tok[len(name):]
    return None

def expand_bundled_verb_flags(spec,tok):
    if spec is None: return None
    if not re.match(r'^-[A-Za-z]{2,}$',tok): return None
    out=[]
    chars=tok[1:]
    ind=0
    # Greedy account for two-letter options like -cr in sort? Bundled handling only for chars each flag; sort has -c and -r separate kinds value so not flags. Only expand if every char maps to flag-kind option.
    for ch in chars:
        name='-'+ch
        if name not in spec.options or spec.options[name]!='flag':
            return None
        out.append(name)
    return out

def parse_one_verb(name, cur, opts, state):
    spec=verbmod.SPECS.get(name)
    cfg={'__order__':[],'__pieces__':[],'__writer_flags__':[]}
    pos=[]; stopped=None
    while True:
        tok=cur.peek()
        if tok is None: stopped='eof'; break
        if tok=='then': stopped='then'; break
        if tok in ('-h','--help'):
            sys.stdout.write(helpmod.verb_usage(name)); raise EarlyExit(0)
        # writer/global flags for put/filter/tee/split before positional satisfied
        allow_writer=getattr(spec,'allow_writer_flags',False) if spec else False
        if allow_writer and cliparse.is_global_flag(tok) and (spec is None or tok.split('=',1)[0] not in spec.options):
            # consume global flag into writer flags
            base=tok.split('=',1)[0] if tok.startswith('--') else tok
            kind=cliparse.global_flag_kind(base)
            cur.advance()
            if kind=='value':
                if '=' in tok and tok.startswith('--'): val=tok.split('=',1)[1]
                else:
                    if cur.peek() is None: _verb_missing_arg(name,tok)
                    val=cur.advance()
                cfg['__writer_flags__'].append((base,val))
            elif kind=='multi':
                # not valid writer flag; treat as unknown
                _verb_unknown(name,tok)
            else:
                cfg['__writer_flags__'].append((base,None))
            continue
        if tok.startswith('-') and tok!='-':
            m=match_verb_option(spec,tok)
            if m is None:
                bundled=expand_bundled_verb_flags(spec,tok)
                if bundled:
                    cur.advance()
                    for bname in bundled:
                        cfg[bname]=True; cfg['__order__'].append((bname,True))
                    continue
                _verb_unknown(name,tok)
            canon,kind,inline=m
            cur.advance()
            if kind=='flag':
                cfg[canon]=True; cfg['__order__'].append((canon,True))
            else:
                if inline is not None: val=inline
                else:
                    if cur.peek() is None: _verb_missing_arg(name,tok)
                    val=cur.advance()
                if kind=='multi':
                    cfg.setdefault(canon,[]).append(val)
                else:
                    cfg[canon]=val
                cfg['__order__'].append((canon,val))
                if name in ('put','filter'):
                    if canon=='-f': cfg['__pieces__'].append(('file',val))
                    elif canon=='-e': cfg['__pieces__'].append(('expr',val))
            continue
        # positional
        needed=spec.positionals if spec else 0
        if len(pos)<needed:
            pos.append(tok); cur.advance()
            cfg['__order__'].append(('__pos__',tok))
            if name in ('put','filter'):
                cfg['__pieces__'].append(('expr',tok))
            if len(pos)>=needed:
                stopped='positional_done'; break
