def parse_cli(argv):
    opts=Options(); state={'from_files':[],'files_files':[]}
    cur=Cursor(argv)
    # cpuprofile first-position handling
    if cur.peek()=='--cpuprofile':
        cur.advance();
        if cur.peek() is None: _missing_arg('--cpuprofile')
        state['cpuprofile']=cur.advance()
    if cur.peek()=='--traceprofile':
        cur.advance();
        if cur.peek() is None: _missing_arg('--traceprofile')
        state['traceprofile']=cur.advance()
    parse_global(cur,opts,state)
    # terminals after global flags
    tok=cur.peek()
    if tok in TERMINALS:
        return ('terminal', tok, cur.remaining()[1:], opts, state)
    verb_specs=[]; filenames=[]
    if cur.peek() is None:
        raise _NoVerbError()
    while True:
        tok=cur.peek()
        if tok is None:
            if not verb_specs: raise _NoVerbError()
            break
        if tok=='then':
            raise MlrError("'then' must have a verb before it.")
        if tok not in verbmod.VERBS:
            if tok in TERMINALS:
                return ('terminal',tok,cur.remaining()[1:],opts,state)
            raise MlrError(f'verb "{tok}" not found. Please use "mlr -l" for a list.')
        name=cur.advance()
        cfg, stopped=parse_one_verb(name,cur,opts,state)
        verb_specs.append((name,cfg))
        if stopped=='then':
            cur.advance()  # consume then
            if cur.peek() is None:
                raise MlrError("'then' must have a verb after it.")
            continue
        if stopped=='positional_done':
            # resume global flags (only dash tokens), then maybe then/filenames
            parse_global(cur,opts,state)
            if cur.peek()=='then':
                cur.advance()
                if cur.peek() is None:
                    raise MlrError("'then' must have a verb after it.")
                continue
            filenames=cur.remaining(); break
        # filename/eof
        filenames=cur.remaining(); break
    return ('pipeline', verb_specs, filenames, opts, state)

class _NoVerbError(Exception):
    pass

def load_mlrrc_tokens(argv):
    # check --norc among tokens before first verb/terminal
    for t in argv:
        if t=='--norc': return []
        if t in verbmod.VERBS or t in TERMINALS: break
    files=[]
    env=os.environ.get('MLRRC')
    if env is not None:
        if env=='__none__':
            return []
        files=[env]
    else:
        home=os.environ.get('HOME','')
        if home and os.path.exists(os.path.join(home,'.mlrrc')):
            files.append(os.path.join(home,'.mlrrc'))
        if os.path.exists('.mlrrc'):
            lp=os.path.abspath('.mlrrc')
            hp=os.path.abspath(os.path.join(home,'.mlrrc')) if home else None
            if lp!=hp: files.append('.mlrrc')
            elif not files: files.append('.mlrrc')
    tokens=[]
    for path in files:
        try:
            text=open(path,'r',encoding='utf-8',errors='surrogateescape').read()
        except Exception:
            continue
        for line in text.splitlines():
            s=line.strip()
            if not s or s.startswith('#'): continue
            # remove trailing comments? sample comments are full line only; keep simple if ' #'
            # Split first token and remainder
            parts=s.split(None,1)
            flag=parts[0]
            if flag.startswith('#'): continue
            if not flag.startswith('-'):
                flag='--'+flag
            tokens.append(flag)
            if len(parts)>1:
                tokens.append(parts[1].strip())
    return tokens

def expand_flag_files(argv):
    import shlex
    argv=list(argv)
    # expand -s / --s-no-comment-strip only before first verb/terminal, iteratively
    for _ in range(20):
        idx=None; strip=True
        for i,t in enumerate(argv):
            if t in verbmod.VERBS or t in TERMINALS:
                break
            if t in ('-s','--s-no-comment-strip'):
                idx=i; strip=(t=='-s'); break
        if idx is None: break
        if idx+1>=len(argv):
            # let parser produce missing arg later (as global value flag)
            break
        path=argv[idx+1]
        try:
            text=open(path,'r',encoding='utf-8',errors='surrogateescape').read()
        except FileNotFoundError:
            raise MlrError(f'open {path}: no such file or directory')
        try:
            new_tokens=shlex.split(text, comments=strip, posix=True)
        except Exception as e:
            raise MlrError(str(e))
        argv=argv[:idx]+new_tokens+argv[idx+2:]
    return argv

