def build_chain(verb_specs, gctx, writer):
    transformers=[]
    for name,cfg in verb_specs:
        spec=verbmod.SPECS.get(name)
        if spec is None or spec.factory is None:
            raise MlrError(f'verb "{name}" not implemented in this build')
        t=spec.factory(cfg,gctx)
        transformers.append(t)
    # link downstream
    def make_down(next_t):
        return lambda rec,ctx: next_t.process(rec,ctx)
    for i,t in enumerate(transformers):
        if i+1<len(transformers):
            t.downstream=make_down(transformers[i+1])
        else:
            t.downstream=lambda rec,ctx: writer.write(rec,ctx)
    return transformers

def run_pipeline(verb_specs, filenames, opts, state):
    gctx=GlobalCtx(opts)
    # RNG setup
    from gorand import GoRand
    if opts.seed is not None:
        gctx.rng=GoRand(opts.seed)
    else:
        gctx.rng=GoRand(time.time_ns() & ((1<<63)-1))
    gctx.redirects=fmtmod.RedirectManager(gctx)
    if opts.tz:
        os.environ['TZ']=opts.tz
        try: time.tzset()
        except Exception: pass
    # collect input filenames
    files=[]
    files.extend(state.get('from_files',[]))
    for ff in state.get('files_files',[]):
        try:
            lines=open(ff,'r',encoding='utf-8',errors='surrogateescape').read().splitlines()
        except FileNotFoundError:
            raise MlrError(f'open {ff}: no such file or directory')
        for line in lines:
            if line.strip()!='': files.append(line.strip())
    files.extend(filenames)
    if opts.in_place:
        if not files:
            # Miller with -I and no files? just run stdin normal
            opts2=opts
        for path in files:
            _run_one_source_set(verb_specs,[path],opts,state,gctx_template=(opts,state), in_place_path=path)
        if files:
            return 0
    return _run_one_source_set(verb_specs,files,opts,state,gctx=gctx)

def _run_one_source_set(verb_specs, files, opts, state, gctx=None, gctx_template=None, in_place_path=None):
    if gctx is None:
        gctx=GlobalCtx(opts)
        from gorand import GoRand
        gctx.rng=GoRand(opts.seed if opts.seed is not None else (time.time_ns() & ((1<<63)-1)))
        gctx.redirects=fmtmod.RedirectManager(gctx)
    tmp_out=None; tmp_path=None
    if in_place_path is not None:
        import tempfile
        directory=os.path.dirname(os.path.abspath(in_place_path))
        fd,tmp_path=tempfile.mkstemp(dir=directory, prefix='.mlr_tmp_')
        tmp_out=os.fdopen(fd,'wb')
        writer=fmtmod.Writer(opts,tmp_out)
    else:
        writer=fmtmod.Writer(opts,sys.stdout.buffer)
    gctx.writer=writer
    transformers=build_chain(verb_specs,gctx,writer)
    first_filename=files[0] if files else '(stdin)'
    ctx0=RecCtx(0,0,first_filename,1)
    for t in transformers:
        t.start(ctx0)
    current_nr=1
    progress_mod=state.get('nr_progress_mod') if isinstance(state,dict) else None
    def process_items(items):
        nonlocal current_nr
        for item in items:
            if item[0]=='comment':
                sys.stdout.buffer.write((item[1]+'\n').encode('utf-8','surrogateescape'))
                sys.stdout.buffer.flush()
            else:
                _,rec,ctx=item
                if progress_mod and ctx.nr % progress_mod==0:
                    sys.stderr.write(f"{ctx.filename} {ctx.nr}\n")
                transformers[0].process(rec,ctx)
    if transformers:
        head=transformers[0]
    else:
        head=None
    if opts.no_input:
        pass
    elif opts.input_format=='gen':
        items,next_nr=fmtmod.read_records_from_text('',opts,'(stdin)',1,current_nr)
        process_items(items); current_nr=next_nr
    elif not files:
        data=sys.stdin.buffer.read()
        # decompress stdin if flags force
        if opts.prepipe:
            import subprocess
            data=subprocess.run(opts.prepipe,shell=True,input=data,capture_output=True).stdout
        else:
            if opts.gzin: data=fmtmod.gzip.decompress(data)
            elif opts.bz2in: data=fmtmod.bz2.decompress(data)
            elif opts.zin:
                try: data=fmtmod.zlib.decompress(data)
                except: data=fmtmod.zlib.decompress(data,-15)
        text=data.decode('utf-8','surrogateescape')
        items,next_nr=fmtmod.read_records_from_text(text,opts,'(stdin)',1,current_nr)
        process_items(items); current_nr=next_nr
    else:
        for filenum,path in enumerate(files,1):
            data=fmtmod.read_input_bytes(path,opts)
            text=data.decode('utf-8','surrogateescape')
            items,next_nr=fmtmod.read_records_from_text(text,opts,path,filenum,current_nr)
            process_items(items); current_nr=next_nr
    for t in transformers:
        t.finish()
    writer.finish()
    if in_place_path is not None:
        tmp_out.flush(); tmp_out.close()
        os.replace(tmp_path,in_place_path)
    if gctx.redirects is not None:
        gctx.redirects.finish()
    return 0

