def _read_aux_inputs(files):
    if not files:
        return sys.stdin.buffer.read()
    out=b''
    for f in files:
        with open(f,'rb') as fh: out+=fh.read()
    return out

def do_hex(args):
    raw='-r' in args
    files=[a for a in args if a not in ('-r','-h','--help')]
    if '-h' in args or '--help' in args:
        sys.stdout.write(helpmod.DATA.get('aux_hex_help','Usage: mlr hex [options] {zero or more file names}\n')); return 0
    data=_read_aux_inputs(files)
    out=[]
    for off in range(0,len(data),16):
        chunk=data[off:off+16]
        hexpart=''
        groups=[]
        for gi in range(4):
            grp=chunk[gi*4:(gi+1)*4]
            groups.append(' '.join('%02x'%b for b in grp))
        hexs='  '.join(groups)
        # pad hex area to width for 16 bytes: compute full width
        full_groups=[]
        for gi in range(4): full_groups.append(' '.join(['00']*4))
        fullw=len('  '.join(full_groups))
        hexs_padded=hexs.ljust(fullw)
        if raw:
            out.append(hexs_padded+'\n')
        else:
            asc=''.join(chr(b) if 32<=b<127 else '.' for b in chunk)
            out.append(f"{off:08x}: {hexs_padded} |{asc}|\n")
    sys.stdout.buffer.write(''.join(out).encode()); return 0

def do_unhex(args):
    if '-h' in args or '--help' in args:
        sys.stdout.write(helpmod.DATA.get('aux_unhex_help','Usage: mlr unhex [option] {zero or more file names}\n')); return 0
    files=[a for a in args if not a.startswith('-')]
    data=_read_aux_inputs(files).decode('utf-8','ignore')
    out=bytearray()
    for tok in re.split(r'\s+',data):
        if re.fullmatch(r'[0-9a-fA-F]{2}',tok or ''):
            out.append(int(tok,16))
    sys.stdout.buffer.write(bytes(out)); return 0

def do_lecat(args):
    if '-h' in args or '--help' in args:
        sys.stdout.write(helpmod.DATA.get('aux_lecat_help','Usage: mlr lecat [options] {zero or more file names}\n')); return 0
    mono='--mono' in args
    files=[a for a in args if a!='--mono']
    data=_read_aux_inputs(files)
    if mono:
        out=data.replace(b'\r',b'[CR]').replace(b'\n',b'[LF]\n')
    else:
        out=data.replace(b'\r',b'\x1b[31m[CR]\x1b[0m').replace(b'\n',b'\x1b[32m[LF]\x1b[0m\n')
    sys.stdout.buffer.write(out); return 0

def do_termcvt(args):
    modes={'--cr2crlf':(b'\r',b'\r\n'),'--lf2crlf':(b'\n',b'\r\n'),'--crlf2cr':(b'\r\n',b'\r'),'--crlf2lf':(b'\r\n',b'\n'),'--cr2lf':(b'\r',b'\n'),'--lf2cr':(b'\n',b'\r')}
    chosen=[a for a in args if a in modes]
    if '-h' in args or '--help' in args:
        sys.stdout.write(helpmod.DATA.get('aux_termcvt_help','Usage: mlr termcvt [option] {zero or more file names}\n')); return 0
    if len(chosen)!=1:
        sys.stderr.write(helpmod.DATA.get('aux_termcvt_help','Usage: mlr termcvt [option] {zero or more file names}\n')); return 1
    src,dst=modes[chosen[0]]
    files=[a for a in args if a not in modes and a!='-I']
    inplace='-I' in args
    if inplace and files:
        for f in files:
            data=open(f,'rb').read().replace(src,dst)
            open(f,'wb').write(data)
        return 0
    data=_read_aux_inputs(files).replace(src,dst)
    sys.stdout.buffer.write(data); return 0

def do_terminal(name,args,opts):
    if name=='help':
        return helpmod.do_help(args)
    if name=='version':
        sys.stdout.write(helpmod.DATA.get('version_long','mlr version 6.16.0 for linux/amd64/go1.24.0\n')); return 0
    if name=='aux-list':
        sys.stdout.write(helpmod.DATA.get('aux_list','Available entries:\n  mlr aux-list\n  mlr hex\n  mlr lecat\n  mlr termcvt\n  mlr unhex\nFor more information, please invoke mlr {subcommand} --help.\n')); return 0
    if name=='hex': return do_hex(args)
    if name=='unhex': return do_unhex(args)
    if name=='lecat': return do_lecat(args)
    if name=='termcvt': return do_termcvt(args)
    if name=='repl':
        return do_repl(args,opts)
    if name=='regtest':
        return do_regtest(args)
    return 1

def do_repl(args,opts):
    if '-h' in args or '--help' in args:
        text=helpmod.DATA.get('repl_help_template','')
        # replace program name 'executable' captured at capture time with basename of argv0
        prog=os.path.basename(sys.argv[0]) or 'mlr'
        text=text.replace('Usage: executable repl', f'Usage: {prog} repl',1)
        sys.stdout.write(text); return 0
    # Basic REPL implementation (see repl module)
    import replmod
    return replmod.run_repl(args,opts)

def do_regtest(args):
    if '-h' in args or '--help' in args:
        sys.stdout.write(helpmod.DATA.get('regtest_help','Usage: mlr regtest [options] [one or more directories/files]\n')); return 0
    import regtestmod
    return regtestmod.run_regtest(args)

def main(argv=None):
    if argv is None: argv=sys.argv[1:]
    start=time.time()
    try:
        argv=expand_flag_files(argv)
        rc_tokens=load_mlrrc_tokens(argv)
        if rc_tokens:
            argv=rc_tokens+argv
        result=parse_cli(argv)
        if result[0]=='terminal':
            _,name,targs,opts,state=result
            return do_terminal(name,targs,opts)
        _,verb_specs,filenames,opts,state=result
        rc=run_pipeline(verb_specs,filenames,opts,state)
        if state.get('time'):
            sys.stderr.write(f"{time.time()-start:.3f}\n")
        # flush
        try: sys.stdout.buffer.flush()
        except: pass
        return rc
    except EarlyExit as e:
        try: sys.stdout.buffer.flush()
        except: pass
        return e.code
    except _NoVerbError:
        try: sys.stdout.buffer.flush()
        except: pass
        sys.stderr.write("mlr: no verb supplied.\n"+helpmod.DATA.get('main_help','Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}\n'))
        return 1
    except fmtmod._SchemaError as e:
        try: sys.stdout.buffer.flush()
        except: pass
        sys.stderr.write(f"mlr: {e}\nmlr: exiting due to data error\n"); return 1
    except fmtmod._DataError as e:
        try: sys.stdout.buffer.flush()
        except: pass
        sys.stderr.write(e.format()); return 1
    except dslmod.PanicExc as e:
        try: sys.stdout.buffer.flush()
        except: pass
        sys.stderr.write(str(e)+"\n"); return 2
    except MlrRawError as e:
        try: sys.stdout.buffer.flush()
        except: pass
        sys.stderr.write(str(e)); return 1
    except MlrError as e:
        try: sys.stdout.buffer.flush()
        except: pass
        msg=str(e)
        sys.stderr.write("mlr: "+msg+("" if msg.endswith('\n') else "\n")); return 1
    except FileNotFoundError as e:
        try: sys.stdout.buffer.flush()
        except: pass
        path=e.filename or ''
        sys.stderr.write(f"mlr: open {path}: no such file or directory\n"); return 1
    except BrokenPipeError:
        try:
            devnull=os.open(os.devnull, os.O_WRONLY); os.dup2(devnull, sys.stdout.fileno())
        except Exception: pass
        return 0
    except KeyboardInterrupt:
        return 130

if __name__=='__main__':
    sys.exit(main())
