def build_chain(verb_specs, gctx, writer):
    transformers=[]
    for name,cfg in verb_specs:
        spec=verbmod.SPECS.get(name)
        if spec is None or spec.factory is None:
            raise MlrError(f'verb "{name}" not implemented in this build')
        t=spec.factory(cfg,gctx)
        transformers.append(t)
    # link downstream
    def make_down(next_t):
        return lambda rec,ctx: next_t.process(rec,ctx)
    for i,t in enumerate(transformers):
        if i+1<len(transformers):
            t.downstream=make_down(transformers[i+1])
        else:
            t.downstream=lambda rec,ctx: writer.write(rec,ctx)
    return transformers

