        if all_int:
            s=sum(int(v.val) for v in vals if v.kind==INT)
            return VInt(s) if INT64_MIN<=s<=INT64_MAX else VFloat(float(s))
        return VFloat(sum(nums))
    if n==0: return VEmpty()
    if acc=='mean':
        return bifs._num_result(sum(nums)/n, all_int)
    if acc=='mad':
        mu=sum(nums)/n; return VFloat(sum(abs(x-mu) for x in nums)/n)
    if acc in ('var','stddev','meaneb','skewness','kurtosis'):
        if n<2: return VEmpty()
        mu=sum(nums)/n
        if acc=='var': return VFloat(sum((x-mu)**2 for x in nums)/(n-1))
        if acc=='stddev': return VFloat(math.sqrt(sum((x-mu)**2 for x in nums)/(n-1)))
        if acc=='meaneb': return VFloat(math.sqrt(sum((x-mu)**2 for x in nums)/(n-1))/math.sqrt(n))
        if acc=='skewness':
            svar=sum((x-mu)**2 for x in nums)/(n-1); m3=sum((x-mu)**3 for x in nums)/n
            return VFloat(m3/(svar**1.5) if svar else math.nan)
        if acc=='kurtosis':
            m2=sum((x-mu)**2 for x in nums)/n; m4=sum((x-mu)**4 for x in nums)/n
            return VFloat(m4/(m2*m2)-3 if m2 else math.nan)
    return VEmpty()

def _dynamic_fields(buf, specified, regex_str, inverse_regex_str):
    if specified:
        return list(specified)
    pats=[]
    fields=[]
    if regex_str:
        pats=[compile_field_regex(p) for p in split_field_list(regex_str,keep_quotes=True)]
        for rec,ctx in buf:
            for k in rec.keys():
                if any(p.search(k) for p in pats) and k not in fields: fields.append(k)
        return fields
    if inverse_regex_str:
        pats=[compile_field_regex(p) for p in split_field_list(inverse_regex_str,keep_quotes=True)]
        for rec,ctx in buf:
            for k in rec.keys():
                if not any(p.search(k) for p in pats) and k not in fields: fields.append(k)
        return fields
    return []

@spec('stats1',{' -a':'value','-a':'value','-f':'value','--fr':'value','--fx':'value','-g':'value','--gr':'value','--gx':'value','--grfx':'value','-i':'flag','-s':'flag'})
class Stats1V(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx); self.buf=[]
        if '-a' not in cfg: raise MlrError('mlr stats1: -a option is required')
        self.accs=_parse_stats1_accs(cfg['-a'])
        if '-f' not in cfg and '--fr' not in cfg and '--fx' not in cfg and '--grfx' not in cfg:
            raise MlrError('mlr stats1: -f option is required')
        self.iterative=_flag(cfg,'-s'); self.interp=_flag(cfg,'-i')
        # for iterative, accumulators state managed per group incrementally via recomputation on buffered subsets
        self.groups_buf={}
        self.global_buf=[]
    def _value_fields(self, buf):
        if '--grfx' in self.cfg:
            fx=self.cfg['--grfx']
            return _dynamic_fields(buf,_fields(self.cfg,'-f'),None,fx)
        return _dynamic_fields(buf,_fields(self.cfg,'-f'),_opt(self.cfg,'--fr'),_opt(self.cfg,'--fx'))
    def _group_fields(self, buf):
        if '--grfx' in self.cfg:
            return _dynamic_fields(buf,_fields(self.cfg,'-g'),self.cfg['--grfx'],None)
        return _dynamic_fields(buf,_fields(self.cfg,'-g'),_opt(self.cfg,'--gr'),_opt(self.cfg,'--gx'))
    def process(self,rec,ctx):
        if not self.iterative:
            self.buf.append((copy_rec(rec),ctx)); return
        # iterative: buffer globally (need dynamic fields; if regex fields unknown ahead, values compute from current record fields matching)
        self.buf.append((copy_rec(rec),ctx))
        # Determine group for this record using all buf for dynamic field names (future fields not known, Miller streaming would use current record names)
        gfields=self._group_fields(self.buf)
        if gfields and any(f not in rec for f in gfields):
            self.emit(rec,ctx); return
        # subset records in same group up to current
        if gfields:
            key=group_key_tuple(rec,gfields)
            subset=[r for r,c in self.buf if all(f in r for f in gfields) and group_key_tuple(r,gfields)==key]
        else:
            subset=[r for r,c in self.buf]
        vfields=self._value_fields(self.buf)
        out=OrderedDict(rec)
        for f in vfields:
            vals=_present_values(subset,f)
            for acc in self.accs:
                out[f"{f}_{acc}"]=_stats1_compute(acc,vals,self.interp)
        self.emit(out,ctx)
    def finish(self):
        if self.iterative: return
        if not self.buf: return
        from ctx import RecCtx
        vfields=self._value_fields(self.buf); gfields=self._group_fields(self.buf)
        groups=OrderedDict()
        if not gfields:
            groups[()]=([r for r,c in self.buf], self.buf[-1][1], {})
        else:
            for rec,ctx in self.buf:
                if any(f not in rec for f in gfields): continue
                k=group_key_tuple(rec,gfields)
                if k not in groups:
                    groups[k]=([],ctx,{f:rec[f].copy() for f in gfields})
                groups[k][0].append(rec)
        for k,(records,ctx,gvals) in groups.items():
            out=OrderedDict()
            for f in gfields: out[f]=gvals[f]
            for f in vfields:
                vals=_present_values(records,f)
                # Miller doesn't emit any fields for a value field never present in group (observed -f nope gives empty record)
                if f not in self.cfg.get('-f','') and False: pass
                # Determine presence: if specified -f and never present -> skip all accs for that field (matches -f nope)
                if '-f' in self.cfg and len(vals)==0:
                    continue
                for acc in self.accs:
                    out[f"{f}_{acc}"]=_stats1_compute(acc,vals,self.interp)
            self.emit(out,ctx)

@spec('merge-fields',{' -a':'value','-a':'value','-f':'value','-r':'value','-c':'value','-i':'flag','-o':'value','-k':'flag'})
class MergeFieldsV(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx)
        if '-a' not in cfg: raise MlrError('mlr merge-fields: -a option is required')
        # merge-fields acc errors message likely different; reuse parse but intercept message? keep.
        try: self.accs=_parse_stats1_accs(cfg['-a'])
        except MlrError as e:
            raise MlrError(str(e).replace('stats1:','merge-fields:'))
    def process(self,rec,ctx):
        interp=_flag(self.cfg,'-i'); keep=_flag(self.cfg,'-k')
        if '-c' in self.cfg:
            subs=split_field_list(self.cfg['-c'])
            groups=OrderedDict()
            for k,v in rec.items():
                collapsed=k
                for sub in subs:
                    collapsed=collapsed.replace(sub,'')
                groups.setdefault(collapsed,[]).append(v)
            out=OrderedDict()
            if keep:
                for k,v in rec.items(): out[k]=v
            for collapsed,vals in groups.items():
                for acc in self.accs:
                    out[f"{collapsed}_{acc}"]=_stats1_compute(acc,vals,interp)
            self.emit(out,ctx); return
        # -f or -r mode requires -o
        if '-o' not in self.cfg: raise MlrError('mlr merge-fields: -o option is required')
        outname=self.cfg['-o']
        if '-r' in self.cfg:
            pats=[compile_field_regex(p) for p in split_field_list(self.cfg['-r'],keep_quotes=True)]
            selected=[k for k in rec.keys() if any(p.search(k) for p in pats)]
        else:
            selected=_fields(self.cfg,'-f')
        vals=[rec[k] for k in selected if k in rec]
        out=OrderedDict()
        for k,v in rec.items():
            if keep or k not in selected: out[k]=v
        for acc in self.accs:
            out[f"{outname}_{acc}"]=_stats1_compute(acc,vals,interp)
        self.emit(out,ctx)

# ---- stats2 ----
def _paired_numeric(records, xf,yf):
    pairs=[]
    for r in records:
        if xf in r and yf in r and r[xf].kind in (INT,FLOAT) and r[yf].kind in (INT,FLOAT):
            pairs.append((r[xf].as_float(), r[yf].as_float()))
    return pairs

def _ols(pairs):
    n=len(pairs)
    if n<2: return None
    mx=sum(x for x,y in pairs)/n; my=sum(y for x,y in pairs)/n
    sxx=sum((x-mx)**2 for x,y in pairs); sxy=sum((x-mx)*(y-my) for x,y in pairs); syy=sum((y-my)**2 for x,y in pairs)
    if sxx==0: return None
    m=sxy/sxx; b=my-m*mx
    return (m,b,n,mx,my,sxx,sxy,syy)

@spec('stats2',{' -a':'value','-a':'value','-f':'value','-g':'value','-v':'flag','-s':'flag','--fit':'flag'})
class Stats2V(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx); self.buf=[]
        if '-a' not in cfg: raise MlrError('mlr stats2: -a option is required')
        if '-f' not in cfg: raise MlrError('mlr stats2: -f option is required')
        self.accs=split_field_list(cfg['-a'])
        fields=_fields(cfg,'-f')
        if len(fields)%2!=0: raise MlrError('mlr stats2: -f must have an even number of field names')
        self.pairs=[(fields[i],fields[i+1]) for i in range(0,len(fields),2)]
        known={'linreg-ols','linreg-pca','r2','logireg','corr','cov','covx'}
        for a in self.accs:
            if a not in known: raise MlrError(f'stats2: accumulator "{a}" not found')
        if _flag(cfg,'-s') and _flag(cfg,'--fit'): raise MlrError('mlr stats2: only one of -s or --fit may be used')
    def process(self,rec,ctx):
        self.buf.append((copy_rec(rec),ctx))
        if _flag(self.cfg,'-s'):
            self._emit_iter(rec,ctx)
    def _group_records(self):
        gfields=_fields(self.cfg,'-g')
        groups=OrderedDict()
        if not gfields:
            if self.buf: groups[()]=([r for r,c in self.buf], self.buf[-1][1], {})
        else:
            for rec,ctx in self.buf:
                if any(f not in rec for f in gfields): continue
                k=group_key_tuple(rec,gfields)
                if k not in groups: groups[k]=([],ctx,{f:rec[f].copy() for f in gfields})
                groups[k][0].append(rec)
        return gfields,groups
    def _compute_pair_outputs(self, records, xf,yf, prefix):
        out=[]
        pairs=_paired_numeric(records,xf,yf); n=len(pairs)
        ols_res=_ols(pairs)
        for acc in self.accs:
            if acc=='linreg-ols':
                if ols_res is None:
                    out += [(f"{prefix}_ols_m",VEmpty()),(f"{prefix}_ols_b",VEmpty()),(f"{prefix}_ols_n",VInt(n))]
                else:
                    m,b,nn,mx,my,sxx,sxy,syy=ols_res
                    out += [(f"{prefix}_ols_m",VFloat(m) if not float(m).is_integer() else _stats_num(m)),(f"{prefix}_ols_b",_stats_num(b)),(f"{prefix}_ols_n",VInt(nn))]
            elif acc=='r2':
                if ols_res is None: out.append((f"{prefix}_r2",VEmpty()))
                else:
                    m,b,nn,mx,my,sxx,sxy,syy=ols_res
                    out.append((f"{prefix}_r2", VFloat((sxy*sxy)/(sxx*syy)) if sxx and syy else VEmpty()))
            elif acc=='corr':
                if n<2 or ols_res is None: out.append((f"{prefix}_corr",VEmpty()))
                else:
                    m,b,nn,mx,my,sxx,sxy,syy=ols_res
                    out.append((f"{prefix}_corr", VFloat(sxy/math.sqrt(sxx*syy)) if sxx and syy else VEmpty()))
            elif acc=='cov':
                if n<2 or ols_res is None: out.append((f"{prefix}_cov",VEmpty()))
                else:
                    out.append((f"{prefix}_cov", VFloat(ols_res[6]/(n-1))))
            elif acc=='covx':
                if n<2 or ols_res is None:
                    out += [(f"{xf}_{xf}_covx",VEmpty()),(f"{xf}_{yf}_covx",VEmpty()),(f"{yf}_{xf}_covx",VEmpty()),(f"{yf}_{yf}_covx",VEmpty())]
                else:
                    m,b,nn,mx,my,sxx,sxy,syy=ols_res
                    out += [(f"{xf}_{xf}_covx",VFloat(sxx/(n-1))),(f"{xf}_{yf}_covx",VFloat(sxy/(n-1))),(f"{yf}_{xf}_covx",VFloat(sxy/(n-1))),(f"{yf}_{yf}_covx",VFloat(syy/(n-1)))]
            elif acc=='linreg-pca':
                out.extend(self._pca_outputs(pairs,prefix))
            elif acc=='logireg':
                mm,bb=self._logireg(pairs)
                if mm is None:
                    out += [(f"{prefix}_logistic_m",VEmpty()),(f"{prefix}_logistic_b",VEmpty()),(f"{prefix}_logistic_n",VInt(n))]
                else:
                    out += [(f"{prefix}_logistic_m",VFloat(mm)),(f"{prefix}_logistic_b",VFloat(bb)),(f"{prefix}_logistic_n",VInt(n))]
        return out
    def _pca_outputs(self,pairs,prefix):
        n=len(pairs)
        if n<2: return [(f"{prefix}_pca_m",VEmpty()),(f"{prefix}_pca_b",VEmpty()),(f"{prefix}_pca_n",VInt(n)),(f"{prefix}_pca_quality",VEmpty())]
        mx=sum(x for x,y in pairs)/n; my=sum(y for x,y in pairs)/n
        sxx=sum((x-mx)**2 for x,y in pairs)/(n-1); syy=sum((y-my)**2 for x,y in pairs)/(n-1); sxy=sum((x-mx)*(y-my) for x,y in pairs)/(n-1)
        trace=sxx+syy; det=sxx*syy-sxy*sxy
        disc=max(trace*trace/4-det,0.0)
        l1=trace/2+math.sqrt(disc); l2=trace/2-math.sqrt(disc)
        if abs(sxy)>1e-300:
            vx=sxy; vy=l1-sxx
            norm=math.hypot(vx,vy); vx/=norm; vy/=norm
        else:
            if sxx>=syy: vx,vy=1.0,0.0
            else: vx,vy=0.0,1.0
        if vx<0 or (vx==0 and vy<0): vx,vy=-vx,-vy
        if vx==0:
            m=math.inf; b=math.nan
        else:
            m=vy/vx; b=my-m*mx
        quality=1-(l2/l1) if l1 else 0.0
        out=[(f"{prefix}_pca_m",VFloat(m)),(f"{prefix}_pca_b",VFloat(b)),(f"{prefix}_pca_n",VInt(n)),(f"{prefix}_pca_quality",VFloat(quality))]
        if _flag(self.cfg,'-v'):
            out += [(f"{prefix}_pca_eival1",VFloat(l1)),(f"{prefix}_pca_eival2",VFloat(l2)),(f"{prefix}_pca_eivec11",VFloat(vx)),(f"{prefix}_pca_eivec12",VFloat(vy)),(f"{prefix}_pca_eivec21",VFloat(-vy)),(f"{prefix}_pca_eivec22",VFloat(vx))]
        return out
    def _logireg(self,pairs):
        # One-step Newton from (0,0) approximates Miller's implementation (see probing); iterate a tiny epsilon adjustment to match its near-one-step values is not yet understood.
        n=len(pairs)
        if n==0: return None,None
        # Newton single step with p=0.5
        g0=sum(y-0.5 for x,y in pairs); g1=sum(x*(y-0.5) for x,y in pairs)
        h00=0.25*n; h01=0.25*sum(x for x,y in pairs); h11=0.25*sum(x*x for x,y in pairs)
        det=h00*h11-h01*h01
        if det==0: return None,None
        b=(h11*g0-h01*g1)/det; m=(-h01*g0+h00*g1)/det
        return m,b
    def _emit_iter(self, rec, ctx):
        gfields=_fields(self.cfg,'-g')
        if gfields and any(f not in rec for f in gfields):
            self.emit(rec,ctx); return
        if gfields:
            key=group_key_tuple(rec,gfields)
            records=[r for r,c in self.buf if all(f in r for f in gfields) and group_key_tuple(r,gfields)==key]
        else:
            records=[r for r,c in self.buf]
        out=OrderedDict(rec)
        for xf,yf in self.pairs:
            for k,v in self._compute_pair_outputs(records,xf,yf,f"{xf}_{yf}"):
                out[k]=v
        self.emit(out,ctx)
    def finish(self):
        if _flag(self.cfg,'-s'): return
        gfields,groups=self._group_records()
        if _flag(self.cfg,'--fit'):
            # compute per group parameters, then output original records in original order with fit fields
            params={}
            for k,(records,ctx,gvals) in groups.items():
                pdict={}
                for xf,yf in self.pairs:
                    pairs=_paired_numeric(records,xf,yf)
                    pdict[(xf,yf)]=pairs
                params[k]=pdict
            for rec,ctx in self.buf:
                out=OrderedDict(rec)
                if gfields and any(f not in rec for f in gfields):
                    self.emit(out,ctx); continue
                k=group_key_tuple(rec,gfields) if gfields else ()
                pdict=params.get(k,{})
                for xf,yf in self.pairs:
                    pairs=pdict.get((xf,yf),[])
                    prefix=f"{xf}_{yf}"
                    xv=rec.get(xf)
                    if 'linreg-ols' in self.accs:
                        res=_ols(pairs)
                        out[f"{prefix}_ols_fit"]=_stats_num(res[0]*xv.as_float()+res[1]) if res and xv is not None and xv.kind in (INT,FLOAT) else VEmpty()
                    if 'linreg-pca' in self.accs:
                        outs=dict(self._pca_outputs(pairs,prefix))
                        mm=outs.get(f"{prefix}_pca_m"); bb=outs.get(f"{prefix}_pca_b")
                        out[f"{prefix}_pca_fit"]=_stats_num(mm.as_float()*xv.as_float()+bb.as_float()) if mm is not None and mm.kind==FLOAT and xv is not None and xv.kind in (INT,FLOAT) else VEmpty()
                    if 'logireg' in self.accs:
                        mm,bb=self._logireg(pairs)
                        if mm is not None and xv is not None and xv.kind in (INT,FLOAT):
                            z=mm*xv.as_float()+bb
                            out[f"{prefix}_logistic_fit"]=VFloat(1/(1+math.exp(-z)) if z>-700 else 0.0)
                        else: out[f"{prefix}_logistic_fit"]=VEmpty()
                self.emit(out,ctx)
            return
        for k,(records,ctx,gvals) in groups.items():
            out=OrderedDict()
            for f in gfields: out[f]=gvals[f]
            for xf,yf in self.pairs:
                for kk,vv in self._compute_pair_outputs(records,xf,yf,f"{xf}_{yf}"):
                    out[kk]=vv
            self.emit(out,ctx)

def _stats_num(x):
    # stats2 m/b output showed 2 (not 2.0) for integral floats but float type prints same
    return VFloat(float(x))

