def _paired_numeric(records, xf,yf):
    pairs=[]
    for r in records:
        if xf in r and yf in r and r[xf].kind in (INT,FLOAT) and r[yf].kind in (INT,FLOAT):
            pairs.append((r[xf].as_float(), r[yf].as_float()))
    return pairs

def _ols(pairs):
    n=len(pairs)
    if n<2: return None
    mx=sum(x for x,y in pairs)/n; my=sum(y for x,y in pairs)/n
    sxx=sum((x-mx)**2 for x,y in pairs); sxy=sum((x-mx)*(y-my) for x,y in pairs); syy=sum((y-my)**2 for x,y in pairs)
    if sxx==0: return None
    m=sxy/sxx; b=my-m*mx
    return (m,b,n,mx,my,sxx,sxy,syy)

