# ---------- stats helpers ----------
STATS1_ACCS={'count','null_count','distinct_count','mode','antimode','sum','mean','mad','var','stddev','meaneb','skewness','kurtosis','min','max','minlen','maxlen','median'}
def _parse_stats1_accs(s):
    accs=[]
    for a in split_field_list(s):
        if a in STATS1_ACCS or re.match(r'^p[0-9]+(\.[0-9]+)?$',a):
            accs.append(a)
        else:
            # keep for merge-fields maybe error handled differently
            raise MlrError(f'stats1: accumulator "{a}" not found')
    return accs

def _present_values(records, field):
    return [r[field] for r in records if field in r]

def _stats1_compute(acc, vals, interpolate=False):
    # vals: present Values
    if acc=='count':
        return VInt(sum(1 for v in vals if v.kind not in (EMPTY,NULL,ERROR)))
    if acc=='null_count':
        return VInt(sum(1 for v in vals if v.kind in (EMPTY,NULL)))
    if acc=='distinct_count':
        return VInt(len(set(v.to_string() for v in vals)))
    if acc in ('mode','antimode'):
        if not vals: return VEmpty()
        counts={}; order=[]; first={}
        for v in vals:
            k=v.to_string()
            if k not in counts: counts[k]=0; first[k]=v; order.append(k)
            counts[k]+=1
        best=order[0]
        for k in order[1:]:
            if acc=='mode' and counts[k]>counts[best]: best=k
            if acc=='antimode' and counts[k]<counts[best]: best=k
        return first[best].copy()
    if acc in ('min','max'):
        cand=[v for v in vals if v.kind not in (ERROR,ARRAY,MAP,FUNCT)]
        if not cand: return VEmpty()
        best=cand[0]
        for v in cand[1:]:
            c=bifs._sort_cmp_default(v,best)
            if acc=='min' and c<0: best=v
            if acc=='max' and c>0: best=v
        return best.copy()
    if acc in ('minlen','maxlen'):
        if not vals: return VEmpty()
        lens=[len(v.to_string()) for v in vals]
        return VInt(min(lens) if acc=='minlen' else max(lens))
    if acc=='median' or re.match(r'^p[0-9]',acc):
        cand=[v for v in vals if v.kind not in (ERROR,ARRAY,MAP,FUNCT)]
        if not cand: return VEmpty()
        from functools import cmp_to_key
        sorted_vals=sorted(cand, key=cmp_to_key(bifs._sort_cmp_default))
        p=50.0 if acc=='median' else float(acc[1:])
        return bifs._percentile_value(sorted_vals,p,interpolate)
    # numeric accumulators
    nums=[]
    all_int=True
    for v in vals:
        if v.kind==INT: nums.append(float(v.val))
        elif v.kind==FLOAT: nums.append(v.val); all_int=False
    n=len(nums)
    if acc=='sum':
        if n==0: return VInt(0)
        if all_int:
            s=sum(int(v.val) for v in vals if v.kind==INT)
            return VInt(s) if INT64_MIN<=s<=INT64_MAX else VFloat(float(s))
        return VFloat(sum(nums))
    if n==0: return VEmpty()
    if acc=='mean':
        return bifs._num_result(sum(nums)/n, all_int)
    if acc=='mad':
        mu=sum(nums)/n; return VFloat(sum(abs(x-mu) for x in nums)/n)
    if acc in ('var','stddev','meaneb','skewness','kurtosis'):
        if n<2: return VEmpty()
        mu=sum(nums)/n
        if acc=='var': return VFloat(sum((x-mu)**2 for x in nums)/(n-1))
        if acc=='stddev': return VFloat(math.sqrt(sum((x-mu)**2 for x in nums)/(n-1)))
        if acc=='meaneb': return VFloat(math.sqrt(sum((x-mu)**2 for x in nums)/(n-1))/math.sqrt(n))
        if acc=='skewness':
            svar=sum((x-mu)**2 for x in nums)/(n-1); m3=sum((x-mu)**3 for x in nums)/n
            return VFloat(m3/(svar**1.5) if svar else math.nan)
        if acc=='kurtosis':
            m2=sum((x-mu)**2 for x in nums)/n; m4=sum((x-mu)**4 for x in nums)/n
            return VFloat(m4/(m2*m2)-3 if m2 else math.nan)
    return VEmpty()

def _dynamic_fields(buf, specified, regex_str, inverse_regex_str):
    if specified:
        return list(specified)
    pats=[]
    fields=[]
    if regex_str:
        pats=[compile_field_regex(p) for p in split_field_list(regex_str,keep_quotes=True)]
        for rec,ctx in buf:
            for k in rec.keys():
                if any(p.search(k) for p in pats) and k not in fields: fields.append(k)
