def _field_type(vals):
    types=[]
    for v in vals:
        if v.kind in (EMPTY,NULL): continue
        if v.kind not in types: types.append(v.kind)
    if not types: return 'null'
    if len(types)==1: return types[0]
    if set(types)=={INT,FLOAT}: return 'float'
    return 'mixed'

