        for gkey, idxs in groups.items():
            for f in self.fields:
                # numeric/original series with positions in group
                vals=[]  # list of (bufidx, Value or None)
                for idx in idxs:
                    rec=self.buf[idx][0]
                    vals.append((idx, rec.get(f)))
                # stateful counters ignoring non-present/non-numeric for most
                counter=0; rsum=None; rprod=None; prev_num=None; first_num=None; prev_any=None; ewmas=[None]*len(ewma_ds)
                for pos,(idx,v) in enumerate(vals):
                    out=outputs[idx]
                    is_num=v is not None and v.kind in (INT,FLOAT)
                    for acc in self.accs:
                        if acc.startswith('slwin'):
                            m=re.match(r'^slwin_([0-9]+)_([0-9]+)$',acc)
                            if not m: continue
                            back=int(m.group(1)); fwd=int(m.group(2))
                            window=[]
                            for pp in range(max(0,pos-back), min(len(vals), pos+fwd+1)):
                                vv=vals[pp][1]
                                if vv is not None and vv.kind in (INT,FLOAT): window.append(vv.as_float())
                            out[f"{f}_{back}_{fwd}"]=VFloat(sum(window)/len(window)) if window and is_num else (VFloat(sum(window)/len(window)) if window else VEmpty())
                            continue
                        if acc=='ewma':
                            for di,d in enumerate(ewma_ds):
                                name=ewma_names[di] if di<len(ewma_names) else str(d)
                                if is_num:
                                    ewmas[di]=v.as_float() if ewmas[di] is None else d*v.as_float()+(1-d)*ewmas[di]
                                    out[f"{f}_ewma_{name}"]=_stats_num(ewmas[di])
                            continue
                        name=f"{f}_{acc}"
                        if acc=='counter':
                            if v is not None:
                                counter+=1; out[name]=VInt(counter)
                            continue
                        if acc in ('shift','shift_lag'):
                            out[name]=prev_any.copy() if prev_any is not None else VEmpty()
                            continue
                        if acc=='shift_lead':
                            nxt=None
                            for pp in range(pos+1,len(vals)):
                                if vals[pp][1] is not None:
                                    nxt=vals[pp][1]; break
                            out[name]=nxt.copy() if nxt is not None else VEmpty()
                            continue
                        if not is_num:
                            continue
                        x=v.as_float(); xint=v.kind==INT
                        if acc=='delta':
                            if prev_num is None: out[name]=VInt(0) if xint else VFloat(0.0)
                            else:
                                # use DSL arith on original values for type preservation
                                out[name]=dslmod.eval_arith('-', v, prev_any_num_val)
                        elif acc=='rsum':
                            rsum=v.copy() if rsum is None else dslmod.eval_arith('+', rsum, v)
                            out[name]=rsum.copy()
                        elif acc=='rprod':
                            rprod=v.copy() if rprod is None else dslmod.eval_arith('*', rprod, v)
                            out[name]=rprod.copy()
                        elif acc=='ratio':
                            if prev_num is None: out[name]=VInt(1)
                            else: out[name]=dslmod.eval_arith('/', v, prev_any_num_val)
                        elif acc=='from-first':
                            if first_num is None: out[name]=VInt(0) if xint else VFloat(0.0)
                            else: out[name]=dslmod.eval_arith('-', v, first_num_val)
                    if v is not None:
                        prev_any=v
                    if is_num:
                        if first_num is None:
                            first_num=v.as_float(); first_num_val=v
                        prev_num=v.as_float(); prev_any_num_val=v
        for (rec,ctx),out in zip(self.buf,outputs):
