                            out[f"{f}_{back}_{fwd}"]=VFloat(sum(window)/len(window)) if window and is_num else (VFloat(sum(window)/len(window)) if window else VEmpty())
                            continue
                        if acc=='ewma':
                            for di,d in enumerate(ewma_ds):
                                name=ewma_names[di] if di<len(ewma_names) else str(d)
                                if is_num:
                                    ewmas[di]=v.as_float() if ewmas[di] is None else d*v.as_float()+(1-d)*ewmas[di]
                                    out[f"{f}_ewma_{name}"]=_stats_num(ewmas[di])
                            continue
                        name=f"{f}_{acc}"
