                            continue
                        if acc in ('shift','shift_lag'):
                            out[name]=prev_any.copy() if prev_any is not None else VEmpty()
                            continue
                        if acc=='shift_lead':
                            nxt=None
                            for pp in range(pos+1,len(vals)):
                                if vals[pp][1] is not None:
                                    nxt=vals[pp][1]; break
                            out[name]=nxt.copy() if nxt is not None else VEmpty()
                            continue
                        if not is_num:
                            continue
                        x=v.as_float(); xint=v.kind==INT
                        if acc=='delta':
                            if prev_num is None: out[name]=VInt(0) if xint else VFloat(0.0)
                            else:
                                # use DSL arith on original values for type preservation
                                out[name]=dslmod.eval_arith('-', v, prev_any_num_val)
                        elif acc=='rsum':
