def _frequent_common(buf, fields, n, suppress_counts, outname, least=False):
    # returns list records
    results=[]
    for f in fields:
        counts=OrderedDict(); first={}
        for rec,ctx in buf:
            if f not in rec: continue
            k=rec[f].to_string()
            if k not in counts: counts[k]=0; first[k]=(rec[f],ctx)
            counts[k]+=1
        items=list(counts.items())
        # sort by count desc (or asc for least), stable by first encounter for ties
        items_sorted=sorted(enumerate(items), key=lambda t: (t[1][1], t[0]) if least else (-t[1][1], t[0]))
        for _,(k,c) in items_sorted[:n]:
            rec=OrderedDict(); rec[f]=first[k][0].copy()
            if not suppress_counts: rec[outname]=VInt(c)
            results.append((rec,first[k][1]))
    return results

