        if '--evar' in cfg: self.explode=True; self.implode=False; self.values=True; self.pairs=False; self.across_records=True; self.nfs=cfg['--evar']
        if '--ivar' in cfg: self.implode=True; self.explode=False; self.values=True; self.pairs=False; self.across_records=True; self.nfs=cfg['--ivar']
