    def _explode_values_for(self,v):
        if v.kind==ARRAY: return [x.copy() for x in v.val]
        s=v.to_string()
        if s=='': return [VEmpty()]
        return [infer_value(p,self.opts.infer_opts()) for p in s.split(self.nfs)]
    def _explode_pairs_for(self,v):
        if v.kind==MAP: return [(k.to_plain_string(),val.copy()) for k,val in v.val.items()]
