        target=fields[0] if fields else None
        groups=OrderedDict()
        for rec,ctx in self.buf:
            key=tuple((k,v.to_string()) for k,v in rec.items() if k!=target)
            if key not in groups: groups[key]=([rec],ctx)
            else: groups[key][0].append(rec)
        for key,(records,ctx) in groups.items():
