@spec('reshape',{' -i':'value','-i':'value','-r':'multi','-o':'value','-s':'value'})
class ReshapeV(Base):
    def __init__(self,cfg,gctx):
        super().__init__(cfg,gctx); self.buf=[]
        self.long_to_wide='-s' in cfg
        if not self.long_to_wide and '-o' not in cfg: raise MlrError('mlr reshape: -o option is required')
    def process(self,rec,ctx):
        if self.long_to_wide:
            self.buf.append((copy_rec(rec),ctx)); return
        out_names=split_field_list(self.cfg['-o'])
        if len(out_names)!=2: raise MlrError('mlr reshape: -o must have key and value field names')
        keyf,valf=out_names
        if '-i' in self.cfg:
            infields=_fields(self.cfg,'-i')
        else:
            pats=[]
            rvals=self.cfg.get('-r',[])
            if not isinstance(rvals,list): rvals=[rvals]
            for rv in rvals: pats.append(compile_field_regex(rv))
            infields=[k for k in rec.keys() if any(p.search(k) for p in pats)]
        retained=[k for k in rec.keys() if k not in infields]
        for f in infields:
            if f not in rec: continue
            out=OrderedDict()
            for k in retained: out[k]=rec[k]
            out[keyf]=VString(f); out[valf]=rec[f]
            self.emit(out,ctx)
    def finish(self):
        if not self.long_to_wide: return
        pair=split_field_list(self.cfg['-s'])
        if len(pair)!=2: raise MlrError('mlr reshape: -s must have key and value field names')
        keyf,valf=pair
        groups=OrderedDict()
        for rec,ctx in self.buf:
            if keyf not in rec or valf not in rec: continue
            retained=[k for k in rec.keys() if k not in (keyf,valf)]
            gk=tuple((k,rec[k].to_string()) for k in retained)
            if gk not in groups:
                base=OrderedDict((k,rec[k].copy()) for k in retained)
                groups[gk]=(base,ctx,OrderedDict())
            groups[gk][2][rec[keyf].to_string()]=rec[valf].copy()
        for base,ctx,extra in groups.values():
            out=OrderedDict(base)
            for k,v in extra.items(): out[k]=v
            self.emit(out,ctx)

