        for f in fields:
            vals=[]
            for rec,ctx in self.buf:
                v=rec.get(f)
                if v is not None and v.kind in (INT,FLOAT): vals.append(v.as_float())
            vals_by_field[f]=vals; all_vals.extend(vals)
        if _flag(self.cfg,'--auto'):
            lo=min(all_vals) if all_vals else 0.0; hi=max(all_vals) if all_vals else 1.0
        else:
            lo=_float_opt(self.cfg,('--lo',),0.0); hi=_float_opt(self.cfg,('--hi',),1.0)
        if hi==lo: hi=lo+1
        width=(hi-lo)/nbins if nbins else (hi-lo)
        bins_by_field={}
        for f,vals in vals_by_field.items():
            bins=[0]*nbins
            for x in vals:
                if x<lo or x>hi: continue
                idx=int((x-lo)/(hi-lo)*nbins) if nbins else 0
                if idx>=nbins: idx=nbins-1
                bins[idx]+=1
            bins_by_field[f]=bins
        for i in range(nbins):
            rec=OrderedDict()
            rec[f"{prefix}bin_lo"]=VFloat(lo+i*width)
