class ReplWriterDest:
    def __init__(self, opts):
        self.opts=opts
        self.writer=fmtmod.Writer(opts, sys.stdout.buffer)
        self.fileobj=None; self.is_stdout=True
    def write(self, rec, ctx):
        self.writer.write(rec,ctx)
        try:
            (self.fileobj or sys.stdout.buffer).flush()
        except Exception: pass
    def set_dest(self, filename, append=False):
        try: self.writer.finish()
        except Exception: pass
        if self.fileobj is not None:
            try: self.fileobj.close()
            except Exception: pass
        self.fileobj=open(filename,'ab' if append else 'wb')
        self.is_stdout=False
        self.writer=fmtmod.Writer(self.opts, self.fileobj)
    def finish(self):
        try: self.writer.finish()
        except Exception: pass
        if self.fileobj is not None:
            try: self.fileobj.close()
            except Exception: pass

class Repl:
    def __init__(self, opts, gctx, args):
        self.opts=opts; self.gctx=gctx
        self.outdest=ReplWriterDest(opts)
