        self.prog=dslmod.DSLProgram('', gctx, opts)
        self.rt=self.prog.runtime
        self.rt.emit_callback=self._emit_cb
        self.rec=OrderedDict()
        self.ctx=RecCtx(0,0,'(stdin)',0)
        self.rt.rec=self.rec; self.rt.ctx=self.ctx
        self.persistent_scope={}
        self.rt.scopes=[self.persistent_scope]
        self.begin_blocks=[]; self.end_blocks=[]; self.main_stmts=[]
        self.filenames=[]; self.records=[]; self.rec_index=0; self.open_counter=0; self.global_nr=0
        self.ast_mode=None
        self.interactive=False
    def _emit_cb(self, rec, ctx, redir, rt):
        if redir is None:
            self.outdest.write(rec,ctx)
        else:
            if self.gctx.redirects is not None:
                self.gctx.redirects.write_record(redir, rec, ctx, self.opts)
    # ----- input records -----
    def open_files(self, filenames):
        # validate all exist first? Reference for nonexistent prints could not open and keeps prior? We'll attempt reads immediately; if fail, print and retain old.
        new_records=[]
