        for fn_i,path in enumerate(filenames):
            self.open_counter+=1
            filenum=self.open_counter
            try:
                data=fmtmod.read_input_bytes(path, self.opts)
            except Exception:
                sys.stdout.write(f'mlr repl: could not open "{path}"\n')
                self.open_counter-=len(filenames)-fn_i if False else 0
                return False
            text=data.decode('utf-8','surrogateescape')
