        self.filenames=list(filenames); self.records=new_records; self.rec_index=0
        return True
    def _next_record(self):
        if self.rec_index>=len(self.records):
            return None
        rec,ctx=self.records[self.rec_index]; self.rec_index+=1
        self.global_nr+=1
        ctx.nr=self.global_nr
        self.rec=OrderedDict((k,v.copy()) for k,v in rec.items())
        self.ctx=ctx
        self.rt.rec=self.rec; self.rt.ctx=self.ctx
        return rec
    # ----- DSL execution -----
    def _add_statements(self, stmts, save_main):
        main=[]
        for s in stmts:
            if s.kind=='funcdef':
                self.prog.funcs[s.name]=dslmod.UserFunction(s.name,s.params,s.rettype,s.body,False)
            elif s.kind=='subrdef':
                self.prog.subrs[s.name]=dslmod.UserFunction(s.name,s.params,s.rettype,s.body,True)
            elif s.kind=='begin':
                self.begin_blocks.append(s.body)
            elif s.kind=='end':
                self.end_blocks.append(s.body)
            else:
                main.append(s)
        if save_main:
            self.main_stmts.extend(main)
        return main
    def execute_snippet(self, text, save_main=False, print_bare=True):
        # parse
        parser=dslmod.Parser(text)
        stmts=parser.parse()
        if self.ast_mode:
            self._print_ast(stmts)
        main=self._add_statements(stmts,save_main)
        if save_main:
            return
        # execute main immediately in persistent scope
        self.rt.rec=self.rec; self.rt.ctx=self.ctx; self.rt.scopes=[self.persistent_scope]; self.rt.captures=None
        self.rt.filter_value=VAbsent()
        dslmod.exec_stmts(self.rt, main)
        if print_bare:
            fv=self.rt.filter_value
            if fv.kind!=ABSENT:
                sys.stdout.write(fv.to_string(self.opts.ofmt)+'\n')
    def execute_saved(self, which):
        self.rt.scopes=[{}] if which in ('begin','end') else [{}]
        self.rt.rec=self.rec if which=='main' else None
        self.rt.ctx=self.ctx; self.rt.captures=None
        blocks=[]
        if which=='begin': blocks=self.begin_blocks
        elif which=='end': blocks=self.end_blocks
        else:
            dslmod.exec_block(self.rt, self.main_stmts)
            self.rt.scopes=[self.persistent_scope]; self.rt.rec=self.rec; return
        for body in blocks:
            dslmod.exec_block(self.rt, body)
        self.rt.scopes=[self.persistent_scope]; self.rt.rec=self.rec
    def _print_ast(self, stmts):
        import verbs
        if self.ast_mode=='parex1':
            sys.stdout.write(ast_sexpr_root(stmts)+'\n')
        elif self.ast_mode=='parex':
            sys.stdout.write(pretty_sexpr(ast_sexpr_root(stmts))+'\n')
        elif self.ast_mode=='indent':
            sys.stdout.write(ast_indent_root(stmts)+'\n' if False else indent_ast(stmts))
    # ----- commands -----
    def do_command(self, line):
        # returns False to quit
        stripped=line.strip()
        if not stripped.startswith(':'):
            return True
        parts=stripped.split(None,1)
        cmd=COMMAND_ALIASES.get(parts[0],parts[0])
        rest=parts[1] if len(parts)>1 else ''
        if cmd==':quit': return False
        if cmd==':help': self.do_help(rest); return True
        if cmd==':context':
            c=self.ctx
            sys.stdout.write(f'FILENAME="{c.filename}",FILENUM={c.filenum},NR={c.nr},FNR={c.fnr}\n'); return True
        if cmd==':open':
            if not rest.strip(): return True
            self.open_files_streaming(rest.split()); return True
        if cmd==':reopen':
            if not self.filenames: sys.stdout.write('No open files\n')
            else: self.open_files_streaming(list(self.filenames))
            return True
        if cmd==':read':
            if not self.filenames and not self.records: sys.stdout.write('No open files\n')
            else: self._next_record()
            return True
        if cmd==':write':
            self.outdest.write(OrderedDict((k,v.copy()) for k,v in self.rec.items()),self.ctx); return True
        if cmd==':rw':
            if not self.filenames and not self.records: sys.stdout.write('No open files\n'); return True
            if self._next_record() is not None: self.outdest.write(OrderedDict((k,v.copy()) for k,v in self.rec.items()),self.ctx)
            return True
        if cmd in (':>',' :>>') or cmd==':>>':
            if rest.strip(): self.outdest.set_dest(rest.strip().split()[0], append=(cmd==':>>'))
            return True
        if stripped.startswith(':>>'):
            fn=stripped[3:].strip(); self.outdest.set_dest(fn,append=True); return True
        if stripped.startswith(':>'):
            fn=stripped[2:].strip(); self.outdest.set_dest(fn,append=False); return True
        if cmd==':skip':
            self.do_skip(rest, process=False); return True
        if cmd==':process':
            self.do_skip(rest, process=True); return True
        if cmd==':begin': self.execute_saved('begin'); return True
        if cmd==':main': self.execute_saved('main'); return True
        if cmd==':end': self.execute_saved('end'); return True
        if cmd==':blocks':
            sys.stdout.write(f"#begin {len(self.begin_blocks)}\n#main  {len(self.main_stmts)}\n#end   {len(self.end_blocks)}\n"); return True
        if cmd==':resetblocks':
            which=rest.strip()
            if which=='begin': self.begin_blocks=[]
            elif which=='main': self.main_stmts=[]
            elif which=='end': self.end_blocks=[]
            else: self.begin_blocks=[]; self.main_stmts=[]; self.end_blocks=[]
            return True
        if cmd==':load':
            if not rest.strip():
                sys.stdout.write(REPL_HELP.get(':load','')); return True
            import glob
            for path in rest.split():
                files=sorted(glob.glob(os.path.join(path,'*.mlr'))) if os.path.isdir(path) else [path]
                for fpath in files:
                    try: text=open(fpath).read()
                    except Exception: sys.stdout.write(f'mlr repl: could not open "{fpath}"\n'); continue
                    try:
                        stmts=dslmod.Parser(text).parse()
                        self._add_statements(stmts,save_main=True)
                    except dslmod.ParseError as e:
                        sys.stderr.write(e.format())
            return True
        if cmd==':astprint':
            mode=rest.strip()
            if not mode:
                sys.stdout.write(REPL_HELP.get(':astprint','')); return True
            if mode=='none': self.ast_mode=None
            elif mode in ('parex','parex1','indent'): self.ast_mode=mode
            return True
        sys.stdout.write(f"REPL verb {parts[0]} not found.\n"); return True
    def do_skip(self, rest, process=False):
        if not self.filenames and not self.records:
            sys.stdout.write('No open files\n'); return
        rest=rest.strip()
        if not rest:
            topic=":skip" if not process else ":process"
            # In reference, bare :skip with open files prints its usage section; extract from repl-details
            sys.stdout.write(extract_command_help(':skip' if not process else ':process')); return
        until_expr=None; count=None
        if rest=='until intr' or rest=='u intr':
            count=10**18
        elif rest.startswith('until '): until_expr=rest[6:]
        elif rest.startswith('u '): until_expr=rest[2:]
        else:
            try: count=int(rest.split()[0])
            except: until_expr=rest
        done=0
        while True:
            if count is not None and done>=count: break
            rec=self._next_record()
            if rec is None: break
            done+=1
            if process:
                self.execute_saved('main')
                self.outdest.write(OrderedDict((k,v.copy()) for k,v in self.rec.items()),self.ctx)
            if until_expr is not None:
                # evaluate expr as a bare expression in persistent runtime
                try:
                    stmts=dslmod.Parser(until_expr).parse()
                    self.rt.rec=self.rec; self.rt.ctx=self.ctx; self.rt.scopes=[self.persistent_scope]; self.rt.filter_value=VAbsent()
                    main=self._add_statements(stmts,save_main=False)
                    dslmod.exec_stmts(self.rt,main)
                    if self.rt.filter_value.kind==BOOL and self.rt.filter_value.val: break
                except Exception:
                    break
    def do_help(self, rest):
        rest=rest.strip()
        if not rest:
            sys.stdout.write(REPL_HELP.get(':help','')); return
        if rest.startswith('find '):
            term=rest[5:].strip(); self.help_find(term); return
        key=':help '+rest
        if key in REPL_HELP:
            sys.stdout.write(REPL_HELP[key]); return
        # name lookup functions/keywords
        res=''
        if rest in helpmod.DATA.get('function_help',{}): res+=helpmod.DATA['function_help'][rest]
        if rest in helpmod.DATA.get('keyword_help',{}): res+=helpmod.DATA['keyword_help'][rest]
        if res: sys.stdout.write(res); return
        sys.stdout.write(extract_command_help(rest) or f'No help found for "{rest}".\n')
    def help_find(self, term):
        out=[]
        for kw,txt in helpmod.DATA.get('keyword_help',{}).items():
            if term in kw: out.append(txt)
        for fn,txt in helpmod.DATA.get('function_help',{}).items():
            if term in fn: out.append(txt)
        sys.stdout.write(''.join(out))

def extract_command_help(name):
    # sections in repl-details separated by blank lines starting with :name
    text=REPL_HELP.get(':help repl-details','')
    # find heading line equal to name or starting name
    lines=text.splitlines(True)
    start=None
    for i,ln in enumerate(lines):
        if ln.strip()==name or ln.startswith(name+' ') or ln.startswith(name+'\n'):
            start=i; break
    if start is None: return ''
    end=len(lines)
    for j in range(start+1,len(lines)):
        if lines[j].startswith(':') and lines[j].rstrip().find(' ')==-1:
            pass
    # Sections are separated by an empty line followed by a line beginning ':'
    out=[]; 
    for j in range(start,len(lines)):
        if j>start and lines[j].startswith(':') and (j==0 or lines[j-1].strip()=='' ):
            end=j; break
    return ''.join(lines[start:end])

def ast_sexpr_root(stmts):
    import verbs
    return verbs.ast_to_sexpr(stmts)

def pretty_sexpr(s):
    # tokenize sexpr and pretty format: a node stays inline if none of its direct children is a list containing a list.
    toks=re.findall(r'\(|\)|[^\s()]+',s)
    pos=0
    def parse():
        nonlocal pos
        if toks[pos]=='(':
            pos+=1; items=[]
            while toks[pos]!=')':
                items.append(parse())
            pos+=1; return items
        else:
            t=toks[pos];pos+=1;return t
    tree=parse()
    def inline(node):
        if not isinstance(node,list): return str(node)
        return '('+' '.join(inline(x) for x in node)+')'
    def has_nested(node):
        return any(isinstance(x,list) and any(isinstance(y,list) for y in x) for x in node[1:]) if isinstance(node,list) else False
    def fmt(node,indent):
        if not isinstance(node,list): return str(node)
        if not has_nested(node): return inline(node)
        lines=['('+str(node[0])]
        for child in node[1:]:
            lines.append(' '*(indent+4)+fmt(child,indent+4))
        lines.append(' '*indent+')')
        return '\n'.join(lines)
    return fmt(tree,0)

def indent_ast(stmts):
    # Use dsl AST printer implementation in dsl module if available else sexpr fallback
    if hasattr(dslmod,'ast_indent'):
        return dslmod.ast_indent(stmts)
    # fallback simple
    return ast_sexpr_root(stmts)+'\n'

def run_repl(args, base_opts):
