            if i<len(args): i+=1
            continue
        if a.startswith('-'):
            # global flag (may have value)
            base=a.split('=',1)[0] if a.startswith('--') else a
            kind=cliparse.global_flag_kind(base)
            if kind is None:
                sys.stderr.write(f'mlr: option "{a}" not recognized.\nPlease run "mlr --help" for usage information.\n'); return 1
            if kind=='value':
                if '=' in a and a.startswith('--'): val=a.split('=',1)[1]; i+=1
                else:
                    if i+1>=len(args): sys.stderr.write(f'mlr: option "{a}" missing argument(s).\n'); return 1
                    val=args[i+1]; i+=2
