    files=state.get('from_files',[])+files
    gctx=GlobalCtx(opts)
    from gorand import GoRand
    import time as _t
    gctx.rng=GoRand(opts.seed if opts.seed is not None else (_t.time_ns() & ((1<<63)-1)))
    gctx.redirects=fmtmod.RedirectManager(gctx)
    repl=Repl(opts,gctx,args)
    repl.ast_mode=ast_mode
