    ps2=os.environ.get('MLR_REPL_PS2','... ')
    if interactive and show_banner:
        sys.stdout.write("Miller 6.16.0 REPL for linux/amd64/go1.24.0\nDocs: https://miller.readthedocs.io\nType ':h' or ':help' for online help; ':q' or ':quit' to quit.\n"); sys.stdout.flush()
    multiline=None; save_multiline=False
    while True:
        if interactive and show_prompts:
            sys.stdout.write(ps2 if multiline is not None else ps1); sys.stdout.flush()
        try:
            line=sys.stdin.readline()
        except KeyboardInterrupt:
            sys.stdout.write('\n'); multiline=None; continue
        if line=='':
            break
        line=line.rstrip('\n')
        if multiline is not None:
            endmark='>>' if save_multiline else '>'
            if line.strip()==endmark:
