                except MlrRawError as e: sys.stderr.write(str(e))
                except MlrError as e: sys.stderr.write(f"mlr: {e}\n")
                except Exception as e: sys.stderr.write(f"mlr: {e}\n")
                continue
            multiline.append(line); continue
        s=line.strip()
        if s=='<':
            multiline=[]; save_multiline=False; continue
        if s=='<<':
            multiline=[]; save_multiline=True; continue
        if s.startswith('??'):
            repl.help_find(s[2:].strip()); continue
        if s.startswith('?'):
            repl.do_help(s[1:].strip()); continue
        if s.startswith(':'):
            try:
                cont=repl.do_command(line)
            except MlrRawError as e:
                sys.stderr.write(str(e)); cont=True
            except MlrError as e:
                sys.stderr.write(f"mlr: {e}\n"); cont=True
            except Exception as e:
                sys.stderr.write(f"mlr: {e}\n"); cont=True
            if not cont: break
