        try:
            repl.execute_snippet(line)
        except dslmod.ParseError as e:
            sys.stderr.write(e.format())
        except MlrRawError as e:
            sys.stderr.write(str(e))
        except MlrError as e:
            sys.stderr.write(f"mlr: {e}\n")
        except Exception as e:
            sys.stderr.write(f"mlr: {e}\n")
    repl.outdest.finish()
    if gctx.redirects: gctx.redirects.finish()
    return 0
