    import time
    def tmp(data):
        path=f"/tmp/mlr-temp{random.randint(100000000,9999999999)}"
        open(path,'wb').write(data); return path
    p1=tmp(exp); p2=tmp(act)
    r=subprocess.run(['diff','-u',p1,p2],capture_output=True)
    try: os.remove(p1); os.remove(p2)
    except: pass
    return r.stdout.decode('utf-8','surrogateescape')

