def extract_command_help(name):
    # sections in repl-details separated by blank lines starting with :name
    text=REPL_HELP.get(':help repl-details','')
    # find heading line equal to name or starting name
    lines=text.splitlines(True)
    start=None
    for i,ln in enumerate(lines):
        if ln.strip()==name or ln.startswith(name+' ') or ln.startswith(name+'\n'):
            start=i; break
    if start is None: return ''
    end=len(lines)
    for j in range(start+1,len(lines)):
        if lines[j].startswith(':') and lines[j].rstrip().find(' ')==-1:
            pass
    # Sections are separated by an empty line followed by a line beginning ':'
    out=[]; 
    for j in range(start,len(lines)):
        if j>start and lines[j].startswith(':') and (j==0 or lines[j-1].strip()=='' ):
            end=j; break
    return ''.join(lines[start:end])

def ast_sexpr_root(stmts):
    import verbs
    return verbs.ast_to_sexpr(stmts)

def pretty_sexpr(s):
    # tokenize sexpr and pretty format: a node stays inline if none of its direct children is a list containing a list.
    toks=re.findall(r'\(|\)|[^\s()]+',s)
    pos=0
    def parse():
        nonlocal pos
        if toks[pos]=='(':
            pos+=1; items=[]
            while toks[pos]!=')':
                items.append(parse())
            pos+=1; return items
        else:
            t=toks[pos];pos+=1;return t
    tree=parse()
    def inline(node):
        if not isinstance(node,list): return str(node)
        return '('+' '.join(inline(x) for x in node)+')'
    def has_nested(node):
        return any(isinstance(x,list) and any(isinstance(y,list) for y in x) for x in node[1:]) if isinstance(node,list) else False
    def fmt(node,indent):
        if not isinstance(node,list): return str(node)
        if not has_nested(node): return inline(node)
        lines=['('+str(node[0])]
        for child in node[1:]:
            lines.append(' '*(indent+4)+fmt(child,indent+4))
        lines.append(' '*indent+')')
        return '\n'.join(lines)
    return fmt(tree,0)

