def ast_indent(stmts):
    lines=[]
    def add(depth,label):
        lines.append('    '*depth+f'* {label}')
    def q(s):
        return '"'+str(s).replace('\\','\\\\').replace('"','\\"')+'"'
    def expr(n,depth):
        k=n.kind
        if k=='field': add(depth,f'direct field value {q(n.name)}')
        elif k=='oosvar': add(depth,f'direct oosvar value {q(n.name)}')
        elif k=='fullrec': add(depth,'full record "$*"')
        elif k=='fulloos': add(depth,'full oosvar "@*"')
        elif k=='name': add(depth,f'local variable {q(n.name)}')
        elif k=='intlit': add(depth,f'int literal {q(n.value.to_string())}')
        elif k=='floatlit': add(depth,f'float literal {q(n.value.to_string())}')
        elif k=='stringlit': add(depth,f'string literal {q(n.value)}')
        elif k=='boollit': add(depth,f'bool literal {q("true" if n.value else "false")}')
        elif k=='nulllit': add(depth,'null literal "null"')
        elif k=='ctxvar':
            if n.name=='ENV': add(depth,'environment variable "ENV"')
            else: add(depth,f'context variable {q(n.name)}')
        elif k=='index':
            if n.base.kind=='ctxvar' and n.base.name=='ENV':
                add(depth,'environment variable "ENV"'); expr(n.index,depth+1)
            else:
                add(depth,'array or map index access "[]"'); expr(n.base,depth+1); expr(n.index,depth+1)
        elif k=='slice':
            add(depth,'array-slice access "[]"'); expr(n.base,depth+1)
            if n.lo is not None: expr(n.lo,depth+1)
            if n.hi is not None: expr(n.hi,depth+1)
        elif k=='keyatpos':
            add(depth,'positionally-indexed map key "[]"'); expr(n.base,depth+1); expr(n.index,depth+1)
        elif k=='valatpos':
            add(depth,'positionally-indexed map value "[]"'); expr(n.base,depth+1); expr(n.index,depth+1)
        elif k=='reckeyatpos':
            add(depth,'positionally-indexed map key "[]"'); add(depth+1,'full record "$*"'); expr(n.index,depth+1)
        elif k=='recvalatpos':
            add(depth,'positionally-indexed map value "[]"'); add(depth+1,'full record "$*"'); expr(n.index,depth+1)
        elif k=='binary':
            add(depth,f'operator {q(n.op)}'); expr(n.left,depth+1); expr(n.right,depth+1)
        elif k=='unary':
            add(depth,f'operator {q(n.op)}'); expr(n.operand,depth+1)
        elif k=='ternary':
            add(depth,'operator "?:"'); expr(n.cond,depth+1); expr(n.then,depth+1); expr(n.els,depth+1)
        elif k=='call':
            add(depth,f'function callsite {q(n.name)}')
            for a in n.args: expr(a,depth+1)
        elif k=='arraylit':
            add(depth,'array literal "[]"')
            for a in n.elems: expr(a,depth+1)
        elif k=='maplit':
            add(depth,'map literal "{}"')
            for kk,vv in n.entries:
                add(depth+1,'map-literal key-value pair ":"'); expr(kk,depth+2); expr(vv,depth+2)
        elif k=='funclit':
            add(depth,f'function literal {q(n.name)}')
            add(depth+1,'parameter list')
            for vt,pn in n.params:
                add(depth+2,'parameter'); add(depth+3,f'parameter name {q(pn)}')
            block(n.body,depth+1)
        else:
            add(depth,k)
    def target_expr(n,depth,decl_type=None):
        # declarations show type declaration child under local variable
        expr(n,depth)
        if decl_type:
            lines.append('    '*(depth+1)+f'* type declaration {q(decl_type)}')
    def stmt(n,depth):
        k=n.kind
        if k=='assign':
            add(depth,'assignment "="')
            if n.op=='=':
                target_expr(n.target,depth+1); expr(n.rhs,depth+1)
            else:
                target_expr(n.target,depth+1)
                bop=n.op[:-1]
                add(depth+1,f'operator {q(bop)}'); expr(n.target,depth+2); expr(n.rhs,depth+2)
        elif k=='decl':
            add(depth,'assignment "="')
            # local variable node synthetic
            add(depth+1,f'local variable {q(n.name)}')
            add(depth+2,f'type declaration {q(n.vartype)}')
            expr(n.rhs,depth+1)
        elif k=='exprstmt':
            add(depth,'bare boolean'); expr(n.expr,depth+1)
        elif k=='if':
            add(depth,'if-chain')
            for idx,(cond,body) in enumerate(n.branches):
                add(depth+1,f'if-item {q("if" if idx==0 else "elif")}'); expr(cond,depth+2); block(body,depth+2)
            if n.else_body is not None:
                add(depth+1,'if-item "else"'); block(n.else_body,depth+2)
        elif k=='condblock':
            add(depth,'conditional block'); expr(n.cond,depth+1); block(n.body,depth+1)
        elif k=='while':
            add(depth,'while loop "while"'); expr(n.cond,depth+1); block(n.body,depth+1)
        elif k=='dowhile':
            add(depth,'do-while loop "while"'); block(n.body,depth+1); expr(n.cond,depth+1)
        elif k=='forin':
            if len(n.names)==1:
                add(depth,'single-variable for-loop "for"')
                add(depth+1,f'local variable {q(n.names[0])}')
            else:
                add(depth,'double-variable for-loop "for"')
                add(depth+1,f'local variable {q(n.names[0])}'); add(depth+1,f'local variable {q(n.names[1])}')
            expr(n.coll,depth+1); block(n.body,depth+1)
        elif k=='forinmulti':
            add(depth,'multi-variable for-loop "for"')
            for nm in n.knames: add(depth+1,f'local variable {q(nm)}')
            add(depth+1,f'local variable {q(n.vname)}'); expr(n.coll,depth+1); block(n.body,depth+1)
        elif k=='forc':
            add(depth,'triple-for loop "for"')
            block(n.init,depth+1)
            # cond as statement block with bare boolean
            add(depth+1,'statement block')
            if n.cond is not None:
                add(depth+2,'bare boolean'); expr(n.cond,depth+3)
            block(n.incr,depth+1); block(n.body,depth+1)
        elif k=='begin':
            add(depth,'begin block'); block(n.body,depth+1)
        elif k=='end':
            add(depth,'end block'); block(n.body,depth+1)
        elif k in ('funcdef','subrdef'):
            add(depth,f'{"function" if k=="funcdef" else "subroutine"} definition {q(n.name)}')
            add(depth+1,'parameter list')
            for vt,pn in n.params:
                add(depth+2,'parameter'); add(depth+3,f'parameter name {q(pn)}')
            block(n.body,depth+1)
        elif k=='return':
            add(depth,'return "return"')
            if n.expr is not None: expr(n.expr,depth+1)
        elif k in ('print','printn','eprint','eprintn'):
            add(depth,f'print statement {q(k)}')
            add(depth+1,'function callsite')
            for a in n.args: expr(a,depth+2)
            add(depth+1,'no-op')
        elif k=='unset':
            add(depth,'unset "unset"')
            for t in n.targets: expr(t,depth+1)
        elif k in ('emit','emitp','emitf','emit1'):
            add(depth,f'emit statement {q(k)}')
            add(depth+1,'emittable list')
            for a in n.args: expr(a,depth+2)
            add(depth+1,'no-op'); add(depth+1,'no-op')
        elif k=='filterstmt':
            add(depth,'filter statement "filter"'); expr(n.expr,depth+1)
        elif k=='callstmt':
            add(depth,f'subroutine call {q(n.name)}')
            for a in n.args: expr(a,depth+1)
        elif k in ('dump','edump'):
            add(depth,f'{k} statement "{k}"')
        elif k=='break': add(depth,'break "break"')
        elif k=='continue': add(depth,'continue "continue"')
        else:
            add(depth,k)
    def block(body,depth):
        add(depth,'statement block')
        for s in body: stmt(s,depth+1)
    block(stmts,0)
    return '\n'.join(lines)+'\n'
