def pretty_sexpr(s):
    toks=re.findall(r'\(|\)|[^\s()]+',s)
    pos=0
    def parse():
        nonlocal pos
        if pos<len(toks) and toks[pos]=='(':
            pos+=1; items=[]
            while pos<len(toks) and toks[pos]!=')':
                items.append(parse())
            if pos<len(toks): pos+=1
            return items
        t=toks[pos] if pos<len(toks) else ''; pos+=1; return t
    tree=parse()
    def inline(node):
        if not isinstance(node,list): return str(node)
        return '('+' '.join(inline(x) for x in node)+')'
    def has_list_child(node):
        return any(isinstance(x,list) for x in node[1:]) if isinstance(node,list) else False
    def fmt(node,indent):
        if not isinstance(node,list): return str(node)
        if not has_list_child(node): return inline(node)
        lines=['('+str(node[0])]
        for child in node[1:]:
            lines.append(' '*(indent+4)+fmt(child,indent+4))
        lines.append(' '*indent+')')
        return '\n'.join(lines)
    return fmt(tree,0)
