def collect_warnings(program):
    warnings=[]
    func_names=set(program.funcs)|set(program.subrs)
    def warn_name(n, assigned):
        if n.name not in assigned and n.name not in func_names:
            line,col=node_pos(n)
            warnings.append(f"Variable name {n.name} might not have been assigned yet at DSL expression line {line} column {col}.")
    def analyze_expr(n, assigned):
        if n is None: return
        if isinstance(n,(list,tuple)):
            for x in n: analyze_expr(x,assigned)
            return
        if not isinstance(n,Node): return
        k=n.kind
        if k=='name':
            warn_name(n,assigned); return
        if k=='binary' and n.op=='.':
            analyze_expr(n.left,assigned)
            if n.right.kind!='name': analyze_expr(n.right,assigned)
            return
        if k=='funclit':
            nf=set(pn for vt,pn in n.params)
            analyze_block(n.body,nf)
            return
        if k=='index' and n.base.kind=='ctxvar':
            analyze_expr(n.index,assigned); return
        for attr,val in n.__dict__.items():
            if attr in ('kind','tok','value','name','op','vartype','ci'): continue
            analyze_expr(val,assigned)
    def analyze_target(t, assigned, is_compound=False):
        if not isinstance(t,Node): return
        if t.kind=='name':
            if is_compound: warn_name(t,assigned)
            return
        if t.kind=='index':
            analyze_expr(t.index,assigned)
            if t.base.kind not in ('name','field','oosvar','fullrec','fulloos'):
                analyze_target(t.base,assigned,True)
            return
        if t.kind=='binary' and t.op=='.':
            analyze_target(t.left,assigned,is_compound)
            if t.right.kind!='name': analyze_expr(t.right,assigned)
            return
        if t.kind in ('field','oosvar','fullrec','fulloos','oosbyexpr','reckeyatpos','recvalatpos'):
            idx=getattr(t,'index',None)
            if idx is not None: analyze_expr(idx,assigned)
            return
        analyze_expr(t,assigned)
    def mark_target(t,assigned):
        if not isinstance(t,Node): return
        if t.kind=='name': assigned.add(t.name)
        elif t.kind=='index': mark_target(t.base,assigned)
        elif t.kind=='binary' and t.op=='.': mark_target(t.left,assigned)
    def analyze_stmt(s,assigned):
        k=s.kind
        if k=='assign':
            analyze_expr(s.rhs,assigned)
            analyze_target(s.target,assigned,is_compound=(s.op!='='))
            mark_target(s.target,assigned); return
        if k=='decl':
            analyze_expr(s.rhs,assigned); assigned.add(s.name); return
        if k=='exprstmt': analyze_expr(s.expr,assigned); return
        if k=='if':
            for cond,body in s.branches:
                analyze_expr(cond,assigned); analyze_block(body,set(assigned))
            if s.else_body is not None: analyze_block(s.else_body,set(assigned))
            return
        if k=='condblock':
            analyze_expr(s.cond,assigned); analyze_block(s.body,set(assigned)); return
        if k in ('while','dowhile'):
            analyze_expr(s.cond,assigned); analyze_block(s.body,set(assigned)); return
        if k=='forin':
            analyze_expr(s.coll,assigned)
            inner=set(assigned); inner.update(s.names); analyze_block(s.body,inner); return
        if k=='forinmulti':
            analyze_expr(s.coll,assigned)
            inner=set(assigned); inner.update(s.knames); inner.add(s.vname); analyze_block(s.body,inner); return
        if k=='forc':
            inner=set(assigned)
            for st in s.init: analyze_stmt(st,inner)
            if s.cond is not None: analyze_expr(s.cond,inner)
            analyze_block(s.body,set(inner))
            for st in s.incr: analyze_stmt(st,set(inner))
            return
        if k in ('funcdef','subrdef'):
            nf=set(pn for vt,pn in s.params); analyze_block(s.body,nf); return
        if k=='return':
            if s.expr is not None: analyze_expr(s.expr,assigned)
            return
        if k=='unset':
            for t in s.targets: analyze_target(t,assigned,False)
            return
        if k in ('begin','end'):
            analyze_block(s.body,set()); return
        # generic: analyze expression-like children in order, and nested statement lists
        for attr,val in s.__dict__.items():
            if attr in ('kind','tok'): continue
            if isinstance(val,list) and val and all(isinstance(x,Node) for x in val) and val[0].kind in ('assign','decl','exprstmt','if','forin','forc','while','print','return'):
                analyze_block(val,set(assigned))
            else:
                analyze_expr(val,assigned)
    def analyze_block(stmts,assigned):
        for s in stmts: analyze_stmt(s,assigned)
    for body in program.begin_blocks:
        analyze_block(body,set())
    analyze_block(program.main_stmts,set())
    for body in program.end_blocks:
        analyze_block(body,set())
    # top-level function bodies are in all_stmts but main excludes them; analyze them
    for s in program.all_stmts:
        if s.kind in ('funcdef','subrdef'):
            analyze_stmt(s,set())
    return warnings
